// ==========================================
// ★ K 의 방 — C등급 직업 갈림길 · 파괴
// 전사 · 화염술사 · 권사 · 폭파공 · 대검사
// 파괴: 다시 붙는 것 · 자라는 것 · 있어서는 안 될 것을 부수고 잡는다
// ==========================================

// ------------------------------------------
// 전사 · 무력
// ------------------------------------------
kJob('warrior', 'C', [

{ at:'C', t:'통로 — 한 번 더 일어난 것',
  x:`아까 쓰러뜨린 것이 일어났다.<br><br>
    목을 쳤다. 손에 남은 감촉으로는 끝난 싸움이었다. 뼈 갈리는 소리도 들었다.<br>
    그것이 고개를 반쯤 덜렁거리며 다시 선다. 벌어진 목이 아래에서부터 천천히 닫힌다.<br><br>
    무기 쥔 손이 아직 아까 감촉을 기억한다. 그 감촉이 틀렸다.`,
  o:[
    { l:'① 닫히기 전에 같은 자리를 다시 친다.', k:'break', dc:15, wake:1,
      ok:`닫히는 자리에 날을 다시 넣었다. 한 번, 또 한 번. 셋째에 머리가 바닥에 떨어졌다.<br><br>몸이 머리를 찾아 손을 더듬는다. 그 손도 쳤다. 더듬는 것이 멈출 때까지.<br>멈추고도 숨 열 번을 기다렸다. 그제야 무기를 내렸다.<br><br>쓰러지는 것과 끝나는 것은 다르다. 손이 그걸 새로 배웠다. 이제부터 치고 나면 숨을 센다. 세는 동안 손은 내려가지 않는다.`,
      ng:`날이 닫히는 살에 물렸다. 빠지지 않는다.<br><br>그것이 무기째 이쪽으로 걸어온다. 손을 놓을 수도 없다.<br>동료가 옆에서 쳐서 겨우 떨어졌다. 팔뚝에 손톱자국이 길게 났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 물러서서 그것이 어떻게 붙는지 본다.', k:'gaze', dc:14,
      ok:`두 걸음 물러섰다. 무기는 낮게.<br><br>닫히는 것은 목만이 아니다. 아까 벤 데가 전부 닫힌다. 발에서 머리 쪽으로, 차례대로.<br>그러면 발이 먼저다. 발목을 쳤다. 그것이 무너지고 다시는 안 섰다.<br><br>어디가 먼저 낫는지 보면 어디를 먼저 쳐야 하는지 안다.`,
      ng:`보는 사이 목이 다 닫혔다.<br><br>그것이 이쪽을 본다. 아까보다 눈이 맑다.<br>한 번 죽어 본 것은 두 번째에 더 조심한다. 팔을 물리고 나서야 떼어 냈다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C1', t:'도축장 — 레일 위의 갈고리',
  x:`천장 레일에 갈고리가 줄지어 걸려 있다. 비었다.<br><br>
    레일이 돈다. 아무도 돌리지 않는데 돈다. 갈고리가 사람 목 높이로 하나씩 지나간다.<br>
    지나가면서 사람 쪽으로 조금씩 기운다. 바람 때문이 아니다.<br><br>
    휘두르는 것에는 박자가 있다. 싸우는 사람은 그걸 몸으로 센다. 이 박자는 고르지 않다.`,
  o:[
    { l:'① 갈고리를 쳐서 레일에서 떨군다.', k:'break', dc:15,
      doom:{ title:'도는 레일', what:'갈고리에 걸려 레일에 끌려갑니다', dc:15, sec:60,
        text:`제일 가까운 갈고리를 쳤다. 떨어졌다.<br><br>다음 갈고리가 그 빈자리를 메우러 빨라졌다. 무기를 거두기 전에 어깨에 걸렸다.<br>발이 바닥에서 뜬다. 레일이 이쪽을 싣고 돈다. 다음 칸 쪽으로.<br><br>다음 칸에서 칼 가는 소리가 난다.`,
        dieText:`레일은 하루에 한 바퀴를 돈다.<br><br>그 바퀴에 빈 갈고리가 하나 줄었다.<br>대신 갈고리 하나가 무겁다. 아무도 돌리지 않는데, 레일은 그 무게만큼 천천히 돈다.` },
      ok:`가까운 갈고리를 쳤다. 떨어졌다. 다음 것이 빨라진다. 그것도 쳤다.<br><br>넷을 떨구자 레일이 멈칫했다. 빈 칸이 넷이면 도는 게 무겁다.<br>그 틈에 다들 아래를 지나갔다.<br><br>떨어진 갈고리가 바닥에서 꿈틀댄다. 밟아서 휘었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 무력을 쓴다 — 갈고리 하나를 붙잡아 레일을 세운다.', k:'steady', dc:14, cost:{ might:18 },
      ok:`지나가는 갈고리를 두 손으로 잡았다. 무력을 발바닥까지 내렸다.<br><br>레일이 끌어간다. 버텼다. 바닥 타일이 신발 밑에서 갈린다.<br>레일이 섰다. 다들 줄줄이 빠져나갔다. 마지막 사람이 지난 다음에 놓았다.<br><br>손바닥에 녹이 박혔다. 갈고리가 놓친 게 아쉽다는 듯 한참 떨었다.`,
      ng:`잡기는 잡았다. 레일이 생각보다 셌다.<br><br>세 걸음 끌려갔다. 손을 놓자 갈고리가 등을 긁고 지나갔다.<br>옷이 찢어졌다. 그 아래도.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6, might:-5 } },
    { l:'③ 박자 사이로 숙이고 지난다.', k:'evade', dc:14,
      ok:`고르지 않은 박자를 오래 봤다. 고르지 않아도 되풀이는 된다. 셋 빠르고 하나 느리다.<br><br>느린 것 밑으로 들어갔다. 다들 따라오게 손짓했다.<br>머리 위로 갈고리가 지나간다. 누구 머리카락이 걸렸다가 풀렸다.<br><br>세는 걸 멈추지 않았다. 다 지날 때까지.`,
      ng:`셋째에 숙였는데 그게 느린 것이었다.<br><br>일어서는 머리 위로 빠른 것이 왔다. 귀를 스쳤다.<br>귀에서 뜨거운 게 목으로 흐른다. 갈고리 끝에 무엇이 걸려 갔는지는 안 봤다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 발목의 인형',
  x:`작업대 밑에서 무언가 발목을 물었다.<br><br>
    인형이다. 무릎 높이. 흰 사기 얼굴에 볼이 발갛게 칠해졌다.<br>
    입 안에 이가 있다. 사기가 아니다. 진짜 이다. 사람 것. 어린아이 것도 섞였다.<br><br>
    무기로 치면 깨진다. 깨지면 조각이 된다. 조각에도 이가 붙어 있다.`,
  o:[
    { l:'① 무게로 내리찍어 부순다.', k:'break', dc:14,
      ok:`무기를 거꾸로 쥐고 자루 끝으로 정수리를 찍었다.<br><br>사기 머리가 쪼개졌다. 턱이 풀렸다. 발목에서 떨어졌다.<br>조각을 하나씩 다시 찍었다. 이가 붙은 조각부터. 다 가루가 될 때까지.<br><br>발목에 반달 모양 자국이 남았다. 작다. 그게 더 기분 나쁘다.`,
      ng:`찍었는데 머리가 아니라 볼이 깨졌다.<br><br>깨진 볼 안쪽에도 이가 있다. 한 줄 더.<br>인형이 턱을 더 깊이 넣었다. 동료가 떼어 줬다. 발목에서 이 하나가 안 빠졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 자루 끝으로 턱 경첩만 친다.', k:'gaze', dc:14,
      ok:`인형 턱은 철사 경첩으로 달렸다. 귀 밑, 양쪽.<br><br>자루 끝으로 왼쪽 경첩을 쳤다. 철사가 튀었다. 턱이 한쪽으로 늘어졌다. 오른쪽도.<br>입이 벌어진 채 안 다물린다. 인형이 바닥으로 굴러떨어졌다. 다시 와도 못 문다.<br><br>무는 것은 무는 데를 부수면 된다. 몸통이 아직 기어 온다. 내버려 뒀다.`,
      ng:`경첩을 겨눈 사이 인형이 고개를 틀었다.<br><br>자루 끝이 이빨에 맞았다. 이 하나가 부러져 튀어 손등에 박혔다.<br>남의 이가 손등에 박힌 채로 한참 서 있었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 날에 낀 것',
  x:`쉬는 틈에 날을 봤다.<br><br>
    이 나간 자리에 살점이 끼었다. 아까 벤 것이다. 닦았는데 남았다.<br>
    손톱으로 빼려는데 살점이 날을 따라 조금 자랐다. 이 나간 자리를 메우듯.<br><br>
    무기는 손의 연장이다. 그 연장에 남의 살이 자란다.`,
  o:[
    { l:'① 돌에 대고 갈아 낸다.', k:'fix', dc:14,
      ok:`결 고운 돌을 찾아 물을 묻혔다. 살점째 갈았다.<br><br>살점이 갈리면서 소리를 냈다. 아주 작게. 끝까지 갈았다.<br>날이 반짝인다. 이 나간 자리가 조금 넓어졌다. 대신 깨끗하다.<br><br>무기에 남의 것이 자라면 안 된다. 날 가는 손이 오늘은 오래 갔다.`,
      ng:`갈다가 돌이 미끄러졌다. 엄지를 베였다.<br><br>엄지에서 난 피가 날로 흘렀다. 살점이 그 피를 먹고 부풀었다.<br>결국 날 끝 한 마디를 부러뜨려 버렸다. 무기가 짧아졌다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } },
    { l:'② 무기를 동료에게 맡기고 쉰다.', k:'bond', dc:13,
      ok:`옆 사람에게 무기를 내밀었다. 살점 낀 데를 가리켰다.<br><br>동료가 불에 달군 칼끝으로 그 자리를 지졌다. 살점이 오그라들어 떨어졌다.<br>무기를 돌려받았다. 손이 비어 있던 동안 처음으로 등을 기대고 쉬었다.<br><br>무기를 남에게 맡겨 본 적이 별로 없다. 생각보다 잘 쉬어진다.`,
      ng:`맡기려는데 손이 안 펴진다. 무기를 놓기 싫다.<br><br>그사이 살점이 자라 날 끝을 감쌌다. 날이 무뎌졌다.<br>밤새 그 무기를 쥔 채 잤다. 쥔 손 안에서 무엇이 꿈틀댔다.`,
      win:{ exp:14, hp:8, mind:5 }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C3', t:'성당 — 갈비 위의 싸움',
  x:`발밑이 천장이다. 아치가 갈비처럼 솟았고 그 사이는 움푹 꺼졌다. 군데군데 꺼진 데가 뚫렸다.<br><br>
    뚫린 데로 내려다보면 어둠이다. 바람이 아래에서 올라온다. 머리 위 멀리 긴 의자들이 거꾸로 매달려 있다.<br>
    아치 위로 무언가 온다. 날개 없는 새 같다. 사람만 하다. 발톱이 아치를 움켜쥔다.<br><br>
    싸움은 발에서 시작한다. 발 디딜 데가 손바닥만 하다.`,
  o:[
    { l:'① 아치 한 줄에 발을 박고 친다.', k:'break', dc:15, wake:1,
      ok:`두 발을 한 줄에 세웠다. 앞뒤로. 넓게 설 수 없으니 허리를 낮췄다.<br><br>그것이 뛰어든다. 발은 그대로 두고 허리만 틀어 쳤다. 무게가 발이 아니라 배에서 나왔다.<br>그것이 구멍 아래로 떨어졌다. 떨어지는 소리가 끝까지 안 들린다.<br><br>발이 좁으면 허리가 넓어진다. 서는 법이 하나 늘었다. 이제 설 자리를 몸 안에 들고 다닌다.`,
      ng:`치는 순간 뒷발이 아치에서 미끄러졌다.<br><br>무기는 그것 어깨를 스쳤다. 이쪽은 움푹한 데로 굴렀다.<br>그것이 위에서 내려다본다. 발톱이 등을 긁고 갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 움푹한 데로 내려가 끌어들인다.', k:'steady', dc:14,
      ok:`아치 사이 움푹한 데로 내려섰다. 사방이 벽이다. 대신 바닥이 넓다.<br><br>그것이 따라 내려온다. 좁은 데서는 긴 팔이 벽에 걸린다.<br>걸린 틈에 쳤다. 두 번에 끝났다.<br><br>내 자리로 끌고 오면 된다. 위에 서는 것만 싸움이 아니다.`,
      ng:`내려섰는데 움푹한 데 바닥이 얇았다.<br><br>발이 빠졌다. 회반죽 아래가 비었다. 어둠이 발목을 붙잡는 것 같다.<br>빠진 발을 빼는 사이 그것이 어깨를 찍었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C4', t:'온실 — 앞치마를 두른 것',
  x:`화분 사이에 정원사가 서 있다. 등을 보이고.<br><br>
    앞치마 끈이 허리에 매였다. 목덜미 위가 하얗다. 머리카락이 아니다. 솜 같은 균이 수북하다.<br>
    손에 가지치기 가위를 들었다. 날이 벌어진 채다. 사람은 가위를 그렇게 안 든다. 손바닥 전체로 감싸 쥐었다.<br><br>
    도구 쥐는 법을 보면 그 손이 뭔지 안다. 저건 손이 아니다.`,
  o:[
    { l:'① 뒤에서 무릎을 쳐 꺾는다.', k:'break', dc:14,
      ok:`다가가 무릎 뒤를 쳤다. 그것이 앞으로 꺾였다.<br><br>쓰러지며 고개가 돌아갔다. 얼굴 자리에 갓이 겹겹이 났다. 갓 밑이 젖었다.<br>가위 쥔 손을 밟고 목덜미를 쳤다. 하얀 것이 터지며 가루가 날렸다. 숨을 참았다.<br><br>앞치마 주머니에 꿀 병이 하나 있다. 뚜껑이 닫혀 있다. 닫힌 것은 먹어도 된다.`,
      ng:`무릎을 쳤는데 안 꺾였다. 다리 속이 뼈가 아니라 줄기다. 휘었다가 돌아온다.<br><br>그것이 돌아서며 가위를 벌렸다. 팔뚝이 날 사이에 들어갔다.<br>빼냈다. 깊다. 상처에 하얀 가루가 묻었다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 무력을 쓴다 — 가위째 팔을 쳐 낸다.', k:'break', dc:15, cost:{ might:18 },
      ok:`쥐는 손부터 없앤다. 무력을 팔에 실었다.<br><br>가위 쥔 팔을 어깨에서 쳤다. 팔이 가위째 화분 사이로 날아갔다.<br>그것이 쥘 것을 찾아 남은 손을 더듬는다. 쥘 게 없으면 아무것도 못 한다. 천천히 끝냈다.<br><br>도구를 쥔 것은 도구를 뺏으면 반이 끝난다. 사람이든 아니든.`,
      ng:`팔은 쳐 냈다. 떨어진 팔이 가위를 안 놓았다.<br><br>바닥에서 가위가 혼자 벌어졌다 닫혔다 한다. 그 사이로 발목이 들어갔다.<br>발목을 빼는 동안 남은 몸이 이쪽 등에 올라탔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, mind:-6, might:-5 } },
    { l:'③ 가위 쥔 손을 오래 본다.', k:'gaze', dc:14,
      ok:`가위 쥔 손가락 사이로 실 같은 게 나와 화분 흙에 박혔다. 손이 화분에 뿌리를 내렸다.<br><br>그러면 저것은 못 걷는다. 걷는 척만 한다.<br>멀리 돌아서 지났다. 그것이 고개만 따라 돌린다. 몸은 못 돌린다.<br><br>안 싸워도 되는 것을 알아보는 것도 싸우는 사람 몫이다.`,
      ng:`보는데 손가락이 흙에서 빠졌다. 뿌리가 아니라 그냥 긴 손톱이었다.<br><br>그것이 걸어온다. 균 가루를 뿌리며.<br>뒷걸음질 치다 화분을 엎었다. 가루를 한 모금 마셨다. 기침이 멎지 않는다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C', t:'불침번 — 기어 오는 조각',
  x:`불침번이다. 다들 잔다.<br><br>
    어둠 저편에서 젖은 소리가 난다. 질척. 질척. 아까 토막 낸 것이 있는 쪽이다.<br>
    소리가 하나에서 둘이 된다. 둘이 다시 하나가 된다. 붙는 소리다.<br><br>
    깨우면 다들 못 잔다. 안 깨우면 이쪽 혼자다.`,
  o:[
    { l:'① 가서 조각을 멀리 흩어 던진다.', k:'break', dc:14,
      ok:`불 없이 소리 나는 쪽으로 갔다.<br><br>조각 둘이 붙어 있다. 붙은 자리를 다시 쳤다. 떨어진 것을 하나씩 들어 사방으로 던졌다. 멀리. 저마다 다른 쪽으로.<br>돌아와 앉았다. 소리가 여기저기서 난다. 작아졌다. 서로 찾느라 바쁘다.<br><br>아침까지 하나로 못 붙었다.`,
      ng:`던지려고 집은 조각이 손가락을 물었다. 입이 어디 붙었는지도 모를 조각이다.<br><br>털어 냈다. 그 소리에 다른 조각들이 이쪽으로 온다.<br>결국 다 깨웠다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 아무도 안 깨우고 혼자 앉아 듣는다.', k:'steady', dc:15, wake:1,
      ok:`무기를 무릎에 놓고 들었다.<br><br>질척. 소리가 다가온다. 아주 느리다. 무엇이 어디까지 붙었는지 소리로 안다. 다리가 붙었다. 이제 팔.<br>다 붙어 일어서는 소리가 났을 때 일어나 한 번에 쳤다. 다 붙은 것은 한 덩이다. 한 덩이는 한 번에 끝난다.<br><br>기다린 시간만큼 치는 손이 무거웠다. 기다리는 것도 휘두르는 일의 반이다. 그걸 손이 처음으로 알았다.`,
      ng:`듣다가 졸았다.<br><br>눈을 떴을 때 그것이 바로 앞에 앉아 있다. 이쪽과 같은 자세로.<br>쳤다. 늦었다. 손목을 물렸다. 다들 깼다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C1', t:'도축장 — 다시 차오르는 갈비',
  x:`갈고리에 고기가 걸려 있다. 소 반 마리.<br><br>
    한쪽 갈비가 칼에 발려 있다. 발린 자리에 새 살이 올라온다. 분홍색이다. 보는 사이에도 자란다.<br>
    배가 고프다. 사흘째 말린 것만 먹었다.<br><br>
    다들 고기를 보고 다시 이쪽을 본다. 여기서 칼질은 이쪽이 제일 낫다.`,
  o:[
    { l:'① 원래 있던 쪽을 크게 베어 낸다.', k:'break', dc:14,
      ok:`새로 자란 데는 안 건드렸다. 원래 있던 허벅지를 크게 베어 냈다.<br><br>베어 낸 덩이를 바닥에 놓고 한참 봤다. 안 움직인다. 갈고리에서 떨어진 것은 안 자란다.<br>벽장 소금 포대를 깨서 문질러 쌌다.<br><br>갈고리에 걸린 쪽은 벌써 다시 차오른다. 다들 그쪽을 안 본다.`,
      ng:`베어 낸 덩이가 바닥에서 한 번 움찔했다.<br><br>다들 물러섰다. 이쪽도. 그사이 갈고리 쪽 고기가 덩이 쪽으로 붉은 실 같은 것을 뻗었다.<br>덩이는 버렸다. 날에 묻은 것이 한참 안 닦였다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-8, mind:-10 } },
    { l:'② 고기는 두고 벽장을 뒤진다.', k:'sense', dc:13,
      ok:`자라는 고기는 먹을 것이 아니다. 벽장을 열었다.<br><br>소금 포대가 쌓여 있다. 굳어서 돌덩이다.<br>맨 밑 칸에 기름종이에 싼 육포가 있다. 여기서 일하던 사람 몫이다. 이것은 안 자란다.<br><br>먹을 때 다들 갈고리 쪽을 등졌다.`,
      ng:`벽장 안에서 무언가 숨을 쉬었다.<br><br>문을 닫았다. 문이 안에서 밀린다. 등으로 막았다.<br>한참 뒤 밀리는 게 멎었다. 다시 열 생각은 아무도 안 했다.`,
      win:{ exp:14, dream:1, item:'말린 고기' }, lose:{ mind:-8, spirit:-8 } }
  ] },

{ at:'C2', t:'공방 — 손목에 감긴 줄',
  x:`천장에서 줄이 내려온다. 가늘다. 거미줄보다 조금 굵다.<br><br>
    언제 감겼는지 모른다. 오른 손목에 세 가닥. 무기 쥔 손이다.<br>
    손목이 저절로 올라간다. 무기가 따라 올라간다. 날이 옆 동료 쪽으로 기운다.<br><br>
    줄은 위층으로 이어진다. 위에서 누가 손가락을 까딱인다.`,
  o:[
    { l:'① 왼손으로 줄을 끊는다.', k:'break', dc:14,
      ok:`왼손으로 허리칼을 뽑아 줄을 그었다. 한 가닥, 두 가닥. 질기다.<br><br>셋째가 끊어지자 오른팔이 뚝 떨어졌다. 무기가 바닥을 쳤다. 팔이 제 것으로 돌아왔다.<br>끊긴 줄이 천장으로 빨려 올라갔다. 위에서 짧게 혀 차는 소리가 났다.<br><br>손목에 줄 자국이 세 줄 남았다.`,
      ng:`한 가닥을 끊는 사이 두 가닥이 더 내려왔다. 왼손목에.<br><br>이제 두 팔이 다 위로 간다. 동료가 이쪽 팔을 붙잡고 줄을 끊었다.<br>그 동료 팔에 이쪽 날이 스쳤다. 미안하다고 했다. 줄이 한 말 같았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-10, spirit:-10 } },
    { l:'② 무력을 쓴다 — 줄을 거슬러 끌어내린다.', k:'steady', dc:15, cost:{ might:20 }, wake:1,
      ok:`팔을 내리지 않았다. 대신 손목을 비틀어 줄을 감았다. 감은 채 무력을 끌어올려 아래로 당겼다.<br><br>위층에서 무엇이 끌려오는 소리가 났다. 바닥판이 삐걱이고 무엇이 넘어졌다. 줄이 툭 풀렸다.<br>팔이 제 것이 됐다. 아까보다 더 제 것 같다.<br><br>당기는 쪽이 있으면 그 힘이 어디서 오는지 손이 안다. 손목에서 위층까지 힘의 줄기가 보이는 것 같았다. 남의 힘을 거슬러 쥐는 법. 쥐는 손이 하나를 더 배웠다.`,
      ng:`당겼다. 위에서도 당긴다. 위가 셌다.<br><br>팔이 뒤로 꺾이며 어깨에서 소리가 났다. 줄이 놓아준 건 동료가 끊어서다.<br>어깨가 한동안 안 올라간다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-6, might:-5 } },
    { l:'③ 무기를 놓는다.', k:'bond', dc:13,
      ok:`손을 폈다. 무기가 떨어졌다.<br><br>줄이 빈손을 들어 올린다. 빈손으로는 아무도 못 벤다. 줄이 머뭇거렸다.<br>그사이 동료가 줄을 잘라 줬다. 무기를 주워 줬다. 자루 쪽을 이쪽으로 해서.<br><br>무기를 놓는 게 이렇게 어려운 줄 몰랐다.`,
      ng:`손을 펴는데 손가락이 안 펴진다. 쥔 채로 굳었다.<br><br>줄이 무기째 팔을 휘둘렀다. 동료가 겨우 피했다. 날이 작업대를 갈랐다.<br>다들 이쪽에서 한 걸음씩 떨어졌다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'성당 — 성가대석',
  x:`성가대석이 거꾸로 매달려 있다. 난간이 발밑 아치에 닿을 듯 내려왔다.<br><br>
    거기서 노래가 난다. 사람 수보다 목소리가 많다. 셀 수가 없다.<br>
    난간 너머로 얼굴 하나가 내려다본다. 얼굴에 입이 셋이다. 셋이 다른 음을 낸다.<br><br>
    노래가 길어질수록 다들 걸음이 느려진다. 이쪽도.`,
  o:[
    { l:'① 난간 기둥을 부숴 성가대석째 떨군다.', k:'break', dc:15,
      doom:{ title:'떨어지는 성가대석', what:'성가대석과 함께 구멍 아래로 떨어집니다', dc:15, sec:55,
        text:`난간을 받친 기둥을 쳤다. 세 번에 금이 갔다.<br><br>성가대석이 기운다. 노래가 안 멈춘다. 오히려 높아진다.<br>떨어지는 것이 이쪽 발밑 아치까지 같이 끌고 간다. 바닥이 갈라졌다.<br><br>발밑으로 어둠이 열렸다. 손에 걸린 건 난간 한 토막이다. 노래가 아래에서 이쪽을 부른다.`,
        dieText:`성가대석이 떨어졌다. 노래는 한참 동안 아래에서 들렸다.<br><br>목소리가 사람 수보다 많았다. 이제 하나 더 많다.<br>음 하나가 쉰 목소리로 낮다. 무기 쥐던 사람 목소리다.` },
      ok:`기둥을 세 번 쳤다. 넷째에 성가대석이 기울었다. 뒤로 뛰었다.<br><br>성가대석이 아치 구멍으로 빠져나갔다. 노래가 떨어지면서 길게 늘어졌다. 그리고 끊겼다.<br>걸음이 다시 빨라졌다. 다들 뭘 듣고 있었는지 기억을 못 한다.<br><br>날에 이 하나가 박혀 있다. 어느 입에서 나온 건지 모른다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 무력을 실어 고함을 지른다 — 박자를 깬다.', k:'fix', dc:14, cost:{ might:16 },
      ok:`배에서부터 소리를 질렀다. 노래가 숨을 고르는 자리에.<br><br>목소리 몇이 박자를 놓쳤다. 놓친 목소리가 다른 목소리를 밀친다. 노래가 엉켰다.<br>엉킨 노래는 걸음을 못 묶는다. 다들 뛰어서 지났다.<br><br>목이 쉬었다. 성가대석에서 이쪽을 노려보는 입이 여럿이다. 이쪽 입은 하나다. 하나로 됐다.`,
      ng:`질렀는데 그 소리를 노래가 받아 갔다.<br><br>이쪽 고함이 성가대석에서 되풀이된다. 서른 개의 입으로.<br>귀가 먹먹하다. 걸음이 아까보다 더 느려졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-12, spirit:-8, might:-5 } }
  ] },

{ at:'C4', t:'온실 — 터지는 짐승',
  x:`화분 사이로 짐승 하나가 걸어 나온다. 개만 하다. 털 대신 갓이 났다.<br><br>
    등에 둥근 주머니가 여럿 달렸다. 걸을 때마다 흔들린다. 하나가 터지자 노란 가루가 퍼졌다.<br>
    가루를 마신 동료가 기침을 하더니 손등을 긁는다. 긁은 자리가 하얗게 일어난다.<br><br>
    치면 터진다. 안 치면 다가온다.`,
  o:[
    { l:'① 숨을 한 번 들이쉬고 그 숨 안에 끝낸다.', k:'break', dc:15, wake:1,
      ok:`숨을 깊이 들이쉬고 멈췄다. 이 숨이 다하기 전에 끝낸다.<br><br>들어가 쳤다. 주머니가 터진다. 가루 속으로 한 번 더 들어가 목을 쳤다. 셋째에 짐승이 주저앉았다.<br>가루 바깥으로 걸어 나와서야 숨을 뱉었다. 폐가 타는 것 같다. 깨끗하다.<br><br>숨 하나에 싸움 하나. 몸이 그 길이를 쟀다. 앞으로는 들이쉬는 순간 싸움의 길이가 정해진다.`,
      ng:`셋째를 치기 전에 숨이 떨어졌다.<br><br>가루 속에서 숨을 들이켰다. 목구멍에 노랗게 들러붙는다.<br>짐승은 쓰러졌다. 이쪽도 반쯤. 기침에 피가 섞였다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 젖은 천으로 입을 막고 무게로 눌러 죽인다.', k:'steady', dc:14,
      ok:`소매를 찢어 물에 적셔 입에 맸다.<br><br>짐승이 다가오기를 기다렸다가 무기를 눕혀 등을 눌렀다. 주머니 사이를. 짐승이 바닥에 짓눌려 버둥댄다.<br>그대로 무게를 실었다. 한참. 버둥대는 게 멎었다.<br><br>가루는 하나도 안 날렸다. 오래 걸렸다. 그 값이다.`,
      ng:`누르는데 짐승 몸이 물렀다. 무기가 등에 박히며 주머니 셋이 한꺼번에 터졌다.<br><br>젖은 천이 노랗게 물들었다. 천 너머로 가루가 들어온다.<br>눈이 따갑다. 손등이 가렵다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C', t:'통로 — 문 앞 순서',
  x:`문 앞에 섰다. 문 너머에서 무언가 씹는 소리가 난다.<br><br>
    누가 먼저 들어갈지 아무도 안 정했다. 다들 이쪽을 본다.<br>
    전사는 앞에 서는 사람이다. 앞에 서는 사람은 제일 먼저 다친다. 그래서 앞에 선다.<br><br>
    오늘은 오른 다리가 무겁다. 어제 물린 데다.`,
  o:[
    { l:'① 그래도 앞에 선다.', k:'steady', dc:14,
      ok:`문을 발로 밀고 먼저 들어갔다.<br><br>씹던 것이 고개를 든다. 입이 이쪽 머리만 하다. 무기를 앞으로 내밀어 그 입에 물렸다.<br>그것이 무기를 씹는 사이 뒤에서 다들 들어와 쳤다. 끝났다.<br><br>날에 이빨 자국이 남았다. 앞에 선 값이다. 싸다.`,
      ng:`들어서는데 무거운 다리가 문턱에 걸렸다.<br><br>그것이 먼저 왔다. 어깨를 물렸다. 뒤에서 다들 들어와 떼어 냈다.<br>앞자리는 지켰다. 어깨는 못 지켰다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-4 } },
    { l:'② 오늘은 앞을 내주고 바로 뒤에서 친다.', k:'bond', dc:14,
      ok:`옆 사람 어깨를 쳤다. 먼저 가라고. 바로 뒤에 붙겠다고.<br><br>그 사람이 문을 열었다. 씹던 것이 그쪽으로 고개를 든다. 드는 순간 어깨 너머로 쳤다.<br>앞사람이 놀라 돌아본다. 이쪽은 웃었다.<br><br>앞에 서는 것만 앞이 아니다. 앞사람 어깨 너머도 앞이다.`,
      ng:`앞사람이 문을 열자마자 뒤로 물러섰다. 겁이 났던 것이다.<br><br>둘이 엉켰다. 그것이 둘을 한꺼번에 덮쳤다.<br>무기를 휘두를 자리도 없었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C1', t:'도축장 — 큰 저울',
  x:`줄 끝에 큰 저울이 있다. 소를 통째로 다는 것이다.<br><br>
    저울판 앞에서 레일이 갈라진다. 무거운 것은 왼쪽으로, 가벼운 것은 오른쪽으로.<br>
    왼쪽 문 너머에서 칼 내려치는 소리가 일정하게 난다. 오른쪽은 조용하다.<br><br>
    저울판을 안 밟고는 못 지난다. 무기까지 치면 이쪽이 제일 무겁다.`,
  o:[
    { l:'① 무기를 동료에게 넘기고 맨몸으로 지난다.', k:'bond', dc:14,
      ok:`무기를 동료 둘에게 나눠 들렸다. 날 쪽과 자루 쪽.<br><br>맨몸으로 저울판에 올랐다. 바늘이 떤다. 한가운데서 멈췄다. 레일이 망설이다 오른쪽으로 갔다.<br>건너가서 무기를 돌려받았다. 손이 무기를 찾아 먼저 나갔다.<br><br>무기 없이 서 본 게 언제인지 모르겠다. 가벼웠다. 싫었다.`,
      ng:`무기를 내렸는데도 바늘이 왼쪽으로 기운다.<br><br>무기 탓이 아니었다. 이쪽 무게다. 갈고리가 어깨로 내려온다.<br>동료들이 끌어당겨 판에서 내렸다. 갈고리가 옷을 찢고 올라갔다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 저울 머리를 쳐 바늘을 꺾는다.', k:'break', dc:15,
      ok:`저울 머리를 쳐서 바늘을 꺾었다. 바늘이 오른쪽 끝에 박혔다.<br><br>그다음부터는 무엇을 올려도 가볍다. 레일이 다 오른쪽으로 간다. 다들 차례로 지났다.<br>왼쪽 문 너머 칼 소리가 멈췄다. 기다리는 소리 같다.<br><br>안 오는 것을 기다리게 두고 갔다.`,
      ng:`저울 머리가 생각보다 단단했다. 무기가 튕겼다.<br><br>그 소리에 왼쪽 문이 열렸다. 앞치마 끝만 보이고 다시 닫혔다.<br>바늘은 그대로다. 손목이 울린다. 다른 길을 찾아 한참 돌았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C2', t:'공방 — 무기를 든 인형',
  x:`작업대 위에 큰 인형이 서 있다. 사람 키다.<br><br>
    팔 하나가 굵다. 무기를 쥐었다. 나무로 깎은 것이다. 이쪽 무기와 모양이 같다. 이가 나간 자리까지.<br>
    이쪽이 무기를 들자 인형도 든다. 이쪽이 발을 옮기자 인형도 옮긴다. 줄은 안 보인다.<br><br>
    이쪽 버릇을 다 안다. 언제부터 보고 있었는지 모른다.`,
  o:[
    { l:'① 하던 대로 정면에서 친다.', k:'break', dc:15,
      ok:`하던 대로 들어갔다. 인형도 하던 대로 들어왔다. 두 무기가 맞았다.<br><br>나무와 쇠다. 나무가 졌다. 인형 무기가 부러지고 팔이 어깨에서 빠졌다.<br>똑같이 휘둘러도 쥔 것이 다르면 다르다. 남은 몸통을 쪼갰다. 안에 이쪽 머리카락이 한 줌 들어 있었다.<br><br>머리카락은 태웠다. 언제 빠진 건지는 생각 안 하기로 했다.`,
      ng:`하던 대로 들어갔다. 인형은 하던 대로 피했다. 이쪽이 피하는 쪽으로.<br><br>그리고 이쪽이 치는 자리를 쳤다. 정확히. 옆구리다.<br>나무 무기인데도 갈비가 울렸다. 버릇은 남이 쥐면 칼이 된다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 버릇을 버리고 처음 하는 식으로 친다.', k:'gaze', dc:15, wake:1,
      ok:`무기를 반대 손으로 바꿔 쥐었다. 인형도 바꿨다. 그런데 어색하다. 이쪽도 처음이니까.<br><br>처음 딛는 발로, 처음 가는 쪽에서 쳤다. 인형이 따라 하다가 멈칫했다. 따라 할 버릇이 없다.<br>멈칫한 머리를 쪼갰다.<br><br>손이 늘 가던 길이 있다. 오늘 그 길 말고도 갈 데가 있다는 걸 알았다. 몸에 박힌 것을 한 번 비우니 그 자리에 더 많은 게 들어올 것 같다.`,
      ng:`반대 손으로 쥐었다. 진짜로 어색했다.<br><br>무기가 손에서 돌았다. 인형은 그 어색함까지 따라 했다. 둘 다 무기를 떨어뜨렸다.<br>인형이 먼저 주웠다. 이쪽 무기를. 그걸로 이쪽 정강이를 쳤다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 끈 하나',
  x:`동료 허벅지가 길게 찢어졌다. 아까 그것 발톱이다.<br><br>
    피가 안 멎는다. 묶을 끈이 없다. 다들 가진 걸 다 썼다.<br>
    이쪽 무기 자루에 감은 가죽끈이 있다. 그걸 풀면 손이 미끄러진다. 여기서 손이 미끄러지면 다음 싸움이 없다.<br><br>
    그리고 그 발톱 주인은 아직 근처에 있다.`,
  o:[
    { l:'① 자루 끈을 풀어 묶어 준다.', k:'heal', dc:14,
      ok:`가죽끈을 풀었다. 길다. 허벅지 위쪽을 두 번 감아 막대를 끼우고 돌렸다.<br><br>피가 멎었다. 동료가 이를 악물었다 놓는다.<br>맨 자루를 쥐어 봤다. 미끄럽다. 손바닥에 흙을 묻혀 다시 쥐었다. 쥘 만하다.<br><br>끈은 다시 감으면 된다. 다리는 다시 안 생긴다.`,
      ng:`묶는데 막대가 부러졌다. 다시 돌리다 끈이 끊어졌다.<br><br>오래된 가죽이다. 끊어진 두 토막으로 겨우 묶었다. 피가 반만 멎었다.<br>자루는 맨 채로 남았다. 손바닥이 땀으로 미끄럽다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-8, spirit:-6 } },
    { l:'② 무력을 쓴다 — 발톱 주인을 쫓아가 끝낸다.', k:'break', dc:15, cost:{ might:18 },
      ok:`핏자국이 그것 쪽으로도 이어진다. 그것도 다쳤다.<br><br>무력을 다리에 싣고 쫓았다. 모퉁이 둘 뒤에 웅크리고 있었다. 이쪽을 보고 일어서기 전에 끝냈다.<br>그것 목에 가죽 목줄이 감겨 있다. 누가 매어 둔 것이다. 풀어 와서 그걸로 묶었다.<br><br>목줄을 맨 사람이 누구였는지는 모른다. 끈은 질겼다.`,
      ng:`쫓아가다 핏자국이 둘로 갈렸다. 한쪽을 골랐다.<br><br>그것이 아니라 그것의 짝이 있었다. 더 컸다. 팔을 물리고 도망쳐 왔다.<br>이제 묶어야 할 사람이 둘이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6, might:-5 } }
  ] },

{ at:'C3', t:'성당 — 엎어지지 않은 종',
  x:`종탑이 거꾸로 섰으니 종도 거꾸로다. 입을 위로 벌리고 발밑에 놓였다. 큰 솥 같다.<br><br>
    종 안에서 숨소리가 난다. 안쪽 벽을 긁는 소리. 추가 매달려 있어야 할 자리에 무엇이 웅크렸다.<br>
    종 둘레를 지나야 길이 이어진다. 지날 때마다 종이 낮게 운다. 울고 나면 안에서 무엇이 조금 더 커진다.<br><br>
    종은 치면 운다. 너무 세게 치면 깨진다.`,
  o:[
    { l:'① 종을 한 번 크게 쳐 울려 버린다.', k:'break', dc:14,
      ok:`종 옆구리를 정면으로 쳤다. 온 힘으로.<br><br>성당 전체가 울었다. 귀가 멀었다. 종 안에 웅크린 것이 그 울림을 한가운데서 맞았다. 긁는 소리가 멎었다.<br>들여다보니 종 바닥에 물렁한 것이 흩어져 있다. 울림이 그것을 안에서부터 풀었다.<br><br>한참 동안 귀에서 종이 울렸다. 그래도 이쪽이 친 종소리다.`,
      ng:`쳤는데 종이 안 울었다. 안에서 무엇이 종을 껴안아 울림을 먹었다.<br><br>먹은 울림이 그대로 돌아왔다. 무기를 타고 팔로, 가슴으로.<br>한참 숨이 안 쉬어졌다. 종 안에서 긁는 소리가 빨라졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-10, mind:-12 } },
    { l:'② 무력을 쓴다 — 종을 들어 엎는다.', k:'steady', dc:15, cost:{ might:22 },
      ok:`종 테두리 밑에 무기를 지렛대로 넣었다. 무력을 남김없이 끌어올렸다.<br><br>종이 기울었다. 더. 넘어갔다. 입이 바닥으로 엎어졌다. 안에 있던 것이 종 밑에 갇혔다.<br>안에서 쳐서는 종이 안 깨진다. 긁는 소리는 이제 아무 데도 못 간다.<br><br>그 위를 밟고 지났다. 무력이 바닥이다. 다리가 후들거렸다.`,
      ng:`종이 반쯤 기울었다가 도로 섰다.<br><br>안에 있던 것이 기운 틈으로 팔을 뻗었다. 손가락이 일곱이다. 이쪽 발목을 잡았다.<br>동료가 쳐서 손가락 셋을 떼어 냈다. 발목에 손가락 자국이 넷 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, spirit:-8, might:-5 } }
  ] },

{ at:'C4', t:'온실 — 바닥에 꿰인 사람',
  x:`잠깐 쉰 사이 동료 하나가 못 일어난다.<br><br>
    등이 바닥에 붙었다. 하얀 실이 흙에서 올라와 옷을 뚫고 등을 꿰맸다. 촘촘하다.<br>
    동료가 눈만 굴린다. 실이 목덜미까지 왔다. 입가로 기어오른다.<br><br>
    실은 흙 속 깊은 데서 나온다. 거기서 무엇이 당기고 있다.`,
  o:[
    { l:'① 동료를 붙잡고 실을 뿌리째 뜯어낸다.', k:'break', dc:15,
      doom:{ title:'흙 속의 실', what:'균사에 감겨 흙 속으로 끌려 들어갑니다', dc:15, sec:60,
        text:`동료 겨드랑이에 팔을 끼우고 당겼다. 실이 뜯겨 나간다. 동료가 빠져나왔다.<br><br>뜯긴 실이 갈 데를 찾는다. 제일 가까운 것을 찾는다. 이쪽 발목이다.<br>순식간에 무릎까지 감겼다. 흙이 물러진다. 발이 들어간다.<br><br>흙 속에서 무엇이 아주 천천히 당긴다. 서두를 필요가 없다는 듯.`,
        dieText:`온실 바닥에 사람 모양으로 흙이 조금 솟았다.<br><br>며칠 뒤 그 자리에 하얀 갓이 줄지어 올라왔다. 손가락 길이만 하다.<br>갓들이 한쪽으로 기울어 있다. 무기를 쥔 손 모양이다.` },
      ok:`동료를 끌어안고 당겼다. 실이 등에서 뜯긴다. 뜯길 때마다 동료가 소리를 지른다.<br><br>마지막 실이 끊어지며 둘이 함께 뒤로 넘어졌다. 실들이 이쪽 발을 찾아 기어 온다. 발을 들고 물러섰다.<br>실이 갈 데를 잃고 흙으로 돌아갔다.<br><br>동료 등이 구멍투성이다. 작다. 그래도 피가 난다. 피가 나면 사람이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 실 밑동만 골라 끊는다.', k:'gaze', dc:14,
      ok:`실이 다 따로 흙에서 나오는 게 아니다. 굵은 줄기 하나가 흙에서 나와 거기서 갈라진다.<br><br>갈라지기 전 굵은 데를 찾아 날로 그었다. 한 번에. 등에 꿰인 실들이 일제히 힘을 잃었다.<br>동료를 일으켰다. 실이 옷에 붙은 채 축 늘어졌다.<br><br>백 가닥을 끊을 일을 한 가닥으로 끝냈다. 손보다 눈이 먼저였다.`,
      ng:`굵은 데라고 끊은 게 갈라진 가지 하나였다.<br><br>남은 실이 놀라 더 세게 조인다. 동료가 숨을 못 쉰다.<br>결국 손으로 하나씩 뜯었다. 동료 등이 피투성이가 됐다. 손바닥에 실이 박혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C', t:'통로 — 혼자 남은 앞',
  x:`문이 등 뒤에서 닫혔다. 저절로.<br><br>
    다들 저쪽이다. 문 두드리는 소리가 들린다. 이쪽에선 안 열린다.<br>
    앞쪽 어둠에서 발소리가 여럿 다가온다. 맨발이다. 바닥에 붙었다 떨어지는 소리가 끈적하다.<br><br>
    여기는 혼자서는 못 버틴다. 그건 다들 안다. 저것들도 안다.`,
  o:[
    { l:'① 문에 등을 대고 버틴다.', k:'steady', dc:15,
      ok:`문에 등을 붙였다. 뒤가 문이면 앞만 보면 된다.<br><br>첫째가 왔다. 쳤다. 둘째, 셋째. 하나씩 오는 동안은 하나씩 친다.<br>넷째가 올 때 등 뒤 문이 열렸다. 동료들 손이 이쪽 어깨를 잡아끌었다. 문이 닫혔다. 저쪽에서 무엇이 문에 부딪쳤다.<br><br>혼자 버틴 게 아니다. 문 열릴 때까지 버틴 것이다. 그 둘은 다르다.`,
      ng:`셋째까지는 쳤다. 넷째와 다섯째가 같이 왔다.<br><br>하나가 무기를 문 사이 다른 하나가 옆구리를 물었다.<br>문이 열렸을 때 이쪽은 문에 기대 앉아 있었다. 동료들이 끌고 들어왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-18, spirit:-6 } },
    { l:'② 자루로 문을 쳐 박자를 보낸다.', k:'fix', dc:14,
      ok:`무기 자루로 문을 쳤다. 셋, 쉬고, 셋.<br><br>저쪽도 같은 박자로 두드렸다. 그다음 저쪽 소리가 문 아래쪽으로 옮겨 갔다. 경첩이다. 저쪽에서 경첩을 깨고 있다.<br>이쪽은 박자를 계속 보냈다. 문이 넘어갔다. 발소리가 닿기 직전이었다.<br><br>박자를 들은 쪽이 일을 했다. 혼자인 쪽은 박자만 보냈다. 그거면 됐다.`,
      ng:`두드린 소리를 앞쪽 것들이 먼저 들었다.<br><br>발소리가 빨라졌다. 저쪽에서도 두드린다. 박자가 엉켰다.<br>문이 열렸을 때는 팔에 이빨 자국이 셋 남은 뒤였다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C', t:'통로 — 일곱 번째',
  x:`오늘만 여섯 번 싸웠다.<br><br>
    여기 것들은 한 번에 안 끝난다. 끝났다 싶으면 다시 붙고, 붙었다 싶으면 다시 온다.<br>
    무기가 무겁다. 처음 들었을 때의 무게가 아니다. 팔이 오늘 휘두른 무게를 다 기억하고 있다.<br><br>
    일곱 번째가 앞에서 기어 온다. 작다. 빠르다.`,
  o:[
    { l:'① 크게 휘두르지 않고 짧게 끊어 친다.', k:'fix', dc:14, wake:1,
      ok:`팔을 다 펴지 않았다. 팔꿈치 아래로만. 손목으로 짧게.<br><br>작은 것이 뛰어오른다. 짧게 쳤다. 떨어졌다. 다시 온다. 또 짧게. 힘의 반의 반만 썼다.<br>다섯 번 만에 끝났다. 숨이 거의 안 찼다.<br><br>세게 치는 법은 오래 배웠다. 오늘은 덜 치는 법을 배웠다. 무기가 아까보다 가볍다. 팔이 무게를 나눠 드는 법을 알았다.`,
      ng:`짧게 치니 힘이 안 실린다. 작은 것이 날에 맞고 튕겨 다시 왔다.<br><br>결국 크게 휘둘렀다. 빗나갔다. 그것이 정강이에 붙었다.<br>떼어 냈을 때 팔이 덜덜 떨렸다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 남은 힘을 끌어모아 크게 친다.', k:'break', dc:14,
      ok:`팔이 무거워도 크게 쳤다. 한 번에 끝나라고.<br><br>끝났다. 작은 것이 벽에 붙었다가 미끄러졌다.<br>무기를 내렸다. 팔이 안 올라간다. 일곱 번째는 끝났다. 여덟 번째는 안 오기를 바랐다.<br><br>안 왔다. 오늘은.`,
      ng:`크게 휘둘렀는데 그것이 작아서 빗나갔다.<br><br>무기 무게가 이쪽을 끌고 갔다. 무릎을 꿇었다. 그것이 목덜미로 뛰어올랐다.<br>동료가 떼어 냈다. 목에 물린 자국이 남았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-15, spirit:-6 } }
  ] },

{ at:'C', t:'끝 방 — 꿰맨 자국이 많은 것',
  x:`마지막 방에 큰 것이 앉아 있다. 소 둘을 붙인 만하다.<br><br>
    온몸에 꿰맨 자국이 있다. 누가 여러 번 베었고, 그때마다 그것이 다시 꿰맸다. 굵은 실로. 제 손으로.<br>
    자국이 많다는 건 여럿이 여기서 졌다는 뜻이다. 자국 하나가 사람 하나다.<br><br>
    그것이 일어선다. 새 실을 손가락에 감으면서.`,
  o:[
    { l:'① 꿰맨 자리만 골라 다시 연다.', k:'break', dc:16, wake:1,
      ok:`새로 벨 필요가 없다. 이미 벤 자리가 있다.<br><br>제일 오래된 꿰맨 자국에 날을 넣어 실을 끊었다. 벌어졌다. 다음 자국. 또 다음. 그것이 꿰매는 손보다 이쪽 손이 빨랐다.<br>동료들이 벌어진 데를 쳤다. 그것이 실을 쥔 채 무너졌다.<br><br>앞사람들이 남긴 자국을 이쪽이 이어서 쳤다. 혼자서는 못 했다. 앞사람들이랑 같이 했다. 무기가 오늘 처음으로 남의 싸움까지 같이 들었다. 손이 그 무게를 안다.`,
      ng:`실 하나를 끊는 사이 그것이 다른 손으로 이쪽 팔을 잡았다.<br><br>손가락에 감긴 실이 이쪽 팔에도 감긴다. 꿰매려 한다. 바늘 끝이 살에 닿았다.<br>동료가 그 손을 쳐서 떼어 냈다. 팔에 바늘땀이 셋 남았다.`,
      win:{ exp:25, dream:3, item:'짐승 고기' }, lose:{ hp:-18, spirit:-10 } },
    { l:'② 무력을 전부 실어 정수리를 친다.', k:'break', dc:15, cost:{ might:25 },
      ok:`머리에는 꿰맨 자국이 없다. 아무도 거기까지 못 갔다.<br><br>무력을 남김없이 끌어올렸다. 동료 등을 딛고 뛰어 정수리에 떨어졌다.<br>그것이 멈췄다. 꿰맬 자리를 찾는 손이 제 머리를 더듬는다. 못 찾는다. 앞으로 넘어졌다.<br><br>처음 닿은 자리였다. 처음은 한 번이면 된다.`,
      ng:`뛰었는데 그것이 고개를 들었다.<br><br>무기가 정수리가 아니라 어깨에 박혔다. 그것이 이쪽을 어깨째 털어 냈다. 벽까지 날아갔다.<br>그것 어깨에 꿰맨 자국이 하나 늘었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-8, might:-5 } },
    { l:'③ 꿰매는 손을 붙잡고 버틴다.', k:'bond', dc:15,
      ok:`그것이 실 감는 손을 두 팔로 끌어안았다.<br><br>손이 묶이면 못 꿰맨다. 그것이 이쪽을 흔든다. 안 놓았다. 그사이 동료들이 벤 자리가 그대로 열려 있다.<br>열린 자리가 다섯을 넘자 그것이 주저앉았다.<br><br>치는 건 동료들이 했다. 이쪽은 쥐기만 했다. 쥐는 건 원래 이쪽 일이다.`,
      ng:`끌어안은 손이 이쪽보다 셌다.<br><br>그것이 이쪽을 들어 바닥에 내리쳤다. 한 번. 두 번.<br>세 번째에 동료들이 이쪽을 빼냈다. 숨이 안 쉬어진다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-8 } }
  ] }

]);

// ------------------------------------------
// 화염술사 · 마력
// ------------------------------------------
kJob('pyro', 'C', [

{ at:'C', t:'통로 — 불을 보고 오는 것',
  x:`어둠 속에서 하얀 것이 이쪽으로 온다. 느리다.<br><br>
    털이 없다. 눈도 없다. 머리 앞쪽이 움푹 파였는데 그 자리가 이쪽 손바닥 불을 향한다.<br>
    짐승은 불을 무서워한다. 이것은 짐승이 아니다. 따뜻한 쪽으로 온다. 벌레가 그렇듯이.<br><br>
    손바닥 불을 끄면 어둠이다. 켜 두면 이것이 손으로 온다.`,
  o:[
    { l:'① 불을 손에서 떼어 멀리 던져 둔다.', k:'fix', dc:14, wake:1,
      ok:`손바닥 불을 뭉쳐 저쪽 벽 아래로 굴렸다. 불이 바닥에 떨어져서도 안 꺼진다. 손을 떠났는데 아직 이쪽 불이다.<br><br>하얀 것이 고개를 돌렸다. 벽 아래 불 쪽으로 기어간다. 불을 끌어안듯 몸을 둥글게 만다.<br>그 등을 지나쳐 갔다. 다 지날 때까지 저쪽 불이 버텼다. 버티게 했다. 멀리서.<br><br>불은 손에 있어야 하는 줄 알았다. 놓아도 이어져 있다. 줄 없이 연을 날리는 기분이다.`,
      ng:`던진 불이 바닥에서 바로 꺼졌다.<br><br>하얀 것이 다시 이쪽을 향한다. 이번엔 빠르다. 따뜻한 데가 하나뿐이니까.<br>손등에 붙었다. 떼어 냈을 때 손등 살갗이 같이 떨어졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'② 손바닥 불을 키워 정면에서 지진다.', k:'break', dc:14,
      ok:`오라고 했다. 불을 키웠다.<br><br>하얀 것이 불에 머리를 박았다. 움푹한 데가 불을 삼키려는 듯 벌어진다. 불이 그 안으로 들어갔다.<br>안에서부터 익었다. 그것이 쪼그라들어 바닥에 떨어졌다.<br><br>따뜻한 걸 좋아하면 따뜻하게 해 주면 된다. 아주 많이.`,
      ng:`불을 키운 만큼 그것도 빨라졌다.<br><br>불 속으로 들어와 손목에 붙었다. 뜨거운 게 아무렇지도 않은 모양이다.<br>불을 끄고서야 떨어졌다. 손목이 데었고 물렸다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-15, mind:-6 } }
  ] },

{ at:'C1', t:'도축장 — 고기 장막',
  x:`레일에 고기가 빽빽이 걸렸다. 통로가 고기로 막혔다.<br><br>
    앞사람이 칼로 한 덩이를 갈랐다. 지나가려는데 갈라진 자리가 도로 붙는다. 붉은 실이 양쪽에서 나와 서로를 찾는다.<br>
    불 쓰는 사람은 안다. 살은 지지면 닫힌다. 닫힌 살은 더 안 자란다.<br><br>
    지지는 냄새가 날 것이다. 여기서 그 냄새는 다른 것도 부른다.`,
  o:[
    { l:'① 갈라진 자리마다 손바닥으로 지지며 지난다.', k:'break', dc:14, wake:1,
      ok:`앞사람이 가르면 손바닥을 갖다 댔다. 치익. 붉은 실이 오그라든다. 다음 덩이. 또 다음.<br><br>지진 자리는 안 붙었다. 고기 사이로 사람 하나 지날 길이 났다. 뒤에서 다들 따라왔다.<br>열한 번째 덩이를 지질 때쯤 손바닥이 알았다. 얼마나 뜨겁게, 얼마나 오래. 딱 그만큼만.<br><br>불은 태우는 것인 줄만 알았다. 오늘은 닫았다. 손바닥이 그 온도를 기억한다. 불로 막을 수 있는 것이 하나 늘었다.`,
      ng:`지지는 냄새가 레일을 타고 퍼졌다.<br><br>다섯째 덩이를 지질 때 저 안쪽에서 칼 가는 소리가 멈췄다. 발소리가 온다.<br>반쯤 지진 길을 뛰어서 빠져나왔다. 붙다 만 고기가 어깨를 쓸고 갔다. 축축하다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 마력을 쓴다 — 장막째 태운다.', k:'break', dc:15, cost:{ mana:18 },
      ok:`두 손을 펴고 앞으로 불을 밀었다. 길게.<br><br>고기 장막이 한 줄로 타 들어간다. 기름이 녹아 바닥에 흐른다. 탄 고기는 안 붙는다. 그을린 갈비만 갈고리에 남았다.<br>길이 넓게 났다. 다들 코를 막고 뛰었다.<br><br>타는 냄새가 고소하다. 그게 제일 싫었다.`,
      ng:`기름이 불을 받아 생각보다 크게 일었다.<br><br>불이 레일을 타고 이쪽으로 돌아왔다. 앞머리와 소매가 탔다.<br>타다 만 고기들이 서로 붙으면서 그을린 자리를 감췄다. 길은 다시 막혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6, mana:-5 } },
    { l:'③ 소금을 박아 붙는 걸 늦춘다.', k:'sense', dc:14,
      ok:`벽 쪽에 소금 포대가 있다. 굳은 덩이를 깨서 갈라진 자리에 박아 넣었다.<br><br>붉은 실이 소금에 닿자 움츠러든다. 붙는 게 느려졌다. 그 틈에 지났다.<br>남은 소금은 챙겼다. 불 말고도 닫는 것이 있다.<br><br>손바닥은 아꼈다. 아낀 손바닥이 아직 따뜻하다.`,
      ng:`소금 포대를 찢는데 안에서 무엇이 꿈틀했다.<br><br>소금 속에 절여 둔 것이 있었다. 손가락이 그 위를 스쳤다. 차고 미끈하다.<br>손을 뺐다. 한동안 손가락에서 짠내가 안 빠졌다. 다른 냄새도.`,
      win:{ exp:15, dream:1, item:'소금 덩이' }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 아직 따뜻한 가마',
  x:`공방 구석에 가마가 있다. 벽돌로 쌓았다. 사람이 기어 들어갈 만한 아궁이.<br><br>
    불이 꺼진 지 오래인데 벽돌이 따뜻하다. 손을 대 보니 안쪽이 더 뜨겁다.<br>
    아궁이 틈으로 들여다보면 사기 인형들이 줄지어 누워 있다. 굽는 중이다. 누가 불을 넣고 있다.<br><br>
    화염술사의 손끝이 저절로 오그라든다. 안쪽 불은 이쪽 불이 아니다.`,
  o:[
    { l:'① 아궁이를 열고 불을 밀어 넣어 안의 것을 다 태운다.', k:'break', dc:15,
      doom:{ title:'가마 속', what:'가마 아궁이 속으로 끌려 들어갑니다', dc:15, sec:55,
        text:`아궁이 문을 열었다. 열기가 얼굴을 친다. 불을 밀어 넣었다.<br><br>누워 있던 인형들이 일제히 고개를 돌렸다. 구워지다 만 얼굴이다. 아직 무르다.<br>무른 손 여럿이 아궁이 밖으로 나와 이쪽 팔을 잡았다. 당긴다. 어깨까지 들어갔다.<br><br>안쪽 불이 이쪽 불보다 오래됐다. 그리고 배가 고프다.`,
        dieText:`며칠 뒤 가마에서 인형 하나가 나왔다.<br><br>다른 것들보다 크다. 사기 살결이 고르지 않다. 손끝이 까맣게 그을렸다.<br>그 인형 손바닥은 늘 따뜻하다. 진열장 어디에 두어도.` },
      ok:`아궁이 문을 열자마자 불을 밀어 넣고 문을 닫았다. 등으로 막았다.<br><br>안에서 무른 것들이 문을 긁는다. 이쪽 불이 안쪽 불을 먹고 커진다. 긁는 소리가 하나씩 멎는다.<br>벽돌이 손을 못 댈 만큼 달아올랐다가 식었다.<br><br>열어 보니 재뿐이다. 재 속에 이빨이 한 줌. 그것만 안 탔다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 벽돌의 열을 손바닥으로 짚어 안을 센다.', k:'gaze', dc:14,
      ok:`벽돌에 손바닥을 대고 열이 다른 자리를 짚었다.<br><br>뜨거운 데가 일곱. 일곱 개가 누워 있다. 그중 하나는 열이 안 난다. 식은 게 아니다. 처음부터 안 구워진 것이다. 살아 있는 것은 안 구워진다.<br>그 하나가 있는 쪽을 피해 공방을 돌아 나갔다.<br><br>안 건드린 가마는 그대로 따뜻하다. 따뜻한 채로 두는 게 나았다.`,
      ng:`짚는데 벽돌 하나가 쑥 들어갔다.<br><br>틈이 생겼다. 틈으로 안쪽 열기가 뿜어져 나와 얼굴을 덮었다. 눈썹이 탔다.<br>틈 너머에서 무른 손가락 하나가 나와 허공을 더듬었다. 뒷걸음질 쳤다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 눕는 연기',
  x:`쉬는 자리에 작은 불을 피웠다. 손바닥만 한 것.<br><br>
    연기가 위로 안 간다. 옆으로 눕는다. 통로 저쪽 어둠으로 길게 빨려 간다.<br>
    연기는 바람을 따른다. 바람은 숨을 따른다. 저쪽에서 무엇이 아주 크게, 아주 천천히 숨을 들이쉬고 있다.<br><br>
    내쉴 때가 올 것이다.`,
  o:[
    { l:'① 연기 끝을 따라가 무엇인지 본다.', k:'sense', dc:14,
      ok:`불씨 하나를 손끝에 두고 연기를 따라갔다. 스무 걸음.<br><br>벽에 구멍이 있다. 구멍 안이 젖은 살이다. 벽 전체가 숨을 쉰다. 벽이 아니라 무엇의 옆구리다.<br>돌아와서 다들 깨웠다. 내쉬기 전에 반대쪽으로 자리를 옮겼다.<br><br>옮기고 한참 뒤 저쪽에서 더운 바람이 불었다. 비린내가 났다.`,
      ng:`따라가는데 연기가 갑자기 멈췄다.<br><br>그리고 거꾸로 왔다. 덥고 축축한 바람이 얼굴을 덮었다. 뼈까지 비린내가 배었다.<br>불씨가 꺼졌다. 어둠 속에서 더듬어 돌아왔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-6 } },
    { l:'② 불을 끄고 다들 숨을 죽인다.', k:'hide', dc:14,
      ok:`불을 손바닥으로 덮어 껐다. 다들 입을 막게 했다.<br><br>어둠 속에서 들숨이 길게 이어졌다. 그리고 멈췄다. 무엇이 냄새를 찾는다. 연기 냄새가 끊겼다.<br>한참 뒤 들숨이 다시 시작됐다. 아까보다 멀다.<br><br>불은 있는 데를 알리는 것이기도 하다. 끌 줄 알아야 오래 쓴다.`,
      ng:`덮어 끈 불이 손바닥 밑에서 한 번 더 피었다. 버릇처럼.<br><br>연기 한 가닥이 손가락 사이로 새어 나갔다. 들숨이 그 가닥을 정확히 찾아왔다.<br>무엇이 가까이 와서 오래 냄새를 맡고 갔다. 아무도 숨을 못 쉬었다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-8, spirit:-8 } }
  ] },

{ at:'C3', t:'성당 — 위로 흐른 촛농',
  x:`거꾸로 매달렸어야 할 촛대가 발밑 아치에서 솟아 있다. 초가 수십 개다. 다 꺼졌다.<br><br>
    촛농이 이상하다. 초 몸통을 따라 위로 흘러 굳었다. 머리 위 바닥 쪽으로.<br>
    여기서는 위아래가 사람한테만 바뀐 게 아니다. 무엇에게 위인지가 섞였다.<br><br>
    불은 늘 위로 탄다. 불 쓰는 사람은 그걸 믿고 산다.`,
  o:[
    { l:'① 초에 하나씩 불을 붙여 길을 밝힌다.', k:'fix', dc:14,
      ok:`손끝으로 심지를 하나씩 건드렸다. 불이 붙는다. 정상적으로, 이쪽 머리 위로 탄다.<br><br>스무 개가 밝아지자 아치 사이 구멍들이 보였다. 디딜 데와 디디면 안 될 데가 갈렸다. 다들 불빛을 따라 건넜다.<br>촛대 밑 상자에 밀랍 덩이가 있다. 벌집 조각이 섞였고 꿀이 아직 고였다.<br><br>마지막 초 하나는 불이 아래로 탔다. 그 초는 꺼 버렸다. 이유는 안 물었다.`,
      ng:`셋째 초에 불을 붙이자 촛농이 끓으며 위로 튀었다. 머리 위로 날아가 안 떨어진다.<br><br>대신 붙은 불이 아래로 기운다. 이쪽 손 쪽으로. 손등이 데었다.<br>다 끄고 어둠 속에서 건넜다. 구멍 하나에 발이 빠질 뻔했다.`,
      win:{ exp:16, dream:1, item:'꿀 한 줌' }, lose:{ hp:-12, mind:-6 } },
    { l:'② 불꽃 끝이 기우는 쪽을 읽는다.', k:'gaze', dc:15, wake:1,
      ok:`손끝 불을 작게 띄우고 가만히 봤다.<br><br>불꽃 끝이 아주 조금 떤다. 이쪽 머리 위로 서 있는데, 끝만 한쪽으로 기운다. 이 성당의 진짜 위가 그쪽이다. 거기에 문이 있을 것이다.<br>그쪽으로 걸었다. 기울기가 커질수록 가까웠다. 문이 있었다. 거꾸로.<br><br>불은 위를 안다. 무엇에게 위인지까지 안다. 이제 불꽃 끝만 보면 길이 보인다. 어둠 속에서 손끝에 나침반을 하나 단 셈이다.`,
      ng:`보는데 불꽃이 두 갈래로 갈라졌다. 한쪽은 위, 한쪽은 아래.<br><br>어느 쪽이 맞는지 보려다 눈이 빙 돌았다. 아치 위에서 무릎을 꿇었다.<br>구역질이 났다. 몸이 위로 떨어지는 것 같았다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-12, spirit:-6 } }
  ] },

{ at:'C4', t:'온실 — 가루가 뜬 방',
  x:`온실 안쪽 방 공기가 노랗다. 가루가 떠 있다. 손을 휘저으면 소용돌이가 진다.<br><br>
    불 쓰는 사람은 이런 공기를 안다. 밀가루 창고, 석탄 굴. 불씨 하나면 방 전체가 한꺼번에 탄다.<br>
    방 한가운데 갓 덮인 짐승이 웅크렸다. 가루는 저것에서 나온다. 숨 쉴 때마다.<br><br>
    저것을 지나야 한다. 손끝이 근질거린다. 참는다.`,
  o:[
    { l:'① 마력을 쓴다 — 불꽃 없이 열만 손에 모아 지진다.', k:'break', dc:15, cost:{ mana:20 }, wake:1,
      ok:`불을 피우지 않았다. 마력을 손바닥 안쪽에만 가뒀다. 불꽃이 될 듯 말 듯한 데서 멈췄다.<br><br>손바닥이 달군 쇠처럼 뜨겁다. 불빛은 하나도 없다. 그 손으로 짐승 목덜미를 눌렀다. 갓이 소리 없이 익어 오그라든다. 가루 속에서도 아무것도 안 붙었다.<br>짐승이 숨을 멈췄다. 가루가 천천히 가라앉는다.<br><br>불은 꽃이 피어야 불인 줄 알았다. 꽃을 안 피우고도 뜨겁다. 손바닥이 아직 그 열을 쥐고 있다. 피울지 말지를 이제 이쪽이 정한다.`,
      ng:`열을 가두다 손끝에서 불티 하나가 새어 나갔다.<br><br>펑. 작았다. 방 전체가 아니라 손 둘레만. 그래도 손이 까맣게 그을었다.<br>짐승이 놀라 가루를 한꺼번에 뿜었다. 기침하며 뒷걸음질 쳐 나왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, spirit:-6, mana:-5 } },
    { l:'② 다들 내보내고 문밖에서 불씨를 던진다.', k:'break', dc:15,
      doom:{ title:'노란 방', what:'가루가 한꺼번에 불붙은 방에 갇혔습니다', dc:15, sec:55,
        text:`다들 내보냈다. 문틀에 서서 불씨를 던졌다.<br><br>방이 한숨에 노랗게 탔다. 생각보다 빨랐다. 불이 문까지 오는 데 한순간이다.<br>등 뒤 문이 바람에 닫혔다. 방 안쪽으로.<br><br>불은 숨을 먹는다. 방 안의 숨을. 그리고 문틈으로 이쪽 숨까지.`,
        dieText:`온실 유리 몇 장이 바깥으로 튀었다. 그 방 하나만.<br><br>타고 남은 방에는 갓 하나 없다. 깨끗하다.<br>문 안쪽에 손바닥 자국이 그을려 있다. 손끝이 유난히 까맣다.` },
      ok:`다들 멀리 보냈다. 문틀에 서서 불씨를 던지고 바로 문을 닫았다. 문에서 손을 떼고 엎드렸다.<br><br>쿵. 문이 한 번 부풀었다 가라앉았다. 문틈으로 뜨거운 바람이 머리 위를 지났다.<br>열어 보니 방이 비었다. 짐승은 까만 덩어리다. 가루는 하나도 없다.<br><br>엎드린 채 손끝을 봤다. 떨린다. 다행히 떨린다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'C', t:'불가 — 가장자리에 모이는 것',
  x:`밤에 불을 피웠다. 둘레에 다들 누웠다.<br><br>
    불빛이 닿는 가장자리에 무언가 모인다. 하나, 둘, 다섯. 불빛 바로 바깥에서 멈춘다.<br>
    무릎 높이다. 손이 많다. 불을 무서워하는 게 아니다. 불빛 안으로 안 들어올 뿐이다. 아직은.<br><br>
    불이 작아지면 가장자리가 안쪽으로 온다. 그것들도 같이 온다.`,
  o:[
    { l:'① 마력을 쓴다 — 불을 한 번 크게 일으킨다.', k:'break', dc:15, cost:{ mana:18 },
      ok:`불에 마력을 한꺼번에 밀어 넣었다. 불이 천장까지 솟았다.<br><br>가장자리가 멀리 밀려난다. 거기 있던 것들이 갑자기 불빛 안에 들어왔다. 숨을 데가 없다. 손 많은 것들이 불빛 속에서 오그라든다. 둘은 탔다. 셋은 어둠 끝까지 도망갔다.<br>불을 다시 낮췄다. 다들 깨어서 이쪽을 본다.<br><br>밝은 데 들어온 것들은 생각보다 작았다.`,
      ng:`불이 솟았다가 너무 빨리 꺼졌다. 마력이 고르게 안 들어갔다.<br><br>순간 어둠이 불 바로 앞까지 왔다. 그것들도.<br>손 여럿이 이쪽 발목을 잡아끌었다. 동료들이 깨서 붙잡아 줬다. 발목에 손자국이 빙 둘러 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-8, mana:-5 } },
    { l:'② 불을 아침까지 같은 크기로 지킨다.', k:'steady', dc:14,
      ok:`불을 키우지도 줄이지도 않았다. 한 뼘. 밤새 그 크기로.<br><br>장작이 줄면 마력을 아주 조금씩 보탰다. 가장자리가 움직이지 않는다. 그것들도 움직이지 않는다.<br>새벽이 되자 하나씩 물러갔다. 기다리다 지친 것 같다.<br><br>불을 크게 하는 건 쉽다. 같은 크기로 두는 게 어렵다. 밤새 눈을 한 번도 안 감았다.`,
      ng:`새벽 무렵 졸았다. 불이 손가락 하나만큼 줄었다.<br><br>그만큼 가장자리가 들어왔다. 누운 동료 발끝이 어둠에 들어갔다. 손 하나가 그 발을 쓰다듬었다.<br>동료 비명에 깼다. 불을 다시 올렸다. 다들 남은 밤을 앉아서 보냈다.`,
      win:{ exp:16, dream:1, hp:6 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C1', t:'도축장 — 기름 가마솥',
  x:`큰 가마솥에 기름이 끓고 있다. 불도 없는데 끓는다.<br><br>
    뼈와 비계를 녹이는 솥이다. 표면에 무언가 떠올랐다 가라앉는다. 손 같다. 손가락이 기름을 긁는다.<br>
    솥 너머 통로에서 발소리가 다가온다. 무겁다. 앞치마 끈이 바닥을 끄는 소리.<br><br>
    끓는 기름은 불이 제일 좋아하는 것이다.`,
  o:[
    { l:'① 기름을 쏟아 불을 붙여 통로를 막는다.', k:'break', dc:15,
      ok:`솥을 발로 차 기울였다. 끓는 기름이 통로 바닥으로 쏟아진다. 거기에 불씨를 떨궜다.<br><br>통로가 불벽이 됐다. 발소리가 그 앞에서 멈췄다. 불 너머로 큰 그림자가 이쪽을 오래 본다. 넘어오지 않는다.<br>그사이 반대쪽으로 빠져나왔다.<br><br>기름에 뜬 손가락이 불 속에서 오그라드는 걸 봤다. 한참 꿈에 나올 것 같다.`,
      ng:`솥이 생각보다 무거웠다. 반만 기울었다.<br><br>쏟아진 기름이 이쪽 발 쪽으로 흘렀다. 불을 붙이기 전에 장화가 기름에 젖었다.<br>발소리가 빨라졌다. 젖은 장화로 미끄러지며 도망쳤다. 불은 결국 못 붙였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 기름을 조금 떠서 오래 갈 횃불을 만든다.', k:'fix', dc:14,
      ok:`작은 통에 기름을 한 국자 떴다. 솥 안의 것이 국자를 쫓아왔다. 국자를 빨리 뺐다.<br><br>천을 감은 막대에 기름을 먹이고 불을 붙였다. 한 번 붙으면 안 꺼진다. 이 아래는 길다.<br>솥 옆 선반에 소금 덩이가 있다. 비계를 절이던 것. 챙겼다.<br><br>발소리가 솥 앞에 닿기 전에 떠났다.`,
      ng:`기름을 뜨는데 국자에 손가락이 따라 올라왔다. 기름 속 그것의 손가락.<br><br>국자를 던졌다. 기름이 손등에 튀었다. 물집이 금방 올라온다.<br>횃불은 못 만들었다. 발소리가 바로 뒤였다.`,
      win:{ exp:16, dream:1, item:'소금 덩이' }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 천장으로 가는 줄',
  x:`천장에서 줄이 수백 가닥 내려온다. 끝마다 인형이 매달렸다.<br><br>
    줄이 당겨질 때마다 인형들이 한꺼번에 고개를 든다. 이쪽을 본다. 입을 벌린다. 이가 촘촘하다.<br>
    줄은 모두 위층 한곳으로 모인다. 거기서 누가 손가락을 움직인다.<br><br>
    줄은 마른 실이다. 마른 실은 불을 아래에서 위로 옮긴다.`,
  o:[
    { l:'① 제일 굵은 줄 끝에 불을 붙여 위로 올려 보낸다.', k:'break', dc:15, wake:1,
      ok:`굵은 줄 하나를 골라 손끝을 댔다. 불이 붙었다. 마력을 줄에 조금씩 실어 위로 밀었다.<br><br>불이 줄을 타고 올라간다. 이쪽 손을 떠났는데 손끝과 이어져 있다. 갈림길마다 원하는 줄로 꺾었다.<br>위층에서 무엇이 비명을 질렀다. 줄들이 일제히 늘어졌다. 인형들이 바닥에 떨어져 굴렀다.<br><br>불을 던진 게 아니다. 보냈다. 길을 따라, 원하는 데까지. 손끝에 아직 줄의 감촉이 남았다. 이제 불이 갈 길을 그려 줄 수 있다.`,
      ng:`불이 줄을 타다가 갈림길에서 엉뚱한 쪽으로 갔다.<br><br>옆 줄들로 번진다. 불붙은 인형들이 매달린 채 흔들린다. 하나가 떨어져 이쪽 어깨에 붙었다. 타면서 물었다.<br>떼어 냈다. 어깨가 데었고 잇자국이 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 다가오는 인형의 줄만 손끝으로 끊는다.', k:'fix', dc:14,
      ok:`인형이 다가오면 그 줄에 손끝을 댔다. 손톱만 한 불. 줄이 툭 끊어진다.<br><br>줄 끊긴 인형은 그 자리에 무너졌다. 하나씩. 불이 번지지 않게, 끊고 나면 손끝으로 불을 잡아 껐다.<br>열두 개를 끊고 공방을 지났다.<br><br>위층에서 손가락이 짜증 내듯 빨라졌다. 줄이 더 내려왔다. 그땐 이미 다음 방이었다.`,
      ng:`끊으려는데 인형이 먼저 왔다. 손끝에 이가 박혔다.<br><br>불을 붙이려던 손가락이다. 이 사이에서 불이 꺼졌다.<br>동료가 인형을 떼어 냈다. 손끝이 퉁퉁 부었다. 한동안 불이 잘 안 붙는다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C3', t:'성당 — 향로를 흔드는 것',
  x:`긴 옷을 입은 것이 아치 위를 걷는다. 손에 향로를 들었다. 흔든다.<br><br>
    향로 안에 불이 없다. 그것이 지나가는 자리마다 이쪽 불이 기운다. 향로 쪽으로. 빨려 들어간다.<br>
    손끝 불이 줄었다. 횃불도. 다들 불빛이 사그라드는 걸 본다.<br><br>
    저것은 불을 먹는다. 먹어서 뭘 하는지는 모른다.`,
  o:[
    { l:'① 마력을 쓴다 — 먹을 수 있는 만큼 먹인다.', k:'break', dc:15, cost:{ mana:20 },
      ok:`손바닥을 향로 쪽으로 펴고 불을 쏟았다. 쉬지 않고.<br><br>향로가 불을 빨아들인다. 빨아들인다. 뚜껑 틈에서 빛이 샌다. 긴 옷 소매가 그을린다.<br>마력이 바닥나기 직전에 향로가 터졌다. 긴 옷이 안에서부터 탔다. 아치 위에 재가 쌓였다.<br><br>다들 횃불이 다시 선다. 배부른 것은 터진다. 불도 그렇다.`,
      ng:`쏟는 만큼 향로가 먹는다. 끝이 없다.<br><br>마력이 바닥났다. 손끝이 차다. 그것이 고개를 돌려 이쪽을 본다. 더 내놓으라는 듯.<br>다가오는 것을 피해 아치 사이로 굴렀다. 한참 손바닥에 불이 안 붙었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-10, spirit:-8, mana:-5 } },
    { l:'② 불을 다 끄고 굶긴다.', k:'steady', dc:14,
      ok:`손끝 불을 껐다. 다들 횃불을 끄게 했다. 성당이 캄캄해졌다.<br><br>향로 흔드는 소리가 다가온다. 냄새를 맡듯 머뭇거린다. 먹을 게 없다.<br>소리가 멀어졌다. 한참 뒤 먼 어둠에서 누군가의 불이 꺼지는 게 보였다. 다른 일행인지 무엇인지 모른다.<br><br>불 쓰는 사람이 불을 끄고 기다렸다. 이상하게 따뜻했다.`,
      ng:`다 껐는데 이쪽 몸에 열이 남았다. 불 쓰는 몸이다.<br><br>향로가 이쪽 앞에서 멈췄다. 흔든다. 몸에서 열이 빠져나간다. 손가락부터 하얗게 언다.<br>동료가 끌어당겨 떼어 놨다. 한참 이가 덜덜 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-10, spirit:-12 } }
  ] },

{ at:'C4', t:'온실 — 알처럼 맺힌 갓',
  x:`양치식물 그늘에 둥근 갓이 줄지어 맺혔다. 주먹만 하다. 하얗고 매끈하다.<br><br>
    하나가 꿈틀했다. 껍질 속에서 무엇이 돌아눕는다. 알이다. 갓 모양을 한 알.<br>
    터지면 아까 그 짐승들이 나올 것이다. 수십 마리.<br><br>
    그늘 가장자리에 먹을 수 있는 버섯이 섞여 있다. 비슷하게 생겼다.`,
  o:[
    { l:'① 하나씩 손끝으로 속까지 지진다.', k:'break', dc:14,
      ok:`손끝을 갓 꼭대기에 대고 불을 안으로 밀었다. 겉은 그대로 두고 속만.<br><br>안에서 돌아눕던 것이 멎었다. 다음. 다음. 서른한 개.<br>다 지지고 나니 손끝이 얼얼하다. 그늘에서 터진 것은 하나도 없다.<br><br>겉을 태우면 가루가 날린다. 속만 익히면 조용하다. 조용한 게 낫다.`,
      ng:`스무 개째에서 손끝이 떨렸다. 불이 겉에 붙었다.<br><br>겉이 터지며 가루가 얼굴로 왔다. 그 소리에 남은 알들이 한꺼번에 꿈틀했다.<br>셋이 터졌다. 작은 것 셋이 발목으로 기어올랐다. 털어 내는 데 한참 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'② 젖은 흙을 덮고 밑에서 데워 찐다.', k:'fix', dc:14,
      ok:`알 무더기 위에 젖은 흙을 두껍게 덮었다. 흙 밑에 손을 넣어 열을 올렸다. 천천히.<br><br>흙에서 김이 올랐다. 안에서 꿈틀대는 소리가 났다가 잦아들었다.<br>흙을 걷으니 알들이 쪼그라들어 있다. 가루 한 점 안 날렸다.<br><br>불을 안 보이고 불로 일했다. 냄새는 났다. 익은 버섯 냄새.`,
      ng:`흙이 덜 젖었다. 열이 오르자 흙이 마르며 갈라졌다.<br><br>갈라진 틈으로 알 하나가 튀어 올라 터졌다. 가루가 눈에 들어갔다.<br>한쪽 눈이 한참 안 떠졌다. 알 몇 개는 흙 밑에서 아직 움직였다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-10, mind:-10 } },
    { l:'③ 그늘 가장자리에서 먹을 것만 가려 딴다.', k:'sense', dc:15,
      ok:`손끝 불을 바짝 대고 하나씩 봤다.<br><br>알은 대가 없다. 버섯은 대가 있다. 알은 불을 대면 안으로 움츠린다. 버섯은 안 움츠린다.<br>안 움츠리는 것만 한 줌 땄다. 알은 하나도 안 건드렸다.<br><br>불로 가린 버섯이다. 먹어도 된다. 아마.`,
      ng:`대가 있어 보이던 것이 손안에서 움츠렸다.<br><br>알이었다. 손바닥에서 터졌다. 손금 사이로 가루가 박혔다.<br>손을 한참 씻었다. 손금이 하얗게 일어난다.`,
      win:{ exp:15, dream:1, item:'야생 버섯' }, lose:{ hp:-8, spirit:-10 } }
  ] },

{ at:'C', t:'쉬는 자리 — 속까지 익힌다',
  x:`아까 잡은 것의 다리 하나를 들고 왔다. 짐승 다리처럼 생겼다. 대체로.<br><br>
    다들 배가 고프다. 아무도 먼저 먹자고 안 한다.<br>
    여기 것은 겉만 익으면 속이 아직 산다. 그걸 다들 오늘 봤다.<br><br>
    불은 이쪽 몫이다.`,
  o:[
    { l:'① 뼈까지 열을 넣어 속을 다 익힌다.', k:'fix', dc:14,
      ok:`다리를 두 손으로 쥐고 열을 안으로 밀었다. 겉이 아니라 뼈부터.<br><br>뼈 속이 먼저 익는다. 거기서부터 살이 바깥으로 익어 나온다. 겉은 마지막에 노릇해졌다.<br>칼로 갈랐다. 속까지 회색이다. 아무것도 안 움직인다.<br><br>한 입씩 나눴다. 맛은 말하지 않기로 했다. 배는 찼다.`,
      ng:`뼈까지 넣으려는데 열이 겉에서 막혔다. 겉이 타 버렸다.<br><br>칼로 가르자 속이 분홍이다. 움찔했다.<br>다 버렸다. 다들 말없이 말린 것을 씹었다. 탄내만 남았다.`,
      win:{ exp:15, dream:1, item:'짐승 고기', hp:6 }, lose:{ mind:-8, spirit:-6 } },
    { l:'② 고기는 치우고 다들 젖은 발을 데운다.', k:'heal', dc:14,
      ok:`고기는 멀리 치웠다. 대신 다들 신을 벗게 했다.<br><br>젖은 발을 하나씩 손바닥으로 감쌌다. 천천히 데웠다. 발가락 사이 하얗게 불은 데가 마른다.<br>마른 발로 자는 잠은 깊다. 다들 금방 잠들었다.<br><br>남의 발을 데우는 손. 이쪽 손도 같이 녹았다.`,
      ng:`셋째 사람 발을 데우다 졸았다. 손에 열이 몰렸다.<br><br>동료가 발을 확 뺐다. 발바닥에 물집이 잡혔다.<br>내일 걸어야 할 발이다. 미안하다는 말이 잘 안 나왔다.`,
      win:{ exp:14, dream:1, mind:6 }, lose:{ mind:-8, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 식칼을 쥔 것',
  x:`도마 앞에 앞치마 두른 것이 서 있다. 사람보다 한 뼘 크다. 등이 굽었다.<br><br>
    식칼로 도마를 친다. 쿵. 쿵. 도마 위에 아무것도 없다. 그래도 친다.<br>
    이쪽 냄새를 맡자 칼질이 멈췄다. 고개가 돌아간다. 얼굴 자리를 앞치마 끝으로 덮었다.<br><br>
    식칼은 쇠다. 쇠는 불을 잘 먹는다.`,
  o:[
    { l:'① 불덩이를 뭉쳐 얼굴에 던진다.', k:'break', dc:15,
      ok:`손바닥에 불을 뭉쳐 앞치마 덮인 얼굴로 던졌다.<br><br>앞치마가 붙었다. 그것이 칼을 든 채 제 얼굴을 친다. 불을 끄려고. 칼등으로, 칼날로.<br>제 칼에 제가 쓰러졌다. 앞치마가 다 탈 때까지 아무도 안 다가갔다.<br><br>다 타고 보니 앞치마 밑에 얼굴이 없었다. 앞치마가 얼굴이었다.`,
      ng:`던진 불을 그것이 식칼로 쳐 냈다. 불이 쪼개져 옆으로 튀었다.<br><br>그리고 칼이 이쪽으로 왔다. 팔을 들어 막았다. 칼등이었다. 팔뚝이 저리다. 칼날이었으면 팔이 없다.<br>다들 끌어당겨 도망쳤다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 마력을 쓴다 — 멀리서 식칼만 달군다.', k:'fix', dc:15, cost:{ mana:18 },
      ok:`식칼을 노려봤다. 손바닥을 칼 쪽으로 펴고 마력을 칼날에만 보냈다.<br><br>칼날이 붉어진다. 자루까지 열이 간다. 그것이 칼을 안 놓는다. 안 놓는다. 자루에서 연기가 난다.<br>마침내 놓았다. 손바닥이 자루 모양으로 탔다. 칼 없이 그것은 그냥 서 있다. 칼질 말고는 할 줄 아는 게 없다.<br><br>그 옆을 지났다. 바닥의 식칼은 아직 붉다.`,
      ng:`칼이 달아오르기 전에 그것이 걸어왔다.<br><br>칼에 마력을 보내는 데 정신이 팔려 피할 생각을 못 했다. 반쯤 달군 칼이 어깨를 스쳤다.<br>베인 데가 동시에 데었다. 피가 안 났다. 그게 더 아팠다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6, mana:-5 } }
  ] },

{ at:'C2', t:'공방 — 안 타는 얼굴',
  x:`사기 인형 셋이 이쪽으로 걸어온다. 관절마다 철사가 삐걱인다.<br><br>
    불을 던졌다. 옷이 타고 머리카락이 탔다. 얼굴은 멀쩡하다. 그을음도 안 남았다.<br>
    사기는 이미 한 번 불에 들어갔다 나온 것이다. 불이 두 번째로 할 말이 없다.<br><br>
    인형들이 웃는다. 이가 보이게.`,
  o:[
    { l:'① 한 얼굴에 불을 붙여 오래 붙든다.', k:'break', dc:15,
      ok:`불을 한 얼굴에만 붙이고 놓지 않았다.<br><br>사기 얼굴이 처음으로 붉어졌다. 붉다가 누렇게. 유약이 녹아 눈물처럼 흘렀다. 인형이 걸음을 멈췄다.<br>녹은 얼굴로는 웃지 못한다. 이가 녹은 사기에 묻혔다. 나머지 둘도 하나씩.<br><br>오래 걸렸다. 손이 아직 뜨겁다. 셋 다 멈췄다.`,
      ng:`붙들고 있는데 사기가 끄떡없다.<br><br>그사이 다른 인형 하나가 팔에 매달렸다. 달아오른 사기 얼굴이 팔에 닿았다. 데었다. 그리고 물렸다.<br>떼어 냈을 때 팔에 화상과 잇자국이 겹쳐 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 한 번 달구고 찬물을 끼얹는다.', k:'gaze', dc:15, wake:1,
      ok:`불을 얼굴에만 모았다. 달궈지자 불을 거두고 물통을 끼얹었다.<br><br>쩍. 사기 얼굴에 거미줄 같은 금이 갔다. 한 번 더 툭 치자 얼굴이 쏟아졌다. 안에 이만 남았다. 철사에 엮여서.<br>나머지 둘도 똑같이 했다. 달구고, 식히고.<br><br>불은 데우는 데서 끝나는 줄 알았다. 식는 것까지가 불의 일이다. 거두는 손이 피우는 손만큼 중요하다는 걸 손이 알았다. 이제 언제 거둘지가 보인다.`,
      ng:`물을 끼얹는 때가 일렀다. 덜 달궜다.<br><br>얼굴이 멀쩡하다. 젖었을 뿐이다. 젖은 사기 얼굴이 웃으며 다가왔다.<br>물통이 비었다. 물린 손등을 쥐고 물러났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 안 식는 손',
  x:`오늘 불을 많이 썼다. 쉬는데 손이 안 식는다.<br><br>
    손바닥을 바닥에 대면 돌이 따뜻해진다. 옆 사람이 손을 뻗었다가 움찔한다.<br>
    불 쓰는 사람이 제일 조심하는 때다. 손이 불을 쥔 채 잠들면 잠든 손이 불을 놓는다.<br><br>
    오늘 밤 이 손으로는 잠들면 안 된다.`,
  o:[
    { l:'① 열을 바닥으로 천천히 내린다.', k:'steady', dc:14,
      ok:`손바닥을 찬 돌에 대고 숨을 길게 쉬었다. 한 숨에 열 하나씩.<br><br>돌이 달아오른다. 다른 돌로 옮겼다. 다섯 번째 돌에서 손이 평소 온도가 됐다.<br>데운 돌은 다들 품에 하나씩 넣고 잤다.<br><br>남은 불은 버리지 않고 나눴다. 버릇이 될 것 같다.`,
      ng:`내리다가 졸았다. 손이 돌 위에서 미끄러졌다.<br><br>옆에 둔 짐 자루에 닿았다. 연기가 났다. 자루 하나가 탔다. 안에 말린 것이 들어 있었다.<br>다들 말없이 남은 것을 나눴다.`,
      win:{ exp:14, dream:1, hp:6 }, lose:{ mind:-8, spirit:-6 } },
    { l:'② 다친 동료 곁에서 열을 나눠 준다.', k:'heal', dc:14,
      ok:`오늘 피를 많이 흘린 동료가 떨고 있다. 그 등에 손바닥을 댔다.<br><br>남은 열을 아주 얇게 펴서 보냈다. 동료 떨림이 잦아든다. 입술 색이 돌아온다.<br>둘 다 잠들었다. 손이 안전한 데서 식었다.<br><br>불이 남으면 나누면 된다. 받는 사람이 있으면.`,
      ng:`열을 너무 한꺼번에 보냈다.<br><br>동료가 신음하며 몸을 뺐다. 등에 손바닥 모양이 붉게 떴다.<br>아무도 아무 말도 안 했다. 손을 무릎에 올려놓고 밤을 샜다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C3', t:'성당 — 매달린 관',
  x:`오르간 관이 거꾸로 매달렸다. 굵은 것, 가는 것. 발밑 아치 가까이까지 내려왔다.<br><br>
    성가대 노래가 들리기 시작했다. 입이 너무 많은 노래. 들으면 무릎이 굽는다. 무릎 꿇게 하는 노래다.<br>
    관 아래쪽 입이 열려 있다. 바람이 들어가면 운다.<br><br>
    더운 바람은 위로 간다. 관 속으로.`,
  o:[
    { l:'① 마력을 쓴다 — 관에 더운 바람을 밀어 넣어 노래를 덮는다.', k:'fix', dc:15, cost:{ mana:18 },
      ok:`제일 굵은 관 밑에 손을 펴고 열을 올렸다. 더운 공기가 관으로 빨려 들어간다.<br><br>관이 울었다. 낮고 큰 소리가 성당을 덮는다. 노래가 그 밑에 깔렸다.<br>무릎이 펴졌다. 다들 소리 속을 걸어 지났다.<br><br>관 소리가 그친 뒤에도 귀가 웅웅거렸다. 노래는 한참 안 들렸다.`,
      ng:`관이 울었는데 노래와 같은 음이었다.<br><br>둘이 겹쳐 더 커졌다. 다들 무릎을 꿇었다. 이쪽도.<br>노래가 끝날 때까지 꿇고 있었다. 일어났을 때 무엇이 머리를 쓰다듬고 간 느낌이 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-12, spirit:-8, mana:-5 } },
    { l:'② 관 입을 녹여 막는다.', k:'break', dc:14,
      ok:`관 입을 하나씩 손으로 쥐고 녹였다. 납이 무르다. 입이 오므라들어 붙었다.<br><br>노래가 관을 타고 오던 길이 막혔다. 성당 안 노래가 반으로 줄었다. 반은 견딜 만하다.<br>무릎이 덜 굽는다. 다들 이를 악물고 지났다.<br><br>녹인 납이 손가락 사이에 굳었다. 떼어 내는 데 오래 걸렸다.`,
      ng:`녹인 납이 아래로 안 흐르고 위로 흘렀다. 여기서는 그렇다.<br><br>손목을 타고 팔꿈치까지 올라왔다. 뜨겁다. 떼어 낼 수가 없다.<br>그동안 노래가 계속됐다. 무릎이 꺾였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C4', t:'온실 — 갓이 난 얼굴',
  x:`정원사 하나가 물뿌리개를 들고 화분에 물을 준다. 빈 물뿌리개다.<br><br>
    얼굴에 갓이 났다. 눈 자리, 입 자리. 귀에서도. 몸은 아직 사람이다. 손톱도, 손목시계도.<br>
    갓 뿌리는 머릿속으로 들어갔다. 갓이 몸을 입었다. 사람을 겉옷처럼.<br><br>
    다 태우면 몸도 탄다. 사람이었던 몸이다.`,
  o:[
    { l:'① 바늘만 한 불로 갓 뿌리만 지진다.', k:'break', dc:15, wake:1,
      ok:`불을 줄였다. 줄였다. 손끝에 바늘만 한 불이 섰다. 그 바늘을 갓과 살이 만나는 데로 넣었다.<br><br>갓 하나가 오그라들어 떨어졌다. 다음. 다음. 그것이 물뿌리개를 떨어뜨렸다. 마지막 갓이 떨어지자 몸이 무너졌다. 무너진 얼굴이 사람 얼굴이다. 눈을 감겨 줬다.<br>손목시계는 아직 간다.<br><br>불은 크게 해야 센 줄 알았다. 작게 할수록 깊이 들어간다. 손끝에 선 바늘이 아직 안 꺼진다. 이걸로 꿰맬 수도 있겠다.`,
      ng:`바늘이 흔들렸다. 갓이 아니라 살을 찔렀다.<br><br>그것이 소리 없이 이쪽을 돌아봤다. 갓들이 한꺼번에 가루를 뿜었다.<br>눈이 따갑다. 뒷걸음질 치다 화분 사이에 넘어졌다. 그것은 다시 물을 주러 갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 사람이었던 몸째 다 태운다.', k:'break', dc:15,
      doom:{ title:'불붙은 정원사', what:'불붙은 정원사에게 끌어안겼습니다', dc:15, sec:60,
        text:`두 손으로 불을 밀었다. 정원사가 통째로 불에 들어갔다.<br><br>갓이 타며 비명을 지른다. 몸이 비틀거리다 이쪽으로 온다. 불붙은 채로. 팔을 벌리고.<br>끌어안겼다. 젖은 갓 타는 연기가 얼굴을 덮는다. 팔이 안 풀린다. 사람 팔 힘이 아니다.<br><br>불 쓰는 사람은 제 불에 안 탄다. 남의 몸에 옮겨 붙은 불은 이미 제 불이 아니다.`,
        dieText:`온실 바닥에 까만 것이 둘 겹쳐 있다.<br><br>한쪽 손목에 시계가 아직 간다.<br>다른 쪽 손끝은 유난히 까맣다. 그 둘레에서 갓 하나가 새로 올라오고 있다.` },
      ok:`두 손으로 불을 밀고 바로 물러섰다. 정원사가 불에 들어갔다.<br><br>갓이 타며 비명을 지른다. 몸이 비틀거리며 이쪽으로 온다. 두 걸음 더 물러섰다. 다섯 걸음째에 그것 무릎이 꺾였다.<br>다 탔다. 손목시계만 남았다. 아직 간다.<br><br>시계를 주웠다. 따뜻하다. 뒤에 이름이 새겨져 있다. 읽지 않았다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'C', t:'통로 — 불이 줄어드는 길',
  x:`이 통로에 들어서자 횃불이 줄었다. 손끝 불도.<br><br>
    바람은 없다. 숨이 가쁘다. 공기가 묽다. 다들 하품을 한다. 잠이 쏟아진다.<br>
    불이 먼저 안다. 불이 줄어드는 데서는 사람도 오래 못 버틴다.<br><br>
    통로 끝은 아직 안 보인다.`,
  o:[
    { l:'① 손끝 불을 감싸 들고 걸음마다 잰다.', k:'steady', dc:14,
      ok:`불을 손 안에 감싸고 불빛 크기를 봤다. 걸음마다.<br><br>스무 걸음에 반으로 줄었다. 서른에는 반의반. 마흔쯤에서 다시 커졌다. 통로 끝이 그 근처다.<br>다들 숨을 아껴 뛰게 했다. 마흔 걸음에서 불이 살아났다. 다들 바닥에 주저앉아 숨을 몰아쉬었다.<br><br>불은 숨의 동무다. 같이 줄고 같이 산다.`,
      ng:`세다가 이쪽 머리가 먼저 흐려졌다.<br><br>몇 걸음인지 잊었다. 불이 꺼졌다. 다들 어둠 속에서 서로를 더듬었다.<br>나와 보니 하나가 무릎을 꿇은 채 졸고 있었다. 되돌아가 끌어냈다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-10, spirit:-6 } },
    { l:'② 불씨를 멀리 던져 끝을 찾는다.', k:'sense', dc:14,
      ok:`불씨를 앞으로 던졌다. 날아가는 동안 줄었다가 어느 지점에서 확 커졌다.<br><br>거기다. 공기가 바뀌는 자리. 거리를 쟀다. 서른다섯 걸음.<br>다들 숨을 크게 쉬게 하고 한숨에 뛰었다.<br><br>불을 던지면 앞을 먼저 가 본다. 불은 겁이 없다.`,
      ng:`던진 불씨가 바로 꺼졌다. 어디서 꺼졌는지도 못 봤다.<br><br>짐작으로 뛰었다. 짐작이 짧았다. 숨이 끊기기 직전에 겨우 나왔다.<br>머리가 한참 지끈거렸다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C', t:'통로 — 탄내를 따라오는 것',
  x:`아까 태운 것이 따라온다.<br><br>
    반쯤 탔다. 까만 껍질이 걸을 때마다 부서진다. 부서진 자리 밑에서 새 살이 분홍으로 올라온다.<br>
    그것이 고개를 든다. 냄새를 맡는다. 이쪽 손끝 냄새다. 저를 태운 불 냄새를 기억한다.<br><br>
    화염술사한테는 늘 탄내가 난다. 숨길 수가 없다.`,
  o:[
    { l:'① 이번엔 끝까지 태운다.', k:'break', dc:15,
      ok:`도망가지 않았다. 다가오기를 기다렸다가 두 손으로 불을 감쌌다.<br><br>새 살까지, 그 아래까지. 그것이 몸부림친다. 손을 떼지 않았다. 까만 것이 재가 될 때까지.<br>재를 발로 흩었다. 다시 안 붙는다.<br><br>반만 태운 불은 원한을 남긴다. 불은 끝까지 가야 한다.`,
      ng:`감싸는 사이 그것이 손을 물었다. 타면서 물었다.<br><br>불이 이쪽 손으로 번질 뻔했다. 손을 빼냈다. 그것은 다시 반쯤 탄 채 어둠으로 기어갔다.<br>이제 그것이 기억하는 냄새에 이쪽 피 냄새가 더해졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 손을 흙과 물로 씻어 냄새를 지운다.', k:'hide', dc:14,
      ok:`물이 고인 데서 손을 박박 씻었다. 흙을 문질러 다시 씻었다. 손끝, 손톱 밑, 팔꿈치까지.<br><br>그것이 다가오다 고개를 갸웃했다. 이쪽 앞을 지나쳐 갔다. 그대로 어둠 쪽으로.<br>숨을 내쉬었다. 손끝이 차다. 오랜만이다.<br><br>탄내가 안 나는 손. 낯설다. 오늘만이다.`,
      ng:`씻어도 손톱 밑 그을음이 안 빠진다.<br><br>그것이 이쪽 앞에서 멈췄다. 손톱 쪽으로 코를 댄다.<br>물렸다. 손톱 하나가 들렸다. 동료가 그것을 쳐서 쫓았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C', t:'끝 방 — 젖은 큰 것',
  x:`마지막 방은 물이 발목까지 찼다. 한가운데 큰 것이 엎드렸다.<br><br>
    몸이 젖었다. 계속 젖는다. 살갗에서 물이 배어 나온다. 칼에 베인 자리도 물이 메운다. 메운 자리가 살이 된다.<br>
    불을 대면 김만 오른다. 오래 대야 한다. 오래 대려면 오래 버텨야 한다.<br><br>
    다들 이쪽을 본다. 여기서 불은 이쪽 몫이다.`,
  o:[
    { l:'① 한 자리에 불을 붙들고 놓지 않는다.', k:'break', dc:16, wake:1,
      ok:`등 한가운데 한 자리를 정했다. 거기에 손바닥을 대고 불을 붙들었다.<br><br>김이 오른다. 그것이 몸부림친다. 동료들이 팔다리를 붙잡았다. 불을 놓지 않았다. 숨 백 번. 이백 번. 김이 줄고 연기가 났다. 그 자리가 말랐다. 마른 자리는 안 나았다.<br>동료들이 마른 자리를 찔렀다. 그것이 물속에 가라앉았다.<br><br>세게 하는 것보다 오래 하는 게 어려웠다. 불이 손에서 한 번도 안 흔들렸다. 오래 붙드는 불. 손이 그 길이를 알았다.`,
      ng:`백 번째 숨에서 손이 미끄러졌다.<br><br>불이 떨어지자 그 자리에 물이 금방 찼다. 처음부터 다시다. 그것이 몸을 뒤집어 이쪽을 물속에 눌렀다.<br>동료들이 끌어냈다. 폐에 물이 들어갔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-18, spirit:-8 } },
    { l:'② 마력을 전부 쏟아 방째 끓인다.', k:'break', dc:15, cost:{ mana:25 },
      ok:`다들 물 밖 돌계단에 올라가게 했다. 두 손을 물에 넣었다. 마력을 남김없이.<br><br>방의 물이 데워진다. 끓는다. 그것이 끓는 물속에서 일어나려다 다시 엎드렸다. 물이 그것을 메우는 대신 익혔다.<br>마력이 바닥나자 손을 뺐다. 손이 벌겋다. 그것은 안 움직인다.<br><br>제 물에 익었다. 마지막엔 늘 제 것이 제 발목을 잡는다.`,
      ng:`물이 미지근해졌을 때 마력이 바닥났다.<br><br>그것은 오히려 기분 좋은 듯 몸을 폈다. 이쪽 손이 물속에 있다. 그 손을 무언가 잡았다.<br>동료들이 잡아 뺐다. 손목에 물컹한 손자국이 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8, mana:-5 } },
    { l:'③ 동료들 칼에 불을 입힌다.', k:'bond', dc:15,
      ok:`동료들 칼날을 하나씩 손으로 쓸었다. 날마다 불이 얇게 붙었다.<br><br>불 입은 칼이 그것을 벤다. 벤 자리가 지져져 물이 안 찬다. 넷이 번갈아 베었다. 이쪽은 불이 꺼지면 다시 입혔다.<br>열두 번째 칼질에 그것이 멈췄다.<br><br>칼을 쥔 건 동료들이다. 날에 붙은 불은 이쪽 것이다. 불이 남의 손에서도 탔다.`,
      ng:`불을 입히자마자 동료 손이 데었다. 칼을 떨어뜨렸다.<br><br>그사이 그것이 그 동료를 덮쳤다. 다들 달려들어 겨우 빼냈다.<br>다들 잠깐 이쪽 손을 피했다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-10 } }
  ] }

]);

// ------------------------------------------
// 권사 · 내공
// ------------------------------------------
kJob('fist', 'C', [

{ at:'C', t:'통로 — 주먹이 묻히는 것',
  x:`통로를 막고 무엇이 서 있다. 사람 둘 너비. 살갗이 반죽 같다.<br><br>
    쳤다. 주먹이 손목까지 묻혔다가 빠졌다. 자국이 천천히 메워진다.<br>
    주먹은 맞는 것을 안다. 맞으면 뼈가 울려야 한다. 이건 울릴 뼈가 없다. 힘이 다 물렁한 데로 흩어진다.<br><br>
    그것이 이쪽으로 한 걸음 기울었다. 덮으려는 것이다.`,
  o:[
    { l:'① 주먹을 댄 채 거리 없이 한 번 더 민다.', k:'break', dc:15, wake:1,
      ok:`주먹을 그것 몸에 댄 채로 멈췄다. 떼지 않았다.<br><br>발끝에서 허리, 허리에서 어깨, 어깨에서 주먹으로. 거리 없이 힘만 보냈다. 주먹은 한 치도 안 움직였다. 대신 그것 등 쪽이 터졌다. 힘이 흩어질 틈이 없었다.<br>그것이 반으로 접히며 주저앉았다.<br><br>멀리서 내지르는 것만 주먹인 줄 알았다. 닿은 채로도 친다. 닿은 데서 시작하는 주먹이 하나 생겼다.`,
      ng:`주먹을 댄 채로 힘을 보내는데 반죽이 손목을 감쌌다.<br><br>힘이 다 반죽에 먹혔다. 그것이 이쪽으로 기울어 덮친다. 얼굴까지 묻혔다.<br>동료들이 어깨를 잡아 뽑아냈다. 숨이 한참 안 돌아왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 다리를 걸어 넘어뜨리고 지난다.', k:'evade', dc:14,
      ok:`몸통은 안 쳤다. 낮게 들어가 발목 같은 데를 걸었다.<br><br>그것이 제 무게로 넘어졌다. 넘어진 반죽은 일어나는 데 오래 걸린다. 밟지 않고 옆으로 돌아 지났다.<br>뒤에서 그것이 바닥에서 몸을 모으는 소리가 났다.<br><br>안 맞는 것은 안 친다. 넘어뜨리는 것도 권법이다.`,
      ng:`걸었는데 발목이 아니었다. 발목 자리에 아무것도 없었다.<br><br>헛디딘 다리가 그것 몸에 박혔다. 무릎까지 빨려 들었다.<br>빼는 데 한참. 바지가 반죽에 녹아 너덜거린다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 안에서 차는 고기',
  x:`갈고리에 걸린 고기 하나가 흔들린다. 다른 것들은 가만한데.<br><br>
    안에서 무엇이 찬다. 고기 겉에 주먹 모양이 솟았다 꺼진다. 작은 주먹이다. 여럿.<br>
    곧 찢고 나올 것이다. 줄은 길고 고기는 많다. 이것 하나가 아니다.<br><br>
    주먹은 주먹을 안다. 저 안의 것이 어디를 치는지 보인다.`,
  o:[
    { l:'① 솟는 자리에 맞춰 주먹을 꽂는다.', k:'break', dc:15,
      doom:{ title:'다시 닫히는 살', what:'고기 속으로 팔이 빨려 들어갑니다', dc:15, sec:60,
        text:`안에서 솟는 순간 바깥에서 쳤다. 정확히 맞았다.<br><br>주먹이 고기를 뚫고 들어갔다. 안의 것이 주먹에 맞아 터졌다. 손을 빼려는데 안 빠진다.<br>뚫린 살이 손목 둘레로 닫힌다. 닫히면서 당긴다. 팔꿈치까지 들어갔다. 레일이 돌기 시작했다.<br><br>고기는 빈자리를 싫어한다. 안에 있던 것 대신 들어올 것을 찾았다.`,
        dieText:`레일은 다음 칸으로 갔다.<br><br>갈고리에 고기 하나가 걸려 있다. 겉이 매끈하다. 다른 것보다 조금 길다.<br>가끔 겉에 주먹 모양이 솟는다. 크다. 어른 주먹이다.` },
      ok:`안에서 솟는 순간 바깥에서 쳤다. 맞자마자 손을 뺐다.<br><br>고기 속에서 터지는 소리가 났다. 꿈틀대던 것이 멎었다. 뚫린 자리가 손 뺀 자리를 따라 닫혔다. 반 박자 늦게.<br>다른 고기들이 흔들리기 시작했다. 같은 박자로 치고 빼고, 치고 뺐다. 줄 끝까지.<br><br>마지막 고기를 치고 손을 봤다. 손목에 붉은 실 같은 게 한 가닥 붙어 있다. 떼어 냈다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 내공을 쓴다 — 손바닥을 대고 속만 울린다.', k:'break', dc:14, cost:{ qi:18 },
      ok:`손바닥을 고기 겉에 붙였다. 뚫지 않는다. 내공을 손바닥 너머로 밀었다.<br><br>겉은 그대로다. 안에서 무엇이 한 번 크게 떨더니 멈췄다. 겉에 솟던 주먹 모양이 가라앉았다.<br>다음 고기, 다음 고기. 손바닥만 댔다 뗐다. 뚫린 데가 없으니 닫힐 것도 없다.<br><br>안을 치는 데 겉을 열 필요는 없다.`,
      ng:`내공이 고기 속에서 흩어졌다. 살이 너무 두꺼웠다.<br><br>안의 것이 울림에 놀라 더 세게 찼다. 겉이 찢어졌다. 작은 손이 튀어나와 이쪽 손목을 잡았다.<br>털어 내는 데 한참. 손목에 손톱자국이 다섯 줄.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6, qi:-5 } }
  ] },

{ at:'C2', t:'공방 — 사기를 치는 손',
  x:`사기 인형이 작업대에서 뛰어내렸다. 무릎 높이다. 입을 벌린다. 진짜 이가 촘촘하다.<br><br>
    주먹으로 치면 깨진다. 깨진 사기는 칼이 된다. 마디가 다 베일 것이다.<br>
    인형 팔다리는 철사로 이었다. 어깨, 팔꿈치, 무릎. 관절은 어디든 같다. 꺾이는 쪽이 있고 안 꺾이는 쪽이 있다.<br><br>
    셋이 더 내려온다.`,
  o:[
    { l:'① 주먹으로 그냥 깬다.', k:'break', dc:14,
      ok:`마디를 세워 정수리를 쳤다. 사기가 쪼개진다. 다음, 다음, 다음.<br><br>넷을 깼다. 바닥에 이가 흩어졌다. 사기 조각과 섞여 반짝인다.<br>주먹을 펴 봤다. 마디에 잔금처럼 베인 데가 여럿이다. 피가 배어 나온다. 깊지는 않다.<br><br>마디는 원래 터지라고 있는 데다. 아물면 더 단단해진다.`,
      ng:`셋째를 깨는 순간 조각이 마디 사이에 박혔다.<br><br>주먹을 못 쥐겠다. 그사이 넷째가 종아리를 물었다.<br>박힌 조각을 이로 뽑았다. 뽑은 조각에 남의 이가 붙어 있었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 잡아서 관절을 거꾸로 꺾는다.', k:'gaze', dc:14,
      ok:`뛰어오르는 인형 팔을 잡았다. 팔꿈치를 안 꺾이는 쪽으로 꺾었다. 철사가 튕겨 나갔다.<br><br>무릎도. 어깨도. 깨지 않고 풀었다. 인형이 바닥에서 머리만 굴린다. 이를 딱딱 부딪친다.<br>넷을 다 풀었다. 마디는 하나도 안 베였다.<br><br>치는 것만 권법이 아니다. 잡는 데서도 시작한다.`,
      ng:`잡은 팔이 손안에서 돌았다. 인형 관절은 사람 관절과 반대로 돌았다.<br><br>인형이 그대로 몸을 돌려 손목을 물었다. 떼어 내니 손목에 반달이 둘.<br>사람 손으로 사람 아닌 것을 사람처럼 잡았다. 그게 틀렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } },
    { l:'③ 장화 바닥으로 밟아 깬다.', k:'steady', dc:13,
      ok:`손은 아꼈다. 다가오는 인형을 발바닥으로 눌러 밟았다. 장화 바닥은 두껍다.<br><br>밟고, 비틀었다. 사기가 장화 밑에서 갈린다. 이가 장화 가죽을 물었다가 놓는다.<br>넷을 다 밟았다. 장화 바닥에 이 자국이 촘촘하다.<br><br>주먹은 다음 것에 쓴다.`,
      ng:`밟는데 인형이 발목으로 기어올랐다. 장화 목 안으로 머리를 들이밀었다.<br><br>정강이를 물렸다. 장화를 벗어 던지고서야 떨어졌다.<br>맨발로 사기 조각 위에 섰다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 터진 마디에 든 것',
  x:`쉬는 틈에 주먹을 봤다. 마디가 다 터졌다. 오늘 친 것이 많다.<br><br>
    터진 데 하나가 이상하다. 상처 속에 하얀 실 같은 게 보인다. 아까 친 것의 살인지, 가루인지.<br>
    손톱으로 건드리자 실이 안으로 조금 들어갔다. 살아 있다.<br><br>
    맨손으로 싸우는 사람에게 주먹은 전부다. 이 손으로 다음 것을 쳐야 한다.`,
  o:[
    { l:'① 내공을 쓴다 — 마디에서 밖으로 밀어낸다.', k:'heal', dc:14, cost:{ qi:16 },
      ok:`숨을 아랫배에서 팔로, 팔에서 손등으로 끌어올렸다. 그다음 손끝 쪽으로 밀었다.<br><br>마디 상처에서 하얀 실이 한 가닥씩 밀려 나왔다. 꿈틀대며. 다 나오자 피가 맑아졌다.<br>나온 것은 돌로 짓이겼다.<br><br>안에 든 것은 안에서 민다. 겉에서 파면 더 들어간다.`,
      ng:`밀어내는데 실이 거꾸로 팔 쪽으로 도망갔다. 내공을 따라.<br><br>팔뚝 안쪽이 근질거린다. 한참 뒤에야 다시 손등으로 몰아냈다. 다 나왔는지는 모르겠다.<br>팔뚝을 자꾸 긁게 된다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-10, mind:-8, qi:-5 } },
    { l:'② 상처를 짜내고 소금물로 씻어 동인다.', k:'fix', dc:14,
      ok:`마디를 눌러 피를 짜냈다. 아프다. 하얀 실이 피를 따라 나온다.<br><br>소금 한 줌을 물에 풀어 마디를 담갔다. 따갑다. 실이 소금물 속에서 오그라든다.<br>천으로 마디마다 동였다. 주먹을 쥐니 쥐어진다.<br><br>마디가 터지는 건 익숙하다. 터진 데로 남의 것이 들어오는 건 처음이다.`,
      ng:`짜내는데 실이 더 깊이 들어갔다.<br><br>소금물에 담그자 손등 안쪽에서 무엇이 꿈틀했다. 따끔한 게 아니라 간지럽다.<br>동였다. 동인 천 밑이 밤새 간지러웠다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'성당 — 아치 위의 진각',
  x:`아치 위에 무언가 붙어 있다. 여럿. 손바닥만 한 것들이 회반죽 틈마다 박혀 있다.<br><br>
    다리가 길다. 걸음마다 발목을 노린다. 하나하나 떼어 내다간 끝이 없다.<br>
    진각이면 된다. 발을 굴러 울림을 보내면 붙은 것은 떨어진다. 권사가 제일 먼저 배우는 것이다.<br><br>
    다만 발밑은 땅이 아니다. 거꾸로 매달린 천장이다. 그 아래는 어둠이다.`,
  o:[
    { l:'① 울림을 발밑 한 뼘에만 가둬 구른다.', k:'break', dc:15, wake:1,
      ok:`발을 들었다. 굴렀다. 다만 울림을 넓게 보내지 않았다. 발바닥 아래 한 뼘에 다 쏟았다.<br><br>발밑 것들이 튀어 올라 떨어졌다. 한 뼘 바깥은 그대로다. 아치는 금 하나 안 갔다.<br>한 걸음 가서 또. 한 뼘씩. 그렇게 건넜다.<br><br>울림은 넓을수록 센 줄 알았다. 좁게 모으니 더 세다. 발이 땅을 다루는 법이 하나 늘었다. 이제 어디까지 울릴지를 발이 정한다.`,
      ng:`한 뼘에 가두려다 울림이 새었다.<br><br>발밑 아치에 금이 갔다. 소리가 아래로 떨어진다. 한참 뒤에 아주 멀리서 무엇이 깨지는 소리가 돌아왔다.<br>붙어 있던 것들이 금 사이로 쏟아져 발목을 물었다. 뛰어서 건넜다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 크게 굴러 한 번에 다 떨군다.', k:'break', dc:15,
      doom:{ title:'깨진 천장', what:'갈라진 아치와 함께 어둠 아래로 떨어집니다', dc:15, sec:55,
        text:`힘껏 굴렀다. 울림이 아치 전체로 퍼졌다.<br><br>붙어 있던 것들이 한꺼번에 떨어졌다. 그리고 아치가 대답했다. 발밑에서 금이 사방으로 달린다.<br>바닥이 기울었다. 발이 미끄러진다. 손에 잡히는 건 부서지는 회반죽뿐이다.<br><br>아래는 어둠이다. 어둠이 이쪽 발목을 당기는 것 같다.`,
        dieText:`성당 천장에 사람 하나만 한 구멍이 났다.<br><br>구멍 가장자리 회반죽에 발자국 하나가 깊이 찍혀 있다. 구른 자국이다.<br>떨어지는 소리는 끝까지 안 들렸다.` },
      ok:`힘껏 굴렀다. 울림이 아치 전체로 퍼졌다.<br><br>붙어 있던 것들이 한꺼번에 우수수 떨어져 구멍 아래로 사라졌다. 발밑에서 금이 달리기 시작했다. 바로 다음 아치로 뛰었다.<br>뒤에서 방금 서 있던 자리가 떨어져 나갔다. 다들 이쪽 아치로 건너왔다. 아슬아슬하게.<br><br>길은 비었다. 되돌아갈 길은 없어졌다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'C4', t:'온실 — 닫은 숨',
  x:`온실 통로에 노란 가루가 자욱하다. 갓 덮인 짐승 셋이 그 안에 있다.<br><br>
    가루를 마시면 목에서 갓이 자란다. 아까 그런 사람을 봤다.<br>
    숨을 다스리는 것이 내공의 시작이다. 숨을 닫고 싸우는 법도 안다. 길게는 못 간다.<br><br>
    짐승들이 이쪽 숨소리를 듣고 고개를 든다.`,
  o:[
    { l:'① 숨을 닫고 들어가 싸운다.', k:'steady', dc:15,
      ok:`숨을 아랫배에 가두고 닫았다. 가루 속으로 들어갔다.<br><br>첫째, 둘째. 주먹 하나씩. 셋째가 주머니를 터뜨렸다. 가루가 얼굴을 덮는다. 숨은 닫혀 있다.<br>셋째까지 쓰러뜨리고 가루 밖으로 나와서야 숨을 열었다. 가슴이 터질 것 같다. 깨끗하다.<br><br>닫은 숨으로 백을 셌다. 어제는 여든이었다.`,
      ng:`셋째에서 숨이 열렸다. 저절로.<br><br>가루가 목으로 들어왔다. 혀가 텁텁하다. 짐승은 쓰러졌다. 이쪽도 기침에 무릎을 꿇었다.<br>동료가 끌어냈다. 목구멍이 한참 근질거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 내공을 쓴다 — 장으로 바람을 밀어 가루를 걷는다.', k:'break', dc:15, cost:{ qi:20 }, wake:1,
      ok:`두 손바닥을 앞으로 모았다. 숨을 끝까지 들이쉬고, 손바닥으로 내쉬었다. 내공을 실어.<br><br>손바닥 앞 공기가 밀려 나간다. 가루가 한 덩이로 통로 끝까지 쓸려 갔다. 짐승들이 갑자기 맑은 공기 속에 드러났다. 숨을 쉬며 들어가 하나씩 쳤다.<br>손바닥이 뜨겁다. 아무것도 안 만졌는데.<br><br>손이 닿지 않는 데까지 손이 갔다. 손바닥 앞에 한 자쯤 손이 더 생긴 것 같다. 그 한 자가 앞으로 길어질 것이다.`,
      ng:`밀어낸 바람이 벽에 부딪혀 되돌아왔다. 가루를 싣고.<br><br>얼굴 정면으로 맞았다. 눈, 코, 입. 짐승들이 그 틈에 달려들었다.<br>정강이를 물리고 겨우 빠져나왔다. 기침이 오래 갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, spirit:-6, qi:-5 } }
  ] },

{ at:'C', t:'운기 — 등 뒤의 숨',
  x:`다들 잔다. 이쪽은 앉아서 운기를 한다.<br><br>
    숨이 반쯤 돌았을 때 등 뒤에 무엇이 앉았다. 숨이 목덜미에 닿는다. 차다. 이쪽 숨 박자를 따라 한다.<br>
    운기 중에 몸을 갑자기 틀면 기가 엇갈린다. 엇갈리면 오래 앓는다.<br><br>
    등 뒤의 숨이 조금씩 가까워진다.`,
  o:[
    { l:'① 운기를 끊지 않고 숨 끝에서 팔꿈치만 뒤로 보낸다.', k:'steady', dc:15,
      ok:`숨을 끝까지 돌렸다. 돌아온 숨이 아랫배에 닿는 순간 팔꿈치를 뒤로 찔렀다. 몸통은 그대로.<br><br>등 뒤에서 무엇이 꺾이는 소리가 났다. 찬 숨이 멎었다.<br>숨을 한 바퀴 더 돌리고 눈을 떴다. 등 뒤에 무릎만 한 것이 접혀 있다. 이쪽 앉은 자세 그대로.<br><br>운기는 안 끊겼다. 몸이 맑다.`,
      ng:`팔꿈치를 보내는 순간 숨이 거꾸로 돌았다.<br><br>가슴이 찢어지는 것 같다. 팔꿈치는 허공을 쳤다. 등 뒤의 것이 목덜미를 핥고 갔다.<br>밤새 가슴을 쥐고 앉아 있었다.`,
      win:{ exp:18, dream:2, qi:10 }, lose:{ hp:-10, mind:-10, qi:-5 } },
    { l:'② 운기를 끊고 돌아서며 친다.', k:'break', dc:14,
      ok:`숨을 끊었다. 돌아서며 주먹을 내질렀다.<br><br>맞았다. 무엇이 어둠으로 굴러갔다. 다시 안 왔다.<br>가슴이 결린다. 끊긴 기가 가슴께에 뭉쳤다. 주먹으로 가슴을 두 번 치자 조금 풀렸다.<br><br>오늘 밤 운기는 날렸다. 목은 남았다.`,
      ng:`돌아섰는데 아무것도 없다.<br><br>끊긴 기가 가슴에 박혔다. 숨이 안 쉬어진다. 그때 다시 등 뒤에서 찬 숨이 닿았다.<br>다들 깨워서야 떨어졌다. 가슴이 아침까지 아팠다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C1', t:'도축장 — 냉동실',
  x:`냉동실 문을 열었다. 하얀 김이 바닥으로 쏟아진다.<br><br>
    고기가 얼어 매달렸다. 겉에 서리가 꼈다. 서리 밑에서 무엇이 아주 느리게 움직인다. 얼어도 자란다.<br>
    지나가려면 이 방을 건너야 한다. 길다. 다들 입김이 하얗다. 하나는 벌써 입술이 파랗다.<br><br>
    뒤에서 문이 천천히 닫히기 시작했다.`,
  o:[
    { l:'① 내공을 쓴다 — 몸을 데워 언 동료를 업고 건넌다.', k:'steady', dc:15, cost:{ qi:18 },
      ok:`입술 파란 동료를 업었다. 내공을 등으로 돌렸다. 등이 화로가 된다.<br><br>얼음 바닥을 한 발씩 건넜다. 매달린 고기들이 지나갈 때마다 서리를 털며 고개를 돌린다. 안 봤다.<br>건너편 문을 어깨로 밀고 나왔다. 동료 입술에 색이 돌아온다.<br><br>등에 업힌 사람 숨이 따뜻해지는 걸 등으로 느꼈다.`,
      ng:`업고 반쯤 왔을 때 내공이 식었다.<br><br>둘 다 얼어 간다. 무릎이 얼음에 붙었다. 매달린 고기 하나가 서리를 털고 이쪽으로 기울었다.<br>뒤따르던 동료들이 둘을 끌고 나왔다. 무릎 살갗이 얼음에 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6, qi:-5 } },
    { l:'② 닫히는 문을 받쳐 둔다.', k:'break', dc:14,
      ok:`문이 닫히는 쪽에 섰다. 문짝을 손바닥으로 받쳤다. 무겁다. 문이 아니라 무엇이 문을 민다.<br><br>밀리지 않았다. 다들 냉동실을 건너 저쪽 문까지 갈 때까지. 마지막 사람이 손을 흔들자 손을 떼고 뛰었다.<br>등 뒤에서 문이 쾅 닫혔다. 저쪽 문은 다들 붙잡고 있었다.<br><br>손바닥이 얼어 문짝 모양이다.`,
      ng:`받친 손바닥이 문짝에 얼어붙었다.<br><br>문이 계속 민다. 손바닥을 떼어 내니 살갗이 문에 남았다. 문이 닫혔다. 이쪽을 안에 두고.<br>다들 저쪽 문을 열고 기다렸다. 얼음 바닥을 맨손으로 기어서 건넜다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 얼어서 멈춘 고기를 한 덩이 떼어 간다.', k:'sense', dc:14,
      ok:`매달린 것 중 서리 밑이 안 움직이는 것을 골랐다. 얼어서 멈춘 것.<br><br>손날로 쳐서 한 덩이 떼어 냈다. 꽁꽁 얼었다. 녹으면 어떻게 될지는 모른다. 녹기 전에 굽기로 했다.<br>품에 넣지 않고 손에 들고 건넜다.<br><br>여기서 얻은 것은 품에 안 넣는다. 그게 여기 규칙 같다.`,
      ng:`떼어 낸 덩이가 손안에서 녹기 시작했다. 이쪽 손이 따뜻하니까.<br><br>녹은 데가 손바닥을 쥐었다. 아주 약하게. 던졌다.<br>손바닥에 붉은 실이 몇 가닥 붙어 있었다. 털어 냈다.`,
      win:{ exp:15, dream:1, item:'짐승 고기' }, lose:{ hp:-8, mind:-10 } }
  ] },

{ at:'C2', t:'공방 — 팽팽한 줄',
  x:`천장에서 줄이 내려와 인형 넷에 이어졌다. 인형들이 줄에 매달려 이쪽으로 걸어온다.<br><br>
    줄은 손으로 못 끊는다. 칼도 미끄러진다. 질기다.<br>
    줄이 팽팽하다. 위층에서 누가 쥐고 있다. 팽팽한 것은 울린다. 퉁기면 끝까지 간다.<br><br>
    주먹은 울림을 보내는 것이다. 사람 몸이든, 바위든.`,
  o:[
    { l:'① 줄 한가운데를 손날로 튕겨 울림을 위로 보낸다.', k:'break', dc:15, wake:1,
      ok:`팽팽한 줄 하나에 손날을 댔다. 그리고 퉁기듯 쳤다. 짧게.<br><br>줄이 운다. 울림이 위로 달려간다. 위층에서 무엇이 손가락을 데인 듯 소리를 질렀다. 줄이 늘어졌다. 다른 줄도 차례로.<br>인형 넷이 바닥에 무너졌다. 위층이 조용해졌다.<br><br>주먹은 닿은 데만 치는 줄 알았다. 이어진 것이면 끝까지 간다. 손날 끝에서 위층까지 길이 보였다. 이제 이어진 것은 다 길이다.`,
      ng:`쳤는데 줄이 안 울었다. 위에서 줄을 늦췄다.<br><br>늦춘 줄이 손날에 감겼다. 위에서 다시 당긴다. 팔이 위로 끌려 올라간다.<br>동료가 인형째 줄을 끊어 냈다. 손날에 줄 자국이 깊이 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 인형 머리만 하나씩 쳐서 떨군다.', k:'break', dc:14,
      ok:`줄은 두고 인형을 쳤다. 사기 머리를 손바닥으로.<br><br>머리가 깨지면 줄이 매달 데를 잃는다. 넷을 쳤다. 줄 끝에 철사 목만 덜렁거린다.<br>위층에서 새 인형이 내려오기 시작했다. 그땐 이미 방을 나왔다.<br><br>손바닥에 사기 가루가 하얗다.`,
      ng:`인형 하나를 치면 줄이 다른 인형을 당겨 옆에서 오게 한다.<br><br>치고 나면 다음이 벌써 옆구리다. 셋째를 칠 때 넷째가 허리를 물었다.<br>위층에서 웃음소리 같은 게 들렸다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C3', t:'성당 — 울림을 받는다',
  x:`거꾸로 선 종이 발밑에서 저절로 울었다.<br><br>
    소리가 몸을 친다. 진짜로 친다. 가슴에 주먹을 맞은 것 같다. 다들 비틀거린다. 하나는 코피가 났다.<br>
    종 안에서 무엇이 종을 흔들고 있다. 한 번 울 때마다 조금씩 세진다.<br><br>
    권사는 맞는 것도 배운다. 맞은 힘을 몸 안에 두지 않고 발로 흘리는 것.`,
  o:[
    { l:'① 울림을 몸으로 받아 발로 흘린다.', k:'steady', dc:15,
      ok:`종 앞에 섰다. 무릎을 굽히고 발을 넓게. 울림이 왔다. 가슴으로 받았다.<br><br>받은 힘을 가슴에서 허리로, 허리에서 다리로, 발바닥으로. 아치에 흘렸다. 아치가 대신 울었다.<br>다들 이쪽 뒤에 섰다. 이쪽이 받는 동안 뒤는 조용하다. 그렇게 종 옆을 지났다.<br><br>다리가 아직 떨린다. 이쪽 다리가 종이 됐다.`,
      ng:`받은 힘이 허리에서 걸렸다.<br><br>가슴 안에서 종이 울린다. 계속. 숨을 쉴 때마다.<br>지나고 나서도 한참 가슴 속 종이 안 멎었다. 피 섞인 기침을 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 종 테두리에 손바닥을 대 울림을 죽인다.', k:'break', dc:15,
      ok:`종이 우는 틈에 다가가 테두리에 손바닥을 댔다. 우는 박자와 반대로 밀었다.<br><br>울림이 손바닥에서 멎는다. 종이 떨다가 조용해졌다. 안에서 흔들던 것이 멈칫한다.<br>그 틈에 다들 지나갔다. 손을 뗐다. 종이 다시 울기 시작했을 땐 아무도 없었다.<br><br>손바닥이 저리다. 오래 갈 것 같다.`,
      ng:`손바닥을 대는 순간 종이 크게 울었다.<br><br>울림이 손바닥을 타고 팔로, 어깨로. 이가 덜덜 부딪친다. 손이 종에 붙어 안 떨어진다.<br>동료가 허리를 잡아 떼어 냈다. 팔이 한참 안 움직였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-10 } }
  ] },

{ at:'C4', t:'온실 — 목에서 자라는 것',
  x:`동료 하나가 기침을 멈추지 못한다. 아까 가루를 마셨다.<br><br>
    입안을 보니 목젖 뒤가 하얗다. 솜처럼. 기침할 때마다 조금씩 커진다.<br>
    그대로 두면 숨길이 막힌다. 손을 넣어 꺼낼 수는 없다. 깊다.<br><br>
    남의 몸에 기를 넣는 법을 조금 안다. 조금.`,
  o:[
    { l:'① 내공을 쓴다 — 등에 손을 대고 속에서 밀어낸다.', k:'heal', dc:15, cost:{ qi:20 }, wake:1,
      ok:`동료를 앉히고 등 한가운데 손바닥을 댔다. 내공을 아주 얇게 넣었다.<br><br>남의 몸은 길이 다르다. 숨길을 따라 더듬었다. 목 뒤에서 막힌 데가 손바닥에 잡혔다. 거기를 아래에서 위로 밀었다.<br>동료가 크게 기침을 했다. 하얀 덩어리가 바닥에 떨어졌다. 바닥에서 꿈틀댄다. 밟았다.<br><br>남의 몸 속 길이 손바닥에 그려졌다. 지도처럼. 손바닥이 처음으로 남의 몸을 읽었다. 이 지도는 쓸수록 넓어질 것이다.`,
      ng:`내공이 동료 몸에서 길을 잃었다.<br><br>숨길이 아니라 가슴께로 갔다. 동료가 가슴을 쥐고 쓰러졌다. 하얀 것은 그대로다.<br>둘이 같이 앉아 한참 숨을 골랐다. 동료 기침은 계속됐다.`,
      win:{ exp:22, dream:2, mind:5 }, lose:{ mind:-10, spirit:-8, qi:-5 } },
    { l:'② 등을 쳐서 토하게 한다.', k:'break', dc:14,
      ok:`동료를 앞으로 숙이게 했다. 날개뼈 사이를 손바닥으로 쳤다. 세게. 한 번.<br><br>동료가 꺽 소리를 내며 토했다. 하얀 것이 반쯤 나왔다. 손가락으로 집어 마저 뽑았다.<br>뽑힌 것에 실뿌리가 붙어 있다. 동료 목에서 피가 조금 났다. 숨은 쉰다.<br><br>세게 친 등에 손바닥 자국이 붉다. 동료는 고맙다고 했다. 아파하면서.`,
      ng:`쳤는데 너무 셌다. 동료가 앞으로 고꾸라졌다.<br><br>하얀 것은 안 나왔다. 대신 동료가 갈비를 쥔다. 금이 갔을지도 모른다.<br>하얀 것은 결국 저 혼자 기침으로 반쯤 나왔다. 반은 남았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-8, mind:-10 } }
  ] },

{ at:'C', t:'쉬는 자리 — 주먹에 남은 감촉',
  x:`쉬는 틈에 주먹을 쥐었다 폈다.<br><br>
    오늘 친 것들의 감촉이 아직 마디에 남았다. 물렁한 것, 닫히는 것, 주먹을 붙잡는 것. 사람 살도 짐승 살도 아니었다.<br>
    모래, 나무, 돌. 주먹은 그 순서로 배웠다. 이런 건 순서에 없었다.<br><br>
    감촉이 안 지워진다. 다음 주먹이 망설일 것 같다.`,
  o:[
    { l:'① 돌벽을 쳐서 감촉을 덮는다.', k:'break', dc:14,
      ok:`벽 앞에 섰다. 돌이다. 진짜 돌.<br><br>쳤다. 아는 감촉이다. 단단하고 정직하다. 쉰 번을 쳤다. 마디에 돌 감촉이 다시 앉았다.<br>주먹을 폈다. 손이 제 손 같다.<br><br>모르는 것을 친 날에는 아는 것을 친다. 그래야 주먹이 길을 안 잃는다.`,
      ng:`쳤는데 돌이 물렀다. 아니, 돌 겉에 무엇이 자라 있었다.<br><br>주먹이 그 속에 묻혔다. 물렁한 감촉이 하나 더 늘었다.<br>손을 빼고 한참 바지에 닦았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } },
    { l:'② 앉아서 운기로 손을 씻는다.', k:'steady', dc:14,
      ok:`앉아 숨을 돌렸다. 숨을 손끝까지 보냈다가 다시 거둬들였다. 열 번.<br><br>손끝에 남은 것이 숨을 따라 빠져나가는 것 같다. 감촉이 옅어진다. 지워지지는 않는다.<br>안 지워지는 건 두기로 했다. 주먹이 아는 게 하나 늘었다고 치기로.<br><br>눈을 떴을 때 손이 따뜻하다.`,
      ng:`숨을 돌릴 때마다 감촉이 오히려 또렷해진다.<br><br>눈을 감으면 주먹 속에서 무엇이 닫힌다. 붙잡는다.<br>운기를 접었다. 손이 차다.`,
      win:{ exp:14, dream:1, mind:6 }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 내려오는 식칼',
  x:`앞치마 두른 것이 식칼을 든다. 사람 팔만 한 칼이다.<br><br>
    내려친다. 도마가 갈라진다. 들어 올린다. 다시 내려친다. 한 박자도 안 틀린다. 그 박자가 이쪽으로 걸어온다.<br>
    맨손이다. 칼을 맨손으로 받는 법은 있다. 두 번 해 봤다. 두 번 다 연습용 나무칼이었다.<br><br>
    다음 박자가 머리 위에 있다.`,
  o:[
    { l:'① 박자 사이로 들어가 손바닥 사이에 칼을 받는다.', k:'evade', dc:16,
      ok:`칼이 올라가는 박자에 들어갔다. 내려오는 칼을 두 손바닥으로 눌러 잡았다.<br><br>칼이 이마 한 치 앞에서 멈췄다. 손바닥이 뜨겁다. 그것이 칼을 빼려 당긴다. 그 힘을 따라 같이 당겼다. 칼이 그것 손에서 빠졌다.<br>칼을 바닥에 박았다. 칼 없는 것은 박자를 잃고 서 있다.<br><br>손바닥 사이가 벌겋다. 나무칼보다 훨씬 무거웠다.`,
      ng:`받긴 받았다. 손바닥이 미끄러졌다.<br><br>칼이 이마를 스쳐 어깨에 떨어졌다. 칼등 쪽이었다. 칼날 쪽이었으면.<br>어깨가 내려앉았다. 동료들이 끌어냈다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, spirit:-6 } },
    { l:'② 내공을 쓴다 — 팔뚝을 굳혀 막고 들어간다.', k:'steady', dc:15, cost:{ qi:18 },
      ok:`내공을 팔뚝에 모았다. 팔뚝이 단단히 선다. 칼날 옆면을 팔뚝으로 쳐 냈다.<br><br>칼이 옆으로 빗나가 도마에 박혔다. 그 틈에 품으로 들어가 명치를 쳤다. 앞치마 밑이 물컹하다. 그래도 그것이 꺾였다.<br>박힌 칼이 안 빠진다. 그것이 칼을 잡아당기는 동안 다들 지나갔다.<br><br>팔뚝에 칼 옆면 자국이 길게 남았다. 베이지는 않았다.`,
      ng:`팔뚝이 덜 굳었다. 칼이 비껴가면서 살을 저몄다.<br><br>피가 팔꿈치로 흐른다. 품으로 들어갔지만 주먹에 힘이 안 실렸다.<br>그것이 이쪽을 앞치마로 밀어냈다. 바닥을 굴렀다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6, qi:-5 } },
    { l:'③ 칼 든 손목만 노려 친다.', k:'break', dc:15,
      ok:`칼이 아니라 손목을 봤다. 칼은 손목을 따라온다.<br><br>내려오는 손목에 주먹을 올려 쳤다. 손목이 꺾였다. 칼이 손에서 돌아 그것 제 발등에 박혔다.<br>그것이 처음으로 박자를 놓쳤다. 발등의 칼을 내려다보며 서 있다.<br><br>그 옆을 지났다. 칼은 한 번만 막으면 된다. 손목은 하나뿐이다.`,
      ng:`손목을 쳤는데 손목이 안 꺾였다. 관절이 거꾸로 붙어 있다.<br><br>주먹이 튕겼다. 칼이 옆구리를 스쳤다.<br>옷이 갈라지고 그 밑이 갈라졌다. 깊지 않다. 깊지 않은데 오래 아팠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 속이 빈 큰 인형',
  x:`공방 한가운데 큰 사기 인형이 앉아 있다. 사람 둘 키.<br><br>
    두드려 보니 속이 비었다. 통 하고 운다. 빈 속에서 무엇이 이를 딱딱 부딪친다. 작은 것들이 가득 들어 있다.<br>
    겉을 깨면 안의 것들이 한꺼번에 쏟아진다. 안 깨면 이 인형이 일어난다. 무릎 관절이 벌써 삐걱인다.<br><br>
    주먹으로 친 울림은 속을 한 바퀴 돌아 나온다.`,
  o:[
    { l:'① 첫 울림이 돌아오는 박자에 두 번째를 친다.', k:'break', dc:15, wake:1,
      ok:`가슴께를 한 번 쳤다. 통. 울림이 안으로 들어가 빈 속을 돈다. 귀를 댔다. 돌아온다.<br><br>돌아오는 박자에 같은 자리를 다시 쳤다. 두 울림이 안에서 부딪쳤다. 안에서 딱딱 대던 소리가 일제히 멎었다. 겉에는 금 하나 없다.<br>큰 인형이 일어서다 말고 도로 앉았다. 속이 다 깨진 채로.<br><br>주먹 하나는 하나인 줄 알았다. 두 번째가 첫 번째를 따라잡으면 하나보다 크다. 손이 박자를 들었다. 이제 주먹 사이의 틈이 들린다.`,
      ng:`두 번째가 빨랐다. 울림이 엇갈렸다.<br><br>겉에 금이 쫙 갔다. 금 사이로 작은 이들이 쏟아져 나온다. 인형 조각들이.<br>발목, 종아리, 무릎. 털어 내는 데 오래 걸렸다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 일어나기 전에 무릎 관절을 친다.', k:'gaze', dc:14,
      ok:`삐걱이는 무릎 관절을 봤다. 사기 둘을 쇠못 하나가 잇는다.<br><br>못 머리를 손바닥으로 쳤다. 못이 안으로 들어가 버렸다. 무릎이 못 펴진다.<br>인형이 일어나려다 기울었다. 안에서 딱딱 소리가 화난 듯 빨라졌다. 그것은 앉은 채로 남았다.<br><br>안 깼다. 못 일어나게만 했다. 그거면 지나갈 수 있다.`,
      ng:`못을 쳤는데 못이 아니라 손바닥이 튕겼다.<br><br>무릎이 펴졌다. 인형이 일어섰다. 일어서는 것만으로 바닥이 흔들렸다.<br>다들 뛰었다. 뒤에서 큰 것이 따라오며 안에서 웃는 소리가 났다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 발바닥',
  x:`장화를 벗었다. 발바닥이 엉망이다.<br><br>
    오늘 디딘 것들. 젖은 고기, 사기 조각, 둥근 아치, 물렁한 균. 어느 것도 땅이 아니었다.<br>
    주먹은 발에서 나온다. 발이 땅을 못 믿으면 주먹이 안 나온다.<br><br>
    발바닥이 아직 땅을 의심한다.`,
  o:[
    { l:'① 맨발로 서서 마보를 오래 선다.', k:'steady', dc:14,
      ok:`맨발로 돌바닥에 섰다. 무릎을 굽히고 오래.<br><br>발바닥이 처음엔 떤다. 돌이 차다. 차고 단단하다. 단단한 것이 발바닥으로 올라온다. 숨 삼백 번.<br>장화를 다시 신었다. 발이 장화 안에서 자리를 잡는다.<br><br>땅은 여기도 있다. 발이 기억하면 된다.`,
      ng:`서 있는데 돌바닥이 아주 조금 움직였다. 숨을 쉬듯.<br><br>발바닥이 그걸 느꼈다. 다리가 풀렸다.<br>장화를 다시 신었다. 발이 장화 안에서 계속 떨렸다.`,
      win:{ exp:14, dream:1, hp:6 }, lose:{ mind:-8, spirit:-8 } },
    { l:'② 다들 발을 주물러 혈을 풀어 준다.', k:'heal', dc:14,
      ok:`옆 사람 발을 잡았다. 발바닥 가운데 오목한 데를 엄지로 눌렀다.<br><br>동료가 신음하다가 한숨을 쉰다. 다음 사람. 다음. 다섯 사람 발을 다 풀었다.<br>다들 금방 잠들었다. 이쪽 발은 아무도 안 풀어 줬다. 괜찮다. 엄지가 따뜻하다.<br><br>남의 발을 주무르면 제 발도 조금 풀린다.`,
      ng:`누르는 자리가 틀렸다.<br><br>동료 다리가 경련을 일으켰다. 쥐가 났다. 한참 펴 주느라 둘 다 못 잤다.<br>미안하다고 했다. 동료는 웃었다. 웃다가 또 쥐가 났다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-10, spirit:-4 } }
  ] },

{ at:'C3', t:'성당 — 입이 많은 성가대원',
  x:`성가대석에서 하나가 내려왔다. 긴 옷을 입었다. 얼굴이 입이다. 입이 다섯.<br><br>
    다섯이 다른 음으로 노래한다. 들으면 다리 힘이 빠진다. 무릎이 저절로 굽는다.<br>
    주먹을 얼굴로 넣으면 입이 문다. 다섯 개가.<br><br>
    노래는 숨에서 나온다. 숨은 목 아래에서 나온다.`,
  o:[
    { l:'① 내공을 쓴다 — 목 아래 숨 자리를 한 점으로 친다.', k:'break', dc:15, cost:{ qi:18 },
      ok:`얼굴은 안 봤다. 목 아래, 쇄골이 만나는 오목한 데를 봤다. 노래할 때마다 거기가 들썩인다.<br><br>내공을 손가락 두 개 끝에 모아 거기를 찔렀다. 노래가 다섯 음 한꺼번에 끊겼다. 입들이 벌어진 채 소리가 안 나온다.<br>숨을 못 쉬는 것은 노래도 못 한다. 그것이 무릎을 꿇었다.<br><br>무릎이 다시 펴졌다. 이쪽 무릎이.`,
      ng:`찌르는 순간 노래가 높아졌다. 다리에서 힘이 쭉 빠졌다.<br><br>손가락이 목이 아니라 턱에 닿았다. 입 하나가 손가락을 물었다.<br>빼냈다. 손가락 두 마디에 이 자국이 둥글다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-8, qi:-5 } },
    { l:'② 숨을 아랫배에 박고 노래를 버틴다.', k:'steady', dc:14,
      ok:`숨을 아랫배에 가라앉혔다. 노래가 귀로 들어와도 아랫배까지는 못 내려오게.<br><br>무릎이 굽으려 한다. 버텼다. 다들 이쪽 어깨를 잡고 버텼다. 그것이 다가와 얼굴을 들이민다. 다섯 입이 노래한다.<br>안 굽혔다. 그것이 노래를 멈추고 고개를 갸웃했다. 그리고 성가대석으로 돌아갔다.<br><br>안 꿇는 것은 재미가 없나 보다.`,
      ng:`버티는데 노래가 아랫배까지 내려왔다.<br><br>무릎이 꺾였다. 그것이 머리 위에서 노래한다. 다섯 입이 정수리 가까이.<br>동료들이 일으켜 세워 끌고 갔다. 머리카락이 한 줌 빠져 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-12, spirit:-8 } }
  ] },

{ at:'C4', t:'온실 — 정원사를 입은 것',
  x:`화단 사이에서 정원사가 일어섰다. 무릎에 흙이 묻었다. 모자 밑이 하얗다.<br><br>
    걷는 게 이상하다. 무릎이 아니라 허리부터 움직인다. 안에서 무엇이 사람을 들고 걷는다.<br>
    주먹 쓰는 사람은 몸을 안다. 사람 몸은 어디를 잡으면 못 움직이는지. 이 몸은 사람 몸이었다.<br><br>
    다만 지금 이 몸을 움직이는 건 사람이 아니다.`,
  o:[
    { l:'① 껴안아 관절을 잠근다.', k:'break', dc:15,
      doom:{ title:'화단의 뿌리', what:'균사에 감겨 화단 속으로 끌려 들어갑니다', dc:15, sec:60,
        text:`뒤로 돌아 들어가 두 팔을 감았다. 어깨와 팔꿈치를 잠갔다. 사람 몸이면 이걸로 끝이다.<br><br>안 끝났다. 잠근 팔 속에서 하얀 실이 이쪽 소매로 기어 나왔다. 손목으로, 팔뚝으로.<br>정원사가 뒤로 넘어졌다. 이쪽을 깔고. 화단 흙 위로. 흙 속에서 실이 마중 나온다.<br><br>잠근 건 이쪽이 아니었다.`,
        dieText:`화단에 정원사가 둘 누워 있다. 겹쳐서.<br><br>둘 다 모자 밑이 하얗다.<br>며칠 뒤 그중 하나가 일어나 걷기 시작했다. 허리부터. 발을 넓게 딛는다.` },
      ok:`뒤로 들어가 팔을 잠갔다. 소매로 하얀 실이 기어 나오는 걸 보자마자 놓았다.<br><br>놓으면서 허리를 찼다. 사람 허리가 아니라 안의 것이 붙든 자리. 정원사가 반으로 접히며 쓰러졌다. 안에서 무엇이 찢어지는 소리.<br>더는 안 일어났다. 몸이 이제 그냥 사람 몸이다.<br><br>소매를 털었다. 실 두 가닥이 떨어져 흙으로 기어갔다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 허리 뒤를 장으로 쳐 안의 것만 떨군다.', k:'gaze', dc:15,
      ok:`걷는 게 허리부터다. 그러면 붙든 데가 허리다.<br><br>등 뒤로 돌아 허리 한가운데를 손바닥으로 쳤다. 사람 뼈는 놔두고 그 안쪽만.<br>정원사가 멈췄다. 모자가 떨어졌다. 하얀 것이 목덜미에서 스르르 빠져나와 흙으로 떨어졌다. 몸이 사람처럼 무너졌다. 무릎부터.<br><br>무릎부터 무너지는 걸 보고 알았다. 이제 사람이다. 죽은 사람.`,
      ng:`허리를 쳤는데 하얀 것이 손바닥으로 옮겨 붙었다.<br><br>손바닥이 하얗게 일어난다. 따끔거린다. 정원사가 돌아서 이쪽 어깨를 잡았다.<br>동료들이 떼어 냈다. 손바닥을 한참 문질러 씻었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C', t:'통로 — 무는 문',
  x:`나무문이다. 문틀이 이상하게 두껍다. 문짝 가장자리가 젖었다.<br><br>
    누가 손잡이를 잡자 문틀이 닫혔다. 위아래로. 입처럼. 손끝을 겨우 뺐다.<br>
    문틀 안쪽에 이가 줄지어 났다. 나무가 아니다.<br><br>
    다른 길은 없다.`,
  o:[
    { l:'① 문틀 위아래 이음매를 주먹으로 친다.', k:'break', dc:15,
      ok:`문틀이 벌어지는 때를 기다렸다. 벌어졌다. 위쪽 이음매를 쳤다. 아래쪽도.<br><br>턱이 빠진 것처럼 문틀이 벌어진 채 늘어졌다. 다물려고 떤다. 못 다문다.<br>문을 열었다. 다들 이 사이로 지났다. 마지막 사람이 지나자 문틀이 천천히 다시 붙기 시작했다.<br><br>턱은 어디나 같다. 이음매가 약하다.`,
      ng:`위쪽 이음매를 치는 순간 문틀이 다물렸다.<br><br>주먹이 이 사이에 걸렸다. 손목까지. 동료들이 문틀을 벌려 겨우 뺐다.<br>손등에 이 자국이 줄지어 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, mind:-6 } },
    { l:'② 손바닥을 대고 다무는 박자를 듣는다.', k:'sense', dc:14,
      ok:`문짝에 손바닥을 댔다. 문틀이 숨 쉬는 게 느껴진다. 들숨에 벌어지고 날숨에 다문다.<br><br>들숨이 시작될 때 문을 열고 사람 하나씩 보냈다. 하나가 지나면 다음 들숨. 다섯 번.<br>마지막에 이쪽이 지났다. 날숨이 등 뒤에서 닫혔다. 옷자락이 조금 잘렸다.<br><br>문도 숨을 쉬면 박자가 있다.`,
      ng:`세던 박자가 중간에 바뀌었다. 문이 이쪽이 세는 걸 알았다.<br><br>셋째 사람 때 문틀이 일찍 닫혔다. 그 사람 가방이 반으로 잘렸다. 사람은 무사하다.<br>이쪽은 손잡이를 쥔 채 얼어 있었다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C', t:'통로 — 끝에 남은 숨',
  x:`오늘 너무 많이 쳤다. 팔이 무겁다. 숨이 가쁘다.<br><br>
    앞에서 하나가 또 온다. 작다. 빠르다. 다리가 여럿이다.<br>
    지친 주먹은 힘으로 안 나간다. 힘을 짜내면 어깨만 나간다.<br><br>
    숨은 아직 남았다. 조금.`,
  o:[
    { l:'① 마지막 숨을 내쉬는 끝에 주먹을 얹는다.', k:'break', dc:15, wake:1,
      ok:`힘을 짜내지 않았다. 숨을 길게 내쉬었다. 내쉬는 숨 맨 끝, 더 내쉴 게 없는 자리에 주먹을 놓았다.<br><br>주먹이 가볍게 나갔다. 가볍게 닿았다. 그것이 벽까지 날아갔다. 힘을 쓴 기억이 없다.<br>그 자리에 서서 숨을 다시 들이켰다. 들이켜는 숨이 아랫배까지 내려간다.<br><br>힘이 남았을 때 치는 법은 배웠다. 숨이 남았을 때 치는 법이 있었다. 몸이 그 끝자리를 기억한다. 지쳐도 칠 데가 생겼다.`,
      ng:`숨 끝을 기다리다 숨이 먼저 끊겼다.<br><br>주먹이 안 나갔다. 그것이 정강이를 타고 올라 허벅지를 물었다.<br>떼어 내는 데 남은 힘을 다 썼다. 그 자리에 앉아 한참 못 일어났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 치지 않고 흘려 피하며 동료에게 넘긴다.', k:'evade', dc:14,
      ok:`그것이 뛰어오를 때 몸을 반만 틀었다. 그것이 지나쳐 뒤로 갔다. 뒤에 동료가 있다.<br><br>동료가 쳤다. 끝났다. 이쪽은 한 번도 안 쳤다.<br>지쳤을 땐 남의 주먹을 빌린다. 다음엔 이쪽이 빌려준다.<br><br>숨을 골랐다. 동료가 어깨를 툭 쳤다.`,
      ng:`몸을 트는데 다리가 안 따라왔다.<br><br>그것이 옆구리에 붙었다. 다리가 여럿이라 떼어 내기 어렵다.<br>동료가 떼어 줬다. 옆구리에 작은 구멍이 여섯.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C', t:'끝 방 — 가운데가 없는 것',
  x:`마지막 방에 큰 것이 있다. 여럿이 엉겨 하나가 됐다. 팔이 많고 머리도 여럿이다.<br><br>
    친 데마다 다른 쪽이 받는다. 머리를 치면 팔이 대신 아파하고, 팔을 치면 다른 머리가 운다.<br>
    권사는 가운데를 친다. 사람이든 짐승이든 무게가 모이는 자리가 있다.<br><br>
    이것은 무게가 계속 옮겨 다닌다.`,
  o:[
    { l:'① 무게가 옮겨 가는 길목에서 가운데를 잡는다.', k:'break', dc:16, wake:1,
      ok:`치지 않고 봤다. 동료가 한쪽을 칠 때마다 무게가 어디로 도망가는지.<br><br>왼쪽 머리에서 등으로, 등에서 오른 다리로. 길이 있다. 늘 등 한가운데를 지난다. 거기서 기다렸다. 무게가 지나가는 순간 쳤다.<br>큰 것이 한꺼번에 굳었다. 머리 여럿이 동시에 입을 벌렸다. 소리 없이. 무너졌다.<br><br>가운데는 한자리에 있는 줄 알았다. 지나가는 길목도 가운데다. 손이 이제 움직이는 가운데를 잡는다.`,
      ng:`기다리던 순간 무게가 다른 길로 갔다.<br><br>주먹이 빈 데를 쳤다. 그것 팔 셋이 이쪽을 감았다.<br>동료들이 팔을 쳐서 겨우 풀었다. 갈비가 결린다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-18, spirit:-8 } },
    { l:'② 내공을 전부 실어 장으로 민다.', k:'break', dc:15, cost:{ qi:25 },
      ok:`어디가 가운데든 상관없게 한다. 손바닥 둘을 몸통에 대고 내공을 남김없이 밀었다.<br><br>힘이 그것 몸 전체로 퍼졌다. 무게가 도망갈 데가 없다. 다 울렸다.<br>큰 것이 뒤로 물러서더니 엉긴 데가 풀렸다. 여럿이 따로따로 바닥에 떨어졌다. 하나하나는 작다.<br><br>동료들이 하나씩 끝냈다. 이쪽은 손바닥을 댄 채 한참 서 있었다.`,
      ng:`밀었다. 힘이 퍼지기 전에 그것이 무게를 손바닥 쪽으로 몰았다.<br><br>힘이 그대로 되돌아왔다. 팔이 꺾이며 뒤로 날아갔다.<br>가슴 속이 뒤집혔다. 피를 토했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-8, qi:-5 } },
    { l:'③ 팔 하나를 잠가 동료들에게 칠 틈을 준다.', k:'bond', dc:15,
      ok:`팔 하나를 잡아 어깨째 잠갔다. 그것이 무게를 그 팔로 몰아 빼려 한다.<br><br>안 놓았다. 무게가 이쪽 팔에 몰려 있는 동안 나머지가 비었다. 동료들이 빈 데를 쳤다.<br>무게가 돌아갈 데를 잃은 것이 주저앉았다.<br><br>치는 건 동료들이 했다. 잡는 것도 주먹이다.`,
      ng:`잠근 팔이 몸에서 떨어졌다. 그것이 스스로 뗐다.<br><br>떨어진 팔을 끌어안은 채 넘어졌다. 팔이 품 안에서 꿈틀댄다.<br>그사이 그것이 다른 팔로 이쪽을 쳤다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-6 } }
  ] }

]);

// ------------------------------------------
// 폭파공 · 자원 없음
// ------------------------------------------
kJob('blaster', 'C', [

{ at:'C', t:'통로 — 뭐든 삼키는 것',
  x:`통로 가운데 무엇이 입을 벌리고 앉아 있다. 몸 전체가 입이다.<br><br>
    동료가 돌을 던졌다. 삼켰다. 칼을 휘둘렀다. 칼끝을 삼켰다. 칼을 놓고서야 동료가 빠져나왔다.<br>
    던지면 삼킨다. 가리지 않는다.<br><br>
    이쪽 품에는 던질 것이 있다. 심지 길이만 맞으면.`,
  o:[
    { l:'① 심지를 짧게 잘라 꾸러미를 던져 넣는다.', k:'break', dc:15, wake:1,
      ok:`꾸러미 하나를 꺼내 심지를 세 숨 길이로 잘랐다. 불을 붙이고 한 숨 들고 있다가 던졌다.<br><br>삼켰다. 한 숨. 두 숨. 그것이 배를 부풀렸다. 퍽. 둔한 소리. 그것이 안에서부터 뒤집혔다. 통로 벽에 튄 것은 거의 없다. 다 그 안에서 끝났다.<br>평소 쓰는 양의 반의반이었다.<br><br>밖에서 터뜨리면 힘이 사방으로 샌다. 안에 넣으면 다 일한다. 꾸러미 크기를 정하는 셈법이 하나 바뀌었다. 이제 어디에 넣을지가 먼저다.`,
      ng:`심지를 너무 길게 잘랐다.<br><br>삼켰다. 한참 아무 일도 없다. 그것이 트림하듯 입을 벌렸다. 연기가 나왔다. 심지가 그 안에서 꺼졌다.<br>그것이 다음 것을 달라는 듯 이쪽으로 기어 왔다. 발목을 반쯤 삼켰다가 뱉었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 빈 꾸러미를 멀리 굴려 그쪽으로 꾀어낸다.', k:'fix', dc:14,
      ok:`빈 기름종이에 돌을 싸서 통로 옆 구멍으로 굴렸다.<br><br>그것이 소리를 따라 몸을 돌렸다. 구멍 쪽으로 기어간다. 구멍에 몸이 반쯤 끼었다.<br>그 뒤를 다들 지나갔다.<br><br>화약은 아꼈다. 종이는 싸게 먹혔다.`,
      ng:`굴린 꾸러미가 그것 입 앞에서 멈췄다.<br><br>삼켰다. 빈 걸 알았는지 화난 듯 크게 부풀었다. 이쪽으로 온다.<br>도망치다 정강이를 바닥 모서리에 찧었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 끓는 보일러',
  x:`레일 끝에 보일러가 있다. 무쇠 통에 관이 사방으로 났다. 레일이 이걸로 돈다.<br><br>
    압력 바늘이 빨간 칸에 박혔다. 이음매마다 김이 샌다. 통 겉이 숨 쉬듯 부풀었다 가라앉는다.<br>
    폭파공은 이런 게 화약보다 무섭다. 화약은 이쪽이 정할 때 터진다. 이것은 제가 정한다.<br><br>
    보일러가 멈추면 레일도 멈춘다. 갈고리도.`,
  o:[
    { l:'① 이음매에 꾸러미를 붙여 보일러를 터뜨린다.', k:'break', dc:16,
      doom:{ title:'터진 보일러', what:'터진 보일러의 김과 쇳조각에 휩싸였습니다', dc:16, sec:55,
        text:`아래 이음매에 꾸러미를 붙이고 심지를 길게 끌었다. 불을 붙이고 돌아섰다.<br><br>세 걸음 갔을 때 보일러가 먼저 터졌다. 심지가 닿기도 전에. 이쪽이 붙인 꾸러미 무게에 이음매가 먼저 졌다.<br>뜨거운 김이 등을 덮쳤다. 쇳조각이 사방으로 날았다. 바닥에 엎어졌다. 일어날 수가 없다.<br><br>김 속에서 레일이 멈추는 소리가 난다. 갈고리 하나가 천천히 이쪽으로 기운다.`,
        dieText:`보일러는 멈췄다. 레일도. 도축장이 처음으로 조용해졌다.<br><br>김이 걷히자 바닥에 엎어진 사람 모양이 하얗게 남았다. 김에 데어 하얗다.<br>그 옆에 타다 만 심지가 하나 떨어져 있다. 끝까지 안 탔다. 탈 필요가 없었다.` },
      ok:`아래 이음매에 꾸러미를 붙이고 심지를 길게 끌었다. 그리고 바로 뛰었다. 심지가 닿을 때까지 기다리지 않았다.<br><br>세 걸음 갔을 때 보일러가 먼저 터졌다. 이음매가 꾸러미 무게에 진 것이다. 예상했다. 그래서 뛰었다.<br>김이 등 뒤를 지나갔다. 레일이 멈췄다. 갈고리가 전부 축 늘어졌다.<br><br>남이 정하는 때를 이쪽이 먼저 알면 그것도 이쪽 때다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 김 새는 밸브를 하나씩 열어 압력을 뺀다.', k:'fix', dc:15,
      ok:`김이 제일 세게 새는 이음매부터 밸브를 찾았다. 녹슨 바퀴. 천을 감고 돌렸다.<br><br>쉬익. 김이 천장으로 뿜는다. 바늘이 빨간 칸에서 내려온다. 둘째 밸브. 셋째.<br>보일러가 숨을 고르듯 조용해졌다. 레일이 느려졌다. 갈고리가 느릿하게 지나간다. 그 사이로 다들 지났다.<br><br>터뜨리는 법을 아는 사람이 안 터뜨리는 법도 제일 잘 안다.`,
      ng:`둘째 밸브를 돌리는데 바퀴가 부러졌다.<br><br>김이 손으로 바로 뿜어졌다. 손등이 하얗게 익었다.<br>바늘은 그대로다. 보일러가 더 크게 숨을 쉰다. 다들 뒤로 물러났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
  ] },

{ at:'C2', t:'공방 — 칠 통이 늘어선 선반',
  x:`선반에 통이 줄지어 있다. 인형 얼굴에 바르는 칠, 유약, 아교, 묽힌 기름.<br><br>
    뚜껑이 다 반쯤 열렸다. 냄새가 코를 찌른다. 머리가 띵하다.<br>
    선반 맞은편에서 사기 인형 여섯이 일어섰다. 다리가 철사다. 이를 딱딱 부딪친다.<br><br>
    화약은 셋 남았다. 여섯을 하나씩 터뜨리기엔 모자란다.`,
  o:[
    { l:'① 꾸러미 하나를 인형들 가운데 굴린다.', k:'break', dc:15,
      ok:`꾸러미에 불을 붙여 인형들 발밑으로 굴렸다. 엎드렸다.<br><br>퍽. 사기 조각과 이가 사방으로 튀었다. 넷이 무너졌다. 둘이 남았다. 남은 둘은 동료들이 깼다.<br>머리 위로 날아간 이가 선반에 박혔다.<br><br>하나로 넷이면 잘 쓴 것이다. 화약이 둘 남았다.`,
      ng:`굴린 꾸러미를 인형 하나가 집었다.<br><br>집은 채로 들고 이쪽으로 걸어온다. 웃으면서. 다들 흩어졌다. 꾸러미가 그 손에서 터졌다.<br>파편이 등에 박혔다. 사기 조각과 이빨 하나.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 냄새로 어느 통이 터질지 가려 불씨를 던진다.', k:'sense', dc:15, wake:1,
      ok:`통 냄새를 하나씩 맡았다. 아교는 안 탄다. 유약은 늦게 탄다. 묽힌 기름은 한숨에 간다.<br><br>기름 통 둘을 골라 인형 쪽 바닥에 엎었다. 물러서며 불씨를 던졌다. 화약은 하나도 안 썼다.<br>바닥이 한 번 펑 하고 탔다. 인형들 철사 다리가 불 속에서 휘었다. 여섯 다 주저앉았다.<br><br>화약이 없으면 못 터뜨리는 줄 알았다. 이 방에는 처음부터 터질 것이 가득했다. 눈이 방 전체를 꾸러미로 보기 시작했다. 이제 남의 것도 쓴다.`,
      ng:`묽힌 기름이라고 고른 게 유약이었다.<br><br>불씨가 떨어져도 안 붙는다. 인형들이 유약을 밟고 다가왔다. 미끄러지지도 않는다.<br>뒤로 물러서다 다른 통을 엎었다. 그게 기름이었다. 이쪽 발밑에서 불이 일었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, mind:-8 } },
    { l:'③ 아교를 바닥에 쏟아 발을 묶는다.', k:'fix', dc:14,
      ok:`아교 통을 엎었다. 바닥에 끈적한 막이 넓게 퍼졌다.<br><br>인형들이 그 위를 밟았다. 철사 발이 붙었다. 하나, 둘. 넘어진 것들은 손까지 붙었다.<br>붙은 것들 옆을 돌아 지났다. 이를 딱딱 부딪치는 소리만 따라왔다.<br><br>터뜨리는 것만 일이 아니다. 붙여 두는 것도 일이다.`,
      ng:`아교가 생각보다 빨리 굳었다. 인형들이 오기 전에.<br><br>굳은 막 위로 인형들이 미끄러지듯 걸어왔다. 하나가 무릎을 물었다.<br>떼어 내다 이쪽 손이 덜 굳은 아교에 붙었다. 살갗을 남기고 뗐다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 갉아 먹힌 화약',
  x:`쉬는 틈에 화약 주머니를 열었다. 매일 하는 일이다.<br><br>
    가벼워졌다. 바닥에 구멍이 났다. 구멍 가장자리가 톱니 모양이다. 작은 이빨 자국.<br>
    무엇이 화약을 먹었다. 이 아래 것들은 화약도 먹는다.<br><br>
    주머니 안쪽 어딘가에서 아주 작게 씹는 소리가 난다.`,
  o:[
    { l:'① 주머니를 뒤집어 털고 남은 것을 다시 나눠 싼다.', k:'fix', dc:14,
      ok:`주머니를 천 위에 뒤집어 털었다. 화약과 함께 손톱만 한 것이 굴러 나왔다. 다리가 많다. 배가 검게 부풀었다.<br><br>돌로 눌렀다. 화약 먹은 것은 눌러도 안 터진다. 다행이다.<br>남은 화약을 기름종이에 새로 쌌다. 다섯 꾸러미. 꾸러미마다 실로 단단히 묶었다.<br><br>먹힌 만큼 아껴 쓰면 된다. 아끼는 것도 일이다.`,
      ng:`털자 작은 것이 셋 튀어나왔다. 둘을 눌렀다. 하나가 손등을 타고 소매 속으로 들어갔다.<br><br>팔 안쪽을 물렸다. 겨우 꺼내 눌렀다.<br>남은 화약은 털다가 반쯤 바닥에 흩어졌다. 흙과 섞였다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } },
    { l:'② 씹는 소리가 나는 자리를 찾아 그것만 꺼낸다.', k:'sense', dc:14,
      ok:`주머니를 귀에 대고 천천히 돌렸다. 소리가 오른쪽 아래 솔기에서 난다.<br><br>솔기를 손톱으로 눌러 열었다. 손톱만 한 것이 화약에 파묻혀 씹고 있다. 집어냈다. 화약은 거의 다 남았다.<br>집어낸 것을 오래 봤다. 배가 검다. 먹은 화약 색이다.<br><br>먹은 것의 배를 보면 얼마 먹었는지 안다. 별로 안 먹었다.`,
      ng:`소리를 따라가다 주머니를 너무 세게 쥐었다.<br><br>안에서 작은 것이 짓눌렸다. 검은 즙이 화약에 번졌다. 한 꾸러미 몫이 젖었다.<br>젖은 화약은 버렸다. 버리면서 냄새를 맡았다. 화약 냄새가 아니다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-8, spirit:-6 } }
  ] },

{ at:'C3', t:'성당 — 아치에 박힌 둥지',
  x:`아치 한가운데 무엇이 둥지를 틀었다. 회반죽과 머리카락과 뼈로 만든 것. 길을 막았다.<br><br>
    둥지 안에서 날개 소리가 난다. 여럿.<br>
    터뜨리면 둥지는 날아간다. 아치도 같이 금이 간다. 발밑은 거꾸로 매달린 천장이다. 그 아래는 어둠이다.<br><br>
    화약 다루는 사람은 터지는 힘이 어디로 갈지부터 본다. 여기는 갈 데가 아래뿐이다.`,
  o:[
    { l:'① 터뜨리지 않고 둥지를 손으로 뜯어낸다.', k:'steady', dc:15,
      ok:`둥지 가장자리부터 손으로 뜯었다. 뼈 하나, 머리카락 한 줌.<br><br>안에서 날개 달린 것이 튀어나와 얼굴을 할퀸다. 고개를 숙이고 계속 뜯었다. 동료들이 날아다니는 것을 쳐서 떨궜다.<br>길이 났다. 아치는 멀쩡하다.<br><br>얼굴에 긁힌 데가 많다. 아치에 금 하나 가는 것보다는 낫다.`,
      ng:`뜯다가 둥지 밑에서 뼈 하나가 빠졌다. 아치 회반죽이 같이 떨어졌다.<br><br>발밑 아치가 기울었다. 날개 달린 것들이 한꺼번에 쏟아져 나왔다.<br>얼굴과 손을 감싸고 다음 아치로 뛰었다. 한쪽 귀가 찢어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 한쪽만 터지게 꾸러미를 싸서 둥지만 날린다.', k:'break', dc:15, wake:1,
      ok:`꾸러미 하나를 풀었다. 아래쪽에 젖은 회반죽을 두껍게 바르고 돌판을 댔다. 위쪽은 종이 한 겹만.<br><br>둥지 위에 얹었다. 심지에 불을 붙이고 물러섰다. 펑. 소리가 위로 갔다. 둥지가 위로 날아 흩어졌다. 아래 아치는 먼지만 조금 털었다.<br>날개 달린 것들이 흩어진 둥지를 찾아 허공을 돈다.<br><br>터지는 건 사방으로 터지는 줄 알았다. 막으면 막힌 쪽으로는 안 간다. 꾸러미를 싸는 손이 이제 방향을 싼다.`,
      ng:`아래를 덜 막았다.<br><br>펑. 반은 위로, 반은 아래로 갔다. 둥지는 날아갔다. 발밑 아치에 금이 줄지어 갔다.<br>다들 엎드린 채 금이 멈추기를 기다렸다. 멈췄다. 아직은.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-12, mind:-10 } }
  ] },

{ at:'C4', t:'온실 — 문을 덮은 갓',
  x:`다음 방으로 가는 문이 갓으로 덮였다. 두껍다. 손바닥만 한 갓이 겹겹이 문틀을 메웠다.<br><br>
    방 공기가 노랗다. 가루가 떠 있다. 불티 하나면 방 전체가 한꺼번에 탄다.<br>
    품에 화약이 있다. 지금 이 방에서 제일 무서운 건 이쪽 품이다.<br><br>
    갓이 숨을 쉰다. 쉴 때마다 가루가 짙어진다.`,
  o:[
    { l:'① 화약을 다 내려놓고 맨손으로 뜯는다.', k:'steady', dc:15,
      ok:`화약 주머니와 부싯돌을 방 밖에 두고 왔다. 쇠붙이도.<br><br>맨손으로 갓을 뜯었다. 뜯을 때마다 가루가 얼굴로 온다. 젖은 천으로 입을 막았다. 한 겹씩.<br>문고리가 드러났다. 돌렸다. 열렸다. 다들 뛰어 지났다.<br><br>방 밖에 둔 화약을 찾으러 돌아갔다. 그대로 있다. 그게 제일 반가웠다.`,
      ng:`뜯는데 갓 속에서 무엇이 손을 물었다.<br><br>가루를 한 모금 마셨다. 기침이 멎지 않는다. 손이 부어오른다.<br>문은 반만 열렸다. 다들 어깨를 비틀어 겨우 지났다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 젖은 흙으로 꾸러미를 싸 불 없이 힘만 터뜨린다.', k:'fix', dc:16, wake:1,
      ok:`꾸러미를 젖은 흙으로 두껍게 감쌌다. 주먹 두 개만 한 흙덩이. 심지도 흙에 묻어 문밖까지 끌었다. 불은 문밖에서 붙였다.<br><br>흙덩이는 문틀 갓 속에 박아 두었다. 다들 문밖으로. 기다렸다.<br>둔하게 쿵. 흙덩이가 안에서 부풀었다 갈라졌다. 불은 한 점도 안 나왔다. 힘만 나왔다. 갓이 문틀째 떨어져 나갔다. 가루는 젖은 흙에 다 먹혔다.<br><br>불과 힘은 같이 오는 줄 알았다. 떼어 놓을 수 있다. 손이 그걸 알았다. 이제 터지는 것에서 불을 빼고 쓸 수 있다.`,
      ng:`흙이 한쪽만 얇았다.<br><br>쿵. 얇은 쪽으로 불이 혀를 내밀었다. 손가락 하나만큼. 그걸로 충분했다. 방 공기가 노랗게 일었다가 꺼졌다.<br>문 앞에 있던 이쪽 눈썹과 앞머리가 없어졌다. 다른 데는 다 있다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C', t:'불침번 — 줄 덫',
  x:`다들 잔다. 불침번이다.<br><br>
    통로 저편에서 무엇이 다가오는 소리가 난다. 멈췄다가 다시. 냄새를 맡는다.<br>
    화약 다루는 사람은 자는 동안에도 지킬 줄 안다. 줄 하나, 작은 꾸러미 하나. 건드리면 터진다. 크게는 아니다. 깨울 만큼.<br><br>
    줄을 맬 데가 마땅치 않다. 벽이 물렁하다.`,
  o:[
    { l:'① 통로 입구에 줄을 매고 작은 꾸러미를 단다.', k:'fix', dc:14,
      ok:`벽에 박힌 뼈 하나에 줄을 묶었다. 맞은편 돌에 다른 끝을. 발목 높이. 줄 끝에 손톱만 한 꾸러미.<br><br>누웠다. 한참 뒤 퍽. 다들 튀어 일어났다. 통로 입구에서 무엇이 다리를 쥐고 뒹군다. 다리 하나가 없다.<br>다들 무기를 들고 끝냈다. 다시 누웠다. 다시 줄을 맸다.<br><br>덫 하나가 사람 하나만큼 지킨다. 더 싸다.`,
      ng:`뼈에 맨 줄이 풀렸다. 뼈가 움직였다. 벽 속에서.<br><br>줄이 축 늘어진 걸 모르고 누웠다. 그것이 들어왔다. 발목을 물려서야 알았다.<br>다들 깼다. 떼어 냈다. 줄은 그 뼈가 가져갔다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-6 } },
    { l:'② 덫 없이 깨어 앉아 귀로 지킨다.', k:'steady', dc:14,
      ok:`화약은 아꼈다. 등을 벽에 대고 앉았다. 눈을 감고 귀만 열었다.<br><br>소리가 다가왔다가 멈추고, 다가왔다가 멈춘다. 다섯 걸음 앞까지 왔을 때 돌을 던졌다. 소리가 물러났다.<br>밤새 그렇게 세 번. 아침에 다들 개운하다고 했다. 이쪽 눈이 빨갛다.<br><br>심지 타는 소리를 듣던 귀다. 이 정도는 듣는다.`,
      ng:`새벽에 졸았다.<br><br>목덜미에 차가운 숨이 닿아 깼다. 바로 옆이다. 소리를 질렀다.<br>그것이 물러났다. 목덜미가 긁혔다. 다들 그 뒤로 못 잤다.`,
      win:{ exp:14, dream:1, hp:6 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C1', t:'도축장 — 뼈로 막힌 통로',
  x:`통로가 뼈와 살로 막혔다. 쌓인 게 아니다. 자랐다. 갈비가 갈비에 붙고 그 사이를 살이 메웠다.<br><br>
    한가운데를 크게 터뜨리면 뚫린다. 뚫린 자리도 자랄 것이다. 조각은 사방에 붙어 다시 자랄 것이다.<br>
    벽이 숨을 쉰다. 벽 너머에서 레일 소리가 들린다.<br><br>
    화약은 다섯 꾸러미 남았다.`,
  o:[
    { l:'① 작은 꾸러미 셋을 차례로 터지게 이어 붙인다.', k:'break', dc:15, wake:1,
      ok:`꾸러미 셋을 벽에 한 줄로 박았다. 심지를 하나에서 다음으로 이었다. 길이를 한 숨씩 다르게.<br><br>첫째가 터져 겉을 열었다. 한 숨 뒤 둘째가 열린 자리 안쪽에서 터졌다. 셋째가 그 안쪽에서. 벽이 자랄 틈 없이 세 번 열렸다.<br>사람 하나 지날 굴이 났다. 다들 굴이 닫히기 전에 지났다. 마지막 사람 뒤에서 굴이 천천히 닫혔다.<br><br>한 번에 크게보다 세 번에 작게. 앞엣것이 다음 것의 길을 낸다. 심지를 잇는 손이 이제 순서를 잇는다.`,
      ng:`둘째 심지가 짧았다. 첫째와 둘째가 거의 같이 터졌다.<br><br>겉만 크게 날아갔다. 조각이 다들 몸에 붙었다. 셋째는 닫히는 살 속에 묻혀 안 터졌다.<br>몸에 붙은 조각을 떼어 내는 데 한참. 하나는 떼어 낸 자리에 빨간 점을 남겼다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 한가운데를 크게 터뜨린다.', k:'break', dc:15,
      ok:`꾸러미 둘을 하나로 묶어 한가운데 깊이 박았다. 심지를 길게.<br><br>쾅. 벽 한가운데가 뚫렸다. 조각이 통로 사방에 붙었다. 붙은 조각들이 바로 꿈틀대기 시작했다.<br>뛰어서 지났다. 다들 조각을 밟으며. 지나고 돌아보니 통로가 아까보다 좁아졌다.<br><br>크게 하면 크게 남는다. 그래도 지났다.`,
      ng:`터지자 조각이 다들에게 붙었다. 이쪽 얼굴에도.<br><br>얼굴에 붙은 조각이 살갗을 찾아 뿌리를 뻗는다. 따끔하다. 손톱으로 떼어 냈다.<br>뚫린 자리는 다 지나기 전에 닫혔다. 둘은 돌아서 와야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'③ 벽 너머 레일 소리를 따라 다른 길을 찾는다.', k:'sense', dc:14,
      ok:`벽에 귀를 댔다. 레일 소리가 오른쪽으로 멀어진다. 오른쪽 어딘가에 레일이 지나는 구멍이 있다.<br><br>오른쪽 벽을 따라갔다. 천장 가까이 레일이 벽을 뚫고 지난다. 그 구멍으로 기어올랐다.<br>화약은 하나도 안 썼다. 구멍 옆 선반에 소금 포대가 있었다.<br><br>터뜨릴 수 있는 것 앞에서 안 터뜨린 날이다.`,
      ng:`레일 구멍으로 기어오르는데 레일이 돌았다.<br><br>갈고리가 머리 위로 지나갔다. 숙였다. 다음 갈고리가 등짐 끈에 걸렸다.<br>끈을 잘라 냈다. 등짐 하나가 레일에 실려 갔다.`,
      win:{ exp:15, dream:1, item:'소금 덩이' }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 진열장의 눈',
  x:`벽 한 면이 진열장이다. 사기 인형이 백 개쯤 앉아 있다. 다 눈을 감았다.<br><br>
    동료 하나가 기침을 했다. 맨 끝 인형 하나가 눈을 떴다. 소리 난 쪽을 본다.<br>
    소리가 나면 눈을 뜬다. 다 뜨면 다 내려올 것이다.<br><br>
    화약 일은 원래 시끄럽다.`,
  o:[
    { l:'① 숨까지 줄이고 소리 없이 지난다.', k:'hide', dc:15,
      ok:`장화를 벗어 들었다. 다들에게도 벗게 했다. 맨발로 진열장 앞을 지났다.<br><br>품 안 화약 주머니가 사각거린다. 손으로 눌렀다. 한 걸음, 한 숨.<br>다 지났다. 맨 끝 인형만 눈을 뜨고 있다. 아까부터 뜬 그 하나.<br><br>진열장을 나오고서야 숨을 쉬었다. 화약 주머니를 꽉 쥔 손에 땀이 찼다.`,
      ng:`누군가 사기 조각을 밟았다. 딱.<br><br>인형 열 개가 한꺼번에 눈을 떴다. 고개가 이쪽으로. 진열장에서 하나가 뛰어내렸다.<br>뛰었다. 발목을 물렸다. 진열장이 웅성대듯 덜그럭거렸다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 진열장 다리를 터뜨려 통째로 엎는다.', k:'break', dc:15,
      ok:`진열장 다리 밑에 꾸러미 둘을 넣었다. 심지를 길게 끌어 문 쪽까지.<br><br>다들 문밖으로 내보내고 불을 붙였다. 쾅. 진열장이 앞으로 엎어졌다. 백 개가 한꺼번에 바닥에 떨어져 깨졌다. 깨지는 소리가 한참 이어졌다.<br>먼지가 가라앉자 깨진 조각 사이로 이들이 반짝인다. 하나도 안 움직인다.<br><br>시끄러운 게 일이면 크게 시끄럽게 한다. 한 번에.`,
      ng:`터지는 소리에 백 개가 한꺼번에 눈을 떴다. 엎어지기 직전에.<br><br>절반이 엎어지는 진열장에서 뛰어내렸다. 안 깨진 채로.<br>문을 닫고 등으로 막았다. 문 너머에서 작은 이들이 문짝을 긁었다. 오래.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C3', t:'성당 — 종 속의 것',
  x:`발밑에 거꾸로 선 종이 입을 벌리고 있다. 안이 어둡다.<br><br>
    종 안에 무엇이 매달려 있다. 추가 있어야 할 자리에. 길다. 팔이 여럿 접혀 있다.<br>
    종 너머로 가야 한다. 지날 때마다 종이 낮게 운다. 그때마다 접힌 팔이 하나씩 펴진다.<br><br>
    종 안은 좋은 그릇이다. 소리도, 힘도 안에 모인다.`,
  o:[
    { l:'① 종 안에 꾸러미를 넣고 터뜨린다.', k:'break', dc:15,
      doom:{ title:'종 속', what:'종 안의 것에게 붙잡혀 종 속으로 끌려 들어갑니다', dc:15, sec:55,
        text:`종 테두리에 엎드려 꾸러미를 안으로 내렸다. 심지에 불을 붙였다.<br><br>손을 빼려는데 손목을 무엇이 잡았다. 접혀 있던 팔 하나. 둘. 셋. 종 안으로 당긴다.<br>어깨가 테두리에 걸렸다. 심지 타는 소리가 종 안에서 크게 울린다. 이쪽 귀 바로 옆에서.<br><br>종 안은 좋은 그릇이다. 그건 이쪽이 한 말이다.`,
        dieText:`종이 한 번 울었다. 성당 전체가 울었다.<br><br>그 뒤로 그 종은 안 운다. 안에서 무엇이 울림을 다 먹었다.<br>종 테두리에 장화 한 짝이 걸려 있다. 밑창이 사기 조각에 긁혀 있다.` },
      ok:`종 테두리에 엎드려 꾸러미를 안으로 내렸다. 심지에 불을 붙이자마자 손을 빼 굴렀다.<br><br>접힌 팔 하나가 빈손을 쥐었다. 늦었다. 쾅. 종이 성당 전체를 울렸다. 귀가 먹었다. 종 안에서 팔들이 한꺼번에 축 늘어졌다.<br>한참 아무 소리도 안 들렸다. 손짓으로 다들 건너게 했다.<br><br>귀가 돌아오는 데 반나절이 걸렸다. 종은 그 뒤로 안 울었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 종 입구를 판자로 덮고 위로 지난다.', k:'steady', dc:14,
      ok:`부서진 의자 판자를 모아 종 입구를 덮었다. 그 위를 밟고 지나가게 했다.<br><br>밟을 때마다 종이 운다. 덮었으니 소리가 판자에 먹힌다. 안에서 팔이 판자를 밀어 올린다. 무거운 사람부터 판자 위에 올라섰다.<br>다 지났다. 판자가 들썩였다.<br><br>안 터뜨리고 덮어 뒀다. 다음에 오는 사람은 판자를 조심해야 할 것이다.`,
      ng:`판자 하나가 썩었다. 밟자 부러졌다.<br><br>발이 종 안으로 빠졌다. 접힌 팔 하나가 발목을 감았다. 동료들이 겨드랑이를 잡아 뽑아냈다.<br>장화가 종 안에 남았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C4', t:'온실 — 바닥 밑의 뿌리',
  x:`온실 바닥 타일이 군데군데 들렸다. 밑에서 하얀 뿌리가 밀어 올렸다.<br><br>
    뿌리는 굵기가 팔뚝만 하다. 서로 엮였다. 밟으면 저쪽 화단에서 무엇이 고개를 든다. 한 덩어리로 이어진 것이다.<br>
    끊으려면 많이 끊어야 한다. 화약은 넷.<br><br>
    무엇이든 힘을 받는 데가 있다. 뿌리도 받친다.`,
  o:[
    { l:'① 뿌리가 모이는 매듭을 찾아 거기 하나만 터뜨린다.', k:'gaze', dc:15, wake:1,
      ok:`들린 타일을 몇 장 더 들추고 뿌리가 뻗는 방향을 셌다. 다 한쪽으로 모인다. 화단 모퉁이 밑.<br><br>거기 타일을 들자 뿌리가 주먹처럼 뭉친 매듭이 있다. 꾸러미 하나를 매듭 한가운데 박았다. 터졌다.<br>온실 전체에서 뿌리가 한꺼번에 힘을 잃었다. 화단에서 고개 들던 것들이 고개를 떨궜다.<br><br>여럿을 끊을 일은 하나를 끊으면 된다. 그 하나를 찾는 눈이 섰다. 이제 무엇을 봐도 힘이 모이는 매듭부터 보인다.`,
      ng:`매듭이라고 터뜨린 게 갈라지는 가지 하나였다.<br><br>그 가지만 끊겼다. 나머지가 놀란 듯 꿈틀대며 타일을 한꺼번에 밀어 올렸다.<br>발밑이 들썩였다. 넘어지면서 뿌리 하나에 발목이 감겼다. 동료가 끊어 줬다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 뿌리를 안 밟고 타일만 골라 딛는다.', k:'evade', dc:14,
      ok:`안 들린 타일만 골라 딛게 했다. 이쪽이 먼저 가서 디딘 자리에 숯을 묻혔다.<br><br>다들 숯 자국만 밟고 건넜다. 뿌리는 한 번도 안 건드렸다. 화단의 것들은 고개를 안 들었다.<br>건너편 화단 가장자리, 뿌리 없는 쪽에 산나물 같은 잎이 났다. 뜯었다.<br><br>화약은 넷 그대로다.`,
      ng:`숯 자국을 밟는데 그 타일이 들렸다. 밑에서 뿌리가 막 올라오던 참이다.<br><br>화단의 것들이 고개를 들었다. 다들 뛰었다. 뒤에서 무엇이 화단을 기어 나오는 소리.<br>건너편 문을 닫고 한참 등을 댔다.`,
      win:{ exp:15, dream:1, item:'산나물' }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 손가락 세기',
  x:`터뜨린 날 밤에는 손가락을 센다. 폭파공 버릇이다. 열 개.<br><br>
    오늘도 열이다. 옆 동료는 아니다. 아까 인형에게 물린 손이 붉게 부었다. 새끼손가락 끝이 없다.<br>
    동료는 아무 말도 안 한다. 피는 멎었다. 손이 떨린다.<br><br>
    손가락을 잃어 본 사람은 안다. 그다음 밤이 제일 길다.`,
  o:[
    { l:'① 동료 손을 씻고 단단히 동여 준다.', k:'heal', dc:14,
      ok:`물을 데워 상처를 씻었다. 동료가 이를 악문다.<br><br>깨끗한 천으로 새끼손가락을 감고 넷째와 같이 묶었다. 같이 묶으면 덜 아프다. 화약 다루는 사람들이 그렇게 한다.<br>동료 손을 이쪽 손으로 덮고 한참 있었다. 떨림이 잦아들었다.<br><br>동료가 손가락을 세어 봤다. 아홉 반. 웃었다. 이쪽도 웃었다.`,
      ng:`씻는데 물이 너무 뜨거웠다.<br><br>동료가 손을 빼다 묶은 천이 풀렸다. 상처가 다시 터졌다.<br>밤새 둘이서 손을 쥐고 있었다. 동료 손이 아침까지 떨렸다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-8, spirit:-8 } },
    { l:'② 남은 화약을 세어 내일을 정한다.', k:'fix', dc:14,
      ok:`꾸러미를 펼쳐 놓았다. 넷. 크기를 다시 쟀다. 하나는 크고 셋은 작다.<br><br>큰 것은 마지막 방에 쓴다. 작은 셋은 그 전에. 셋이면 문 셋, 아니면 짐승 셋.<br>꾸러미마다 숯으로 표시했다. 쓸 자리를 미리 정해 두면 손이 덜 망설인다.<br><br>동료는 그사이 잠들었다. 손을 가슴에 안고.`,
      ng:`세다가 꾸러미 하나가 축축한 걸 알았다. 동료 피가 묻었다.<br><br>말려 봤다. 말린 화약은 덩어리가 졌다. 셋 남았다.<br>내일이 하나 줄었다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-10, spirit:-4 } }
  ] },

{ at:'C1', t:'도축장 — 고기를 거는 것',
  x:`레일 옆에 앞치마 두른 것이 서서 갈고리에 고기를 건다. 쉬지 않는다.<br><br>
    고기가 다 떨어지면 다른 것을 건다. 지금 이쪽을 본다. 걸 것을 보는 눈이다.<br>
    앞치마 앞주머니가 불룩하다. 쇠붙이 소리가 난다. 갈고리 여분이다.<br><br>
    바닥 배수구에서 썩은 냄새가 올라온다. 고인 냄새. 불붙는 냄새.`,
  o:[
    { l:'① 다가가 앞치마 주머니에 꾸러미를 떨군다.', k:'hide', dc:16,
      ok:`그것이 갈고리를 거는 사이 등 뒤로 붙었다. 심지에 불을 붙인 꾸러미를 앞주머니에 떨궜다.<br><br>그것은 모른다. 계속 건다. 세 걸음 물러섰다. 다섯. 퍽. 주머니가 터지며 갈고리 여분이 그것 몸 안쪽으로 박혔다.<br>그것이 갈고리 하나를 든 채 무릎을 꿇었다. 레일이 멈췄다.<br><br>제 주머니에 든 것에 다친다. 다들 그렇다.`,
      ng:`등 뒤로 붙는데 그것이 돌아섰다. 걸 것을 찾는 눈이 이쪽을 찾았다.<br><br>앞치마 손이 이쪽 어깨를 잡았다. 갈고리 쪽으로 들어 올린다. 동료들이 매달려 끌어내렸다.<br>어깨에 갈고리 끝이 스쳤다. 깊다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, spirit:-6 } },
    { l:'② 배수구에 불씨를 떨궈 고인 것을 터뜨린다.', k:'break', dc:15,
      ok:`배수구 쇠창살 틈으로 불씨를 떨궜다. 다들 엎드리게 했다.<br><br>펑. 바닥 밑에서 파란 불이 창살을 뚫고 솟았다. 그것이 서 있던 바로 아래였다. 앞치마가 붙었다. 그것이 불을 끄려 앞치마를 친다.<br>레일 쪽이 비었다. 그 틈에 다들 지났다.<br><br>화약을 안 썼다. 바닥이 오래 모아 둔 걸 썼다.`,
      ng:`불씨가 창살에 걸려 꺼졌다.<br><br>둘째 불씨를 던지려는데 그것이 이쪽으로 걸어왔다. 갈고리를 들고.<br>뛰었다. 그때 배수구가 늦게 터졌다. 이쪽 발밑에서. 장화가 그을렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'③ 꾸러미를 반대쪽 고기 더미로 굴려 눈을 돌린다.', k:'evade', dc:14,
      ok:`작은 꾸러미 하나에 불을 붙여 반대쪽 고기 더미로 굴렸다.<br><br>퍽. 고기 더미가 흩어졌다. 그것이 고개를 돌렸다. 흩어진 고기를 주우러 간다. 걸 것이 거기 많다.<br>그사이 다들 레일 밑으로 지났다.<br><br>걸 것을 찾는 눈은 걸 것이 많은 쪽으로 간다.`,
      ng:`굴린 꾸러미가 덜 굴렀다. 그것 발 앞에서 터졌다.<br><br>그것은 흔들리지도 않았다. 대신 터진 쪽, 이쪽을 봤다.<br>쫓겨서 뛰었다. 등 뒤에서 갈고리가 허공을 갈랐다. 한 번은 등을.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 위층 계단의 실',
  x:`위층으로 가는 계단이다. 칸마다 실이 걸렸다. 발목 높이, 무릎 높이, 목 높이.<br><br>
    실 끝이 위층으로 이어진다. 건드리면 위에서 안다. 위에서 무엇이 실을 쥐고 기다린다.<br>
    줄 덫은 안다. 제 손으로 매 본 것이니까. 매는 사람의 버릇이 실에 남는다.<br><br>
    여기 실은 매듭이 다 같다. 한 손으로 맸다.`,
  o:[
    { l:'① 매듭 버릇을 읽어 안 걸리는 길을 찾는다.', k:'gaze', dc:15,
      ok:`매듭을 하나씩 봤다. 다 왼쪽으로 감겼다. 오른손잡이가 왼쪽 벽에서 맸다. 그러면 오른쪽 끝이 늘 느슨하다.<br><br>오른쪽 끝으로만 넘어가게 했다. 느슨한 실은 건드려도 위에서 모른다.<br>다들 계단을 올랐다. 위층 문 앞까지. 위에서 기다리는 것이 아직 기다린다.<br><br>매는 사람은 버릇을 남긴다. 이쪽도 그렇다. 조심해야겠다.`,
      ng:`오른쪽이 느슨하다고 본 게 틀렸다. 왼손잡이였다.<br><br>실이 팽팽하게 당겨졌다. 계단 전체가 흔들렸다. 위에서 무엇이 웃었다.<br>계단 위에서 사기 인형 셋이 굴러 내려왔다. 막다가 같이 굴렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 실을 다 모아 묶고 끝에 꾸러미를 단다.', k:'break', dc:15,
      ok:`실을 하나씩 걷어 모았다. 당기지 않게. 열두 가닥을 한 손에 모아 매듭 하나로 묶었다. 그 매듭에 불붙인 꾸러미를 달았다.<br><br>그리고 한꺼번에 당겼다. 위에서 실을 쥔 것이 열두 가닥이 한꺼번에 당겨지는 걸 느꼈다. 당겨 올렸다. 꾸러미째.<br>위층에서 퍽. 계단 위로 먼지와 사기 가루가 쏟아졌다. 조용해졌다.<br><br>실은 양쪽으로 다 간다. 남이 맨 덫은 이쪽 덫도 된다.`,
      ng:`모으다 한 가닥이 팽팽해졌다.<br><br>위에서 알았다. 실이 전부 한꺼번에 당겨졌다. 손에 쥔 실이 손바닥을 베며 빠져나갔다.<br>꾸러미가 계단에 굴러떨어져 이쪽 발밑에서 터졌다. 작은 것이었다. 다행히.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 먹먹한 귀',
  x:`오늘 너무 많이 터뜨렸다. 귀가 먹먹하다. 삐 소리가 계속 난다.<br><br>
    다들 무슨 말을 한다. 입만 보인다. 이쪽은 대충 고개를 끄덕인다.<br>
    이 아래에서 귀가 먼 사람은 제일 먼저 잡힌다. 뒤에서 오는 것을 못 듣는다.<br><br>
    폭파공들은 이걸 다 안다. 그래도 터뜨린다.`,
  o:[
    { l:'① 동료에게 뒤를 들어 달라고 손짓한다.', k:'bond', dc:13,
      ok:`옆 사람 어깨를 두드리고 이쪽 귀를 가리켰다. 뒤를 가리켰다.<br><br>동료가 고개를 끄덕였다. 그다음부터 그 사람이 이쪽 뒤에 섰다. 무엇이 오면 어깨를 쳐 줬다. 두 번 쳤다. 두 번 다 진짜였다.<br>밤에 귀가 조금 돌아왔다. 동료 목소리가 처음 들렸다. 생각보다 낮다.<br><br>남의 귀를 빌렸다. 갚을 것이 생겼다.`,
      ng:`손짓을 동료가 잘못 알아들었다. 고개를 끄덕이더니 앞으로 가 버렸다.<br><br>뒤에서 무엇이 왔다. 못 들었다. 종아리를 물리고서야 알았다.<br>소리를 질렀는데 이쪽 목소리도 안 들렸다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 바닥에 손바닥을 대고 울림으로 듣는다.', k:'sense', dc:14,
      ok:`쉬는 동안 바닥에 손바닥을 붙였다. 귀 대신 손으로.<br><br>발걸음은 바닥을 울린다. 다들 것은 안다. 무겁고 고르다. 그 사이로 다른 울림이 섞였다. 가볍고 빠르다. 왼쪽 벽 너머.<br>왼쪽을 가리켰다. 다들 무기를 들었다. 벽 틈에서 무엇이 나오다 말고 들어갔다.<br><br>화약이 터지면 바닥이 운다. 그 울림을 손이 수천 번 들었다.`,
      ng:`바닥이 온통 울린다. 이쪽 손이 떨리는 건지 바닥이 떨리는 건지 모르겠다.<br><br>잘못 가리켰다. 다들 오른쪽을 봤다. 왼쪽에서 왔다.<br>동료 하나가 다쳤다. 이쪽 탓이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'성당 — 매달린 색유리',
  x:`거꾸로 매달린 창에 색유리가 박혔다. 발밑 아치 바로 옆까지 내려왔다.<br><br>
    유리 그림 속 사람들이 이쪽을 본다. 그림인데 눈이 움직인다. 유리 너머에서 무엇이 그림 눈 뒤에 얼굴을 댔다.<br>
    창 하나가 사람만 하다. 다 깨지면 유리 비가 된다.<br><br>
    창 너머로 손이 하나 짚였다. 유리가 휜다.`,
  o:[
    { l:'① 창을 터뜨려 파편으로 안의 것을 친다.', k:'break', dc:15,
      ok:`창 이쪽 면 모서리에 꾸러미를 붙였다. 유리가 저쪽으로 터지게. 다들 아치 뒤로 숨게 했다.<br><br>쾅. 색유리가 저쪽으로 쏟아졌다. 창 너머의 것이 그 비를 정면으로 맞았다. 비명이 났다. 한참.<br>창틀만 남았다. 창틀 너머가 조용하다.<br><br>유리 조각 하나가 이쪽 소매에 박혔다. 파란 조각이다. 그림 속 누구 눈이었던 것 같다.`,
      ng:`꾸러미 무게에 유리가 이쪽으로 먼저 휘었다.<br><br>터지자 유리가 반은 이쪽으로 왔다. 아치 뒤로 숨기 전에.<br>팔과 등에 색유리가 박혔다. 빨강, 파랑, 초록. 하나씩 뽑았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-6 } },
    { l:'② 유리는 두고 창을 매단 납 테두리만 끊어 창째 떨군다.', k:'fix', dc:15,
      ok:`창은 납 테두리로 아치에 매달렸다. 화약을 한 꼬집씩 테두리 이음매 넷에 얹었다.<br><br>불을 붙였다. 펑, 펑, 펑, 펑. 작게. 납이 녹아 끊어졌다. 창이 통째로 미끄러져 아치 구멍 아래 어둠으로 떨어졌다. 깨지는 소리가 한참 뒤에 아주 작게.<br>창 너머의 것도 같이 떨어졌다. 짚고 있던 손째로.<br><br>유리 비는 없었다. 창 하나가 통째로 내려갔다.`,
      ng:`이음매 넷 중 셋만 끊어졌다.<br><br>창이 한쪽으로 기울어 매달렸다. 창 너머의 것이 기운 틈으로 팔을 내밀었다. 이쪽 발목을 잡았다.<br>동료들이 그 팔을 쳤다. 발목에 손가락 자국이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-10 } }
  ] },

{ at:'C4', t:'온실 — 보일러실',
  x:`온실을 데우는 보일러실이다. 보일러에 하얀 뿌리가 감겼다. 빈틈없이.<br><br>
    뿌리는 온실 한가운데로 이어진다. 거기 가장 큰 것이 자란다. 보일러 열을 먹고.<br>
    보일러를 터뜨리면 열이 끊긴다. 한가운데 것도 식는다.<br><br>
    뿌리가 보일러 압력 바늘까지 덮었다. 지금 몇인지 안 보인다.`,
  o:[
    { l:'① 뿌리 밑 보일러 몸통에 꾸러미를 붙인다.', k:'break', dc:16,
      doom:{ title:'뿌리 감긴 보일러', what:'뿌리에 감겨 터지는 보일러 쪽으로 끌려갑니다', dc:16, sec:55,
        text:`뿌리를 비집고 손을 넣어 보일러 몸통에 꾸러미를 붙였다. 심지에 불을 붙였다.<br><br>손을 빼려는데 뿌리가 조였다. 손목째. 뿌리가 보일러 쪽으로 당긴다. 따뜻한 쪽으로. 먹으려는 것이다.<br>심지가 탄다. 한 숨. 두 숨. 어깨까지 감겼다. 몇 숨짜리 심지였는지 이쪽은 안다.<br><br>안다는 게 이렇게 쓸모없는 때도 있다.`,
        dieText:`보일러실에서 쾅 소리가 났다. 온실 유리가 한꺼번에 떨었다.<br><br>그날부터 온실이 식었다. 한가운데 큰 것도 시들었다.<br>보일러실 바닥에 뿌리가 까맣게 탔다. 그 가운데 손가락 열 개 자리만 하얗다.` },
      ok:`뿌리를 비집고 손을 넣어 보일러 몸통에 꾸러미를 붙였다. 불을 붙이고 손을 빼는 순간 뿌리가 조였다. 반 박자 늦게.<br><br>빈손 자리를 조였다. 뿌리가 당황한 듯 꿈틀했다. 뛰었다. 다들 보일러실 문밖에 엎드려 있다.<br>쾅. 문이 날아갔다. 온실 유리가 한꺼번에 떨었다. 한가운데 쪽에서 무엇이 길게 울었다. 식어 가는 소리다.<br><br>문틀에 엎드린 채 손가락을 셌다. 열.`,
      win:{ exp:25, dream:3 } },
    { l:'② 밸브를 찾아 불을 잠가 보일러를 꺼 버린다.', k:'fix', dc:15,
      ok:`뿌리 사이로 손을 넣어 밸브 바퀴를 더듬었다. 찾았다. 천천히 잠갔다.<br><br>불이 줄어든다. 보일러가 식는다. 감긴 뿌리가 하나씩 힘을 잃고 미끄러진다. 따뜻한 데가 없으면 붙어 있을 이유가 없다.<br>한가운데 쪽에서 무엇이 웅크리는 소리가 났다.<br><br>안 터뜨렸다. 식혔다. 식는 건 느리다. 그래도 확실하다.`,
      ng:`밸브를 돌리는데 뿌리가 손을 감았다.<br><br>빼냈다. 손등 살갗이 뿌리에 남았다. 밸브는 반만 잠겼다.<br>보일러가 그르렁댄다. 뿌리가 더 굵어지는 것 같다. 다들 서둘러 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C', t:'통로 — 자라서 막힌 길',
  x:`아까 지나온 길이 막혔다. 돌이 무너진 게 아니다. 벽이 자라서 붙었다.<br><br>
    살 같은 것이 양쪽 벽에서 나와 가운데서 만났다. 아직 무르다. 두께가 한 팔쯤.<br>
    뒤로 가야 한다. 앞쪽은 더 나쁘다.<br><br>
    무른 것을 터뜨리면 덜 일한다. 힘이 먹힌다.`,
  o:[
    { l:'① 꾸러미를 깊이 박아 넣고 터뜨린다.', k:'break', dc:15,
      ok:`무른 벽에 팔을 넣어 꾸러미를 한가운데까지 밀어 넣었다. 팔꿈치까지 들어갔다. 차고 축축하다.<br><br>빼고 심지에 불을 붙였다. 물러섰다. 둔하게 퍽. 벽이 안에서 부풀었다 찢어졌다. 찢어진 사이로 바람이 들어온다.<br>다들 그 틈을 비집고 지났다. 찢어진 가장자리가 옷을 잡았다 놓는다.<br><br>무른 것은 안에서 터뜨린다. 겉에서는 다 먹힌다.`,
      ng:`밀어 넣은 팔을 빼려는데 벽이 팔을 물었다. 감싼 것이다.<br><br>심지에 불을 붙이기도 전에 팔이 안 빠진다. 동료들이 당겼다. 빠졌다. 꾸러미는 벽 속에 남았다.<br>못 터뜨렸다. 다른 길로 돌았다. 팔에서 한참 비린내가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 아직 무른 가운데를 손으로 갈라 연다.', k:'steady', dc:14,
      ok:`벽이 만난 가운데 이음매를 찾았다. 아직 덜 붙었다. 손가락을 넣어 양쪽으로 벌렸다.<br><br>찢어지지 않고 벌어진다. 동료 둘이 같이 벌렸다. 사람 하나 지날 틈. 하나씩 지났다.<br>마지막 사람이 지나고 손을 놓자 틈이 다시 붙었다. 조금 더 단단하게.<br><br>화약은 아꼈다. 손에서 비린내가 났다.`,
      ng:`벌리는데 이음매 안쪽에서 무엇이 손가락을 빨았다.<br><br>손을 뺐다. 손가락 끝이 하얗게 불었다. 감각이 없다.<br>틈은 안 열렸다. 결국 꾸러미 하나를 썼다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'통로 — 숨이 흐트러진 날',
  x:`쫓기는 중이다. 뒤에서 무엇이 온다. 숨이 차다.<br><br>
    앞에 좁은 목이 있다. 거기에 꾸러미를 두고 지나가면 뒤에 오는 것이 걸린다. 심지 길이만 맞으면.<br>
    심지는 숨으로 잰다. 한 뼘에 몇 숨. 지금 숨은 엉망이다. 셀 수가 없다.<br><br>
    뒤에서 오는 소리가 가깝다.`,
  o:[
    { l:'① 숨 대신 맥박으로 심지를 잰다.', k:'break', dc:15, wake:1,
      ok:`숨을 버렸다. 손목을 엄지로 눌렀다. 맥이 뛴다. 빠르다. 그래도 고르다.<br><br>맥 하나에 심지 손톱 하나. 지금 맥이면 서른 맥에 목을 지나고 열 맥 더 간다. 심지를 마흔 맥 길이로 잘라 불을 붙여 목에 두었다. 뛰었다. 세었다.<br>마흔에 터졌다. 뒤에서 오던 것이 목에 막 들어선 참이었다. 무너진 소리 뒤로 아무것도 안 왔다.<br><br>숨은 흐트러진다. 맥은 빨라져도 고르다. 몸 안에 셀 것이 하나 더 있었다. 이제 숨이 엉망인 날에도 잴 수 있다.`,
      ng:`맥을 세다가 맥이 너무 빨라 놓쳤다.<br><br>심지가 짧았다. 이쪽이 목을 다 지나기 전에 터졌다. 등 뒤에서 돌과 흙이 쏟아졌다.<br>뒤에 오던 것은 막혔다. 이쪽 다리도 반쯤 묻혔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 심지 없이 던지고 바로 엎드린다.', k:'evade', dc:15,
      ok:`목을 지나서 돌아섰다. 심지를 손톱만큼 남기고 불을 붙여 바로 던졌다. 엎드렸다.<br><br>목 한가운데서 터졌다. 뒤에서 오던 것이 그 앞에서 멈췄다. 연기 너머로 이쪽을 보다 돌아갔다.<br>엎드린 채 손가락을 셌다. 열.<br><br>심지를 안 잴 때는 몸을 잰다. 엎드리는 속도.`,
      ng:`던지는 손이 늦었다.<br><br>손을 떠나자마자 터졌다. 손바닥이 까맣다. 귀가 먹었다.<br>손가락을 셌다. 열. 셋은 한동안 안 움직였다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C', t:'끝 방 — 여러 군데서 다시 나는 것',
  x:`마지막 방에 큰 것이 있다. 한 군데를 터뜨리면 다른 군데가 대신 자란다.<br><br>
    머리를 날리면 등에서 머리가 난다. 등을 날리면 다리에서. 하나씩 날려서는 끝이 없다.<br>
    자라는 데가 넷이다. 머리, 등, 두 다리. 넷이 서로를 대신한다.<br><br>
    화약은 넷 남았다. 공교롭다.`,
  o:[
    { l:'① 꾸러미 넷을 한 숨에 같이 터지게 맞춘다.', k:'break', dc:16, wake:1,
      ok:`심지 넷을 같은 길이로 잘랐다. 손가락 마디로 쟀다. 넷 다 같은 마디.<br><br>동료들이 그것을 붙잡는 동안 넷을 박았다. 머리, 등, 두 다리. 심지 끝을 한데 모아 불 하나로 붙였다. 뛰었다.<br>네 군데가 한 소리로 터졌다. 대신 자랄 데가 없다. 그것이 서 있다가 무너졌다. 다시는 안 났다.<br><br>차례로 터뜨리는 것과 같이 터뜨리는 것은 다르다. 같이 터지면 서로 대신할 틈이 없다. 심지를 고르게 자르는 손이 이제 시간을 자른다.`,
      ng:`한 심지가 반 마디 길었다.<br><br>셋이 터지고 하나가 늦게 터졌다. 그 반 숨 사이에 늦은 다리에서 머리가 났다.<br>새 머리가 이쪽을 물었다. 어깨. 동료들이 떼어 냈다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-18, spirit:-8 } },
    { l:'② 넷을 하나로 묶어 몸통 한가운데 박는다.', k:'break', dc:15,
      ok:`꾸러미 넷을 한 덩이로 묶었다. 크다. 몸통 한가운데 박고 심지를 길게.<br><br>쾅. 방이 흔들렸다. 그것이 반으로 갈라졌다. 반쪽마다 다시 자라기 시작했다. 느리다. 반쪽은 반만큼 느리다.<br>동료들이 반쪽 둘을 쳤다. 자라는 것보다 빨리. 끝났다.<br><br>큰 것은 큰 걸로. 나머지는 동료들 몫이다.`,
      ng:`터지자 그것이 넷으로 갈라졌다. 넷이 다 자란다.<br><br>작은 넷이 방 안을 돌아다닌다. 하나는 이쪽 다리에 붙었다.<br>다들 하나씩 맡아 끝냈다. 오래 걸렸다. 다들 다쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-10 } },
    { l:'③ 동료 넷에게 하나씩 쥐여 주고 신호를 맞춘다.', k:'bond', dc:15,
      ok:`꾸러미를 동료 넷에게 하나씩 쥐여 줬다. 심지는 짧게 잘라 줬다. 이쪽이 손을 들면 붙이고, 내리면 던진다.<br><br>넷이 넷 군데에 섰다. 손을 들었다. 불이 붙었다. 내렸다. 넷이 한꺼번에 날아갔다. 한 소리로 터졌다.<br>그것이 대신할 데를 못 찾고 무너졌다.<br><br>이쪽 손은 비었다. 신호만 했다. 화약을 남한테 맡겨 본 건 처음이다. 다들 손가락이 열이다.`,
      ng:`한 동료가 늦게 던졌다. 손이 떨렸다.<br><br>셋만 같이 터졌다. 넷째 자리에서 머리가 났다. 늦게 던진 꾸러미가 그 머리 옆에서 터졌다.<br>그 동료가 날아갔다. 다쳤다. 이쪽이 맡긴 일이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-10 } }
  ] }

]);

// ------------------------------------------
// 대검사 · 무력
// ------------------------------------------
kJob('greatsword', 'C', [

{ at:'C', t:'통로 — 껍질 두른 것',
  x:`통로 바닥에 무엇이 웅크렸다. 등이 껍질이다. 거북 등 같은데 거북보다 크다.<br><br>
    아까 한 번 쳤다. 칼이 튕겼다. 팔이 저리다. 껍질에는 흰 줄 하나만 남았다.<br>
    큰 칼은 팔로 휘두르면 팔만큼만 벤다. 그걸 알면서도 팔에 힘이 들어갔다.<br><br>
    그것이 머리를 내민다. 이쪽 발목 쪽으로.`,
  o:[
    { l:'① 칼을 높이 들어 무게만으로 떨군다.', k:'break', dc:15, wake:1,
      ok:`칼을 머리 위로 들었다. 거기서 팔에 힘을 뺐다. 손은 자루를 쥐기만 했다.<br><br>칼이 저 혼자 떨어졌다. 이쪽은 떨어지는 길만 열어 줬다. 아까 남은 흰 줄 위로 정확히. 껍질이 소리 없이 갈라졌다. 안쪽까지.<br>그것이 머리를 내민 채 멈췄다.<br><br>칼 무게가 이쪽 힘보다 세다. 알고는 있었다. 오늘 손이 처음으로 칼에게 맡겼다. 맡길 때를 이제 손이 안다.`,
      ng:`힘을 뺀다는 게 손까지 뺐다.<br><br>칼이 떨어지면서 비틀렸다. 껍질 위를 미끄러져 바닥을 쳤다. 손목이 꺾였다.<br>그것이 그 틈에 발목을 물었다. 칼을 끌어 껍질에 대고 겨우 떼어 냈다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-15, mind:-6 } },
    { l:'② 껍질 이음매에 칼끝을 꽂는다.', k:'gaze', dc:14,
      ok:`껍질은 한 장이 아니다. 여러 장이 맞물렸다. 목 뒤 맞물린 자리가 조금 벌어졌다 닫힌다. 숨 쉴 때마다.<br><br>벌어지는 때를 기다려 칼끝을 꽂았다. 깊이. 그것이 떨다가 멎었다.<br>칼을 뽑는 데 두 손이 다 들었다.<br><br>베지 않고 찔렀다. 큰 칼도 끝은 바늘만 하다.`,
      ng:`칼끝이 이음매에 반만 들어가 걸렸다.<br><br>그것이 몸을 틀었다. 칼이 비틀리며 이쪽 손에서 빠졌다. 칼을 등에 꽂은 채 그것이 통로 안쪽으로 기어갔다.<br>쫓아가서 칼을 되찾았다. 정강이를 두 번 물렸다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 사슬에 매달린 것',
  x:`레일에서 사슬이 수십 줄 늘어졌다. 끝마다 갈고리다. 사람 키 높이에서 흔들린다.<br><br>
    그 사이에서 무엇이 갈고리에 매달린 채 온다. 고기 같은데 팔이 있다. 사슬을 이 손 저 손으로 옮겨 잡으며 그네 타듯.<br>
    큰 칼은 자리가 있어야 휘두른다. 여기는 사슬 숲이다. 휘두르면 걸린다.<br><br>
    그것이 다음 사슬을 잡았다. 이쪽 머리 위다.`,
  o:[
    { l:'① 크게 휘둘러 매달린 것을 사슬째 벤다.', k:'break', dc:15,
      doom:{ title:'사슬 숲', what:'칼째 사슬에 감겨 레일 위로 끌려 올라갑니다', dc:15, sec:60,
        text:`크게 휘둘렀다. 그것은 갈랐다. 칼이 지나간 자리의 사슬 셋이 칼날에 감겼다.<br><br>레일이 돌기 시작했다. 사슬이 당긴다. 칼이 위로 끌려간다. 칼을 놓으면 된다. 놓지 않았다.<br>발이 바닥에서 떴다. 칼자루를 쥔 채 레일 쪽으로 올라간다. 위에서 갈고리들이 이쪽으로 기운다.<br><br>큰 칼을 쥔 사람은 칼을 안 놓는다. 그게 이번엔 틀렸다.`,
        dieText:`레일 한 칸에 큰 칼이 매달려 돈다. 사슬 셋에 감겨서.<br><br>칼자루에 손이 아직 붙어 있다. 손만.<br>레일은 그 무게만큼 천천히 돈다. 칼이 지날 때마다 사슬들이 길을 비킨다.` },
      ok:`크게 휘둘렀다. 그것을 갈랐다. 칼이 사슬 셋을 감는 느낌이 왔다. 감기기 직전에 칼을 비틀어 날을 세웠다.<br><br>사슬이 칼에 감기는 대신 끊어졌다. 쇠사슬이 우수수 떨어졌다. 그것도 반씩 떨어졌다.<br>레일이 빈 사슬 몇 줄을 끌고 지나갔다.<br><br>칼날에 사슬 자국이 셋 남았다. 이가 하나 나갔다. 사슬 셋이면 싸다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 무력을 쓴다 — 칼을 세워 사슬을 감고 레일을 멈춘다.', k:'steady', dc:15, cost:{ might:18 },
      ok:`칼을 바닥에 꽂아 세웠다. 지나가는 사슬을 칼에 일부러 감았다. 하나, 둘, 셋. 무력을 다리에 실어 칼을 붙들었다.<br><br>레일이 당긴다. 칼이 휜다. 안 휘었다. 레일이 끽 소리를 내고 섰다. 매달린 것이 멈춘 사슬에서 내려오려고 버둥댄다.<br>멈춰 있는 동안 다들 내려와 그것을 끝냈다.<br><br>칼이 기둥이 됐다. 레일 하나를 세운 기둥이다.`,
      ng:`셋째 사슬이 감길 때 칼이 바닥에서 뽑혔다.<br><br>칼째 끌려갔다. 다섯 걸음. 칼을 끌어안고 버텼다. 사슬이 칼에서 풀리며 등을 쳤다.<br>칼은 지켰다. 등에 사슬 자국이 길게 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6, might:-5 } }
  ] },

{ at:'C2', t:'공방 — 수십 가닥의 줄',
  x:`천장에서 줄이 쏟아지듯 내려온다. 끝마다 사기 인형이 매달렸다. 스무 개쯤.<br><br>
    인형들이 줄에 끌려 이쪽으로 걸어온다. 이를 딱딱 부딪친다. 하나씩 베기엔 너무 많다.<br>
    줄은 위층 한곳에서 내려온다. 내려오면서 퍼진다. 위로 갈수록 모인다.<br><br>
    큰 칼은 한 번에 많이 벤다. 어디를 지나가느냐가 다다.`,
  o:[
    { l:'① 줄이 모이는 높이를 찾아 한 줄로 긋는다.', k:'break', dc:15, wake:1,
      ok:`인형은 안 봤다. 줄을 봤다. 아래는 넓게 퍼지고 위는 모인다. 사람 키 하나 반 높이에서 거의 한 다발이다.<br><br>칼을 어깨 위로 들어 그 높이를 옆으로 그었다. 한 번. 손에 수십 번 끊기는 감촉이 한꺼번에 왔다.<br>인형 스무 개가 한꺼번에 무너졌다. 위층에서 무엇이 뒤로 넘어지는 소리가 났다.<br><br>큰 칼이 지나갈 한 줄. 여럿을 하나로 만드는 높이가 있다. 이제 눈이 칼보다 먼저 그 줄을 긋는다.`,
      ng:`높이를 잘못 봤다. 줄이 아직 퍼져 있는 데를 그었다.<br><br>반만 끊겼다. 남은 인형 열 개가 끊긴 동료들을 넘어 온다. 칼을 다시 들기 전에.<br>셋이 다리에 매달렸다. 떼어 내는 데 한참.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-15, spirit:-8 } },
    { l:'② 칼면으로 인형들을 쓸어낸다.', k:'break', dc:14,
      ok:`칼을 눕혀 면으로 바닥을 쓸었다. 인형들이 볼링 핀처럼 쓰러져 굴렀다. 사기가 깨진다.<br><br>줄이 깨진 인형들을 다시 들어 올린다. 반쪽짜리가 일어선다. 다시 쓸었다. 셋째에 다 가루가 됐다.<br>줄 끝에 철사만 덜렁거린다.<br><br>세 번 쓸었다. 팔이 뻐근하다. 한 번에 됐으면 좋았다.`,
      ng:`쓸어낸 인형들이 줄에 끌려 그대로 다시 왔다. 넘어진 채로 기어서.<br><br>칼을 다시 들 틈이 없다. 기어 온 것들이 장화를 물었다.<br>뒤로 물러서다 작업대에 걸려 넘어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 칼 홈에 자란 것',
  x:`쉬면서 칼을 무릎에 눕혔다. 날을 따라 홈이 하나 길게 파였다. 피가 빠지라고 판 홈이다.<br><br>
    홈에 하얀 것이 줄지어 났다. 솜 같다. 아까 벤 것들에서 옮은 것이다. 홈을 따라 자란다. 자루 쪽으로.<br>
    칼은 대검사의 몸이다. 그 몸에 남의 것이 자란다.<br><br>
    자루까지 오면 손으로 온다.`,
  o:[
    { l:'① 홈을 칼끝으로 하나하나 긁어낸다.', k:'fix', dc:14,
      ok:`작은 칼을 빌려 홈을 따라 긁었다. 자루 쪽부터. 날 쪽으로 몰아냈다.<br><br>하얀 것이 긁힐 때마다 움츠린다. 끝까지 몰아 날 끝에서 털어 냈다. 털어 낸 것은 돌로 짓이겼다.<br>홈이 다시 검다. 칼이 칼 같다.<br><br>밤이 반이 갔다. 칼을 닦는 데 반을 쓰는 사람이 이쪽이다.`,
      ng:`긁는데 하얀 것이 홈 밖으로 넘쳐 날 위로 퍼졌다.<br><br>손등으로 기어 오른다. 털었다. 손등이 가렵다. 하얗게 일어난다.<br>칼은 다 못 닦았다. 홈 끝에 아직 조금 남았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } },
    { l:'② 동료 불에 칼을 내밀어 홈을 지진다.', k:'bond', dc:13,
      ok:`불가에 앉은 동료에게 칼을 내밀었다. 홈을 불에 대 달라고.<br><br>동료가 칼을 받아 불 위로 천천히 지나가게 했다. 무거워서 두 손으로. 홈의 하얀 것이 오그라들며 탔다.<br>칼을 돌려받았다. 따뜻하다.<br><br>남이 이 칼을 들어 본 건 처음이다. 동료가 손목을 주무른다. 무겁다고 한다. 안다.`,
      ng:`동료가 칼을 받다 무게에 놓쳤다. 칼이 불 속으로 떨어졌다.<br><br>꺼내는데 자루가 달아올랐다. 손바닥이 데었다.<br>홈은 깨끗해졌다. 자루에 그을린 자국이 남았다.`,
      win:{ exp:14, hp:8, mind:5 }, lose:{ hp:-10, spirit:-6 } }
  ] },

{ at:'C3', t:'성당 — 좁은 아치 위의 칼',
  x:`아치 위에 섰다. 발 디딜 데가 손바닥 둘 너비다. 양옆은 움푹하고 군데군데 뚫렸다.<br><br>
    앞에서 날개 없는 것이 아치를 타고 온다. 사람만 하다. 발톱으로 회반죽을 움켜쥔다.<br>
    큰 칼은 휘두르면 몸을 끌고 간다. 여기서 끌려가면 구멍이다. 그 아래는 어둠이다.<br><br>
    칼을 들었다. 칼이 벌써 몸을 기울인다.`,
  o:[
    { l:'① 휘두르다 몸이 끌려가기 전에 칼을 세운다.', k:'break', dc:15, wake:1,
      ok:`크게 들어 내리쳤다. 그것 어깨에서 가슴까지. 칼이 계속 가려 한다. 아치 너머 어둠 쪽으로.<br><br>배에 힘을 주고 손목을 꺾었다. 칼이 허공에서 섰다. 몸이 칼을 따라가다 멈췄다. 발끝이 아치 가장자리에 걸려 있었다.<br>그것이 구멍 아래로 떨어졌다. 칼은 이쪽 손에 남았다.<br><br>휘두르는 것보다 멈추는 게 어렵다. 칼 무게를 중간에서 받아 냈다. 이제 칼이 어디서 멈출지를 이쪽이 정한다.`,
      ng:`멈추려 했는데 칼이 이겼다.<br><br>몸이 칼을 따라 돌았다. 발이 아치에서 미끄러졌다. 움푹한 데로 굴러떨어졌다. 구멍 바로 옆이다.<br>그것이 위에서 덮쳤다. 칼을 세워 겨우 막았다. 어깨를 찍혔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 칼을 아치에 꽂아 기둥 삼고 그 옆에서 싸운다.', k:'steady', dc:14,
      ok:`칼을 아치 회반죽에 깊이 꽂았다. 칼이 섰다. 한 손으로 칼을 잡고 몸을 붙였다.<br><br>그것이 덮쳤다. 칼이 있는 쪽은 못 온다. 반대쪽으로 온다. 거기만 보면 된다. 발로 차서 구멍 쪽으로 밀었다.<br>그것이 구멍 가장자리에 매달렸다. 칼을 뽑아 손을 쳤다. 떨어졌다.<br><br>칼을 안 휘두르고 싸웠다. 서 있는 칼도 칼이다.`,
      ng:`꽂은 칼 둘레 회반죽에 금이 갔다.<br><br>칼이 기울었다. 이쪽도 같이 기울었다. 그것이 그 틈에 팔을 찍었다.<br>칼을 뽑아 들고 물러섰다. 금이 아치를 따라 길게 갔다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C4', t:'온실 — 아직 숨 쉬는 정원사',
  x:`화분 사이에 정원사가 누웠다. 몸 절반이 하얗다. 갓이 가슴과 팔을 덮었다.<br><br>
    숨을 쉰다. 눈을 굴린다. 사람 눈이다. 이쪽을 본다. 입이 갓에 덮여 말을 못 한다.<br>
    갓 뿌리는 아직 얕다. 살갗과 갓 사이에 얇은 막이 있다. 그 막 아래가 사람이다.<br><br>
    이 칼은 사람 키만 하다. 지금 벨 것은 손톱 두께다.`,
  o:[
    { l:'① 칼을 눕혀 갓과 살 사이를 한 겹만 저민다.', k:'gaze', dc:16, wake:1,
      ok:`칼을 눕혔다. 날을 살갗과 나란히. 칼끝을 막에 댔다. 무게를 손으로 다 받쳤다. 한 치씩 밀었다.<br><br>갓이 한 장씩 떨어져 나간다. 그 아래 살갗이 분홍이다. 피가 안 난다. 가슴, 팔, 목. 입을 덮은 것까지.<br>정원사가 숨을 크게 들이켰다. 기침을 했다. 운다.<br><br>큰 칼로 한 겹. 무게를 들고 있으면서 무게를 안 쓰는 법을 손이 알았다. 이제 이 칼로 못 할 일이 하나 줄었다.`,
      ng:`셋째 장에서 칼끝이 떨렸다. 막 아래로 들어갔다.<br><br>정원사가 몸을 비틀었다. 피가 났다. 갓들이 피 냄새에 한꺼번에 가루를 뿜었다.<br>물러섰다. 정원사는 숨을 쉬었다. 아까보다 얕게.`,
      win:{ exp:22, dream:3, hp:5 }, lose:{ mind:-10, spirit:-10 } },
    { l:'② 칼면으로 갓을 긁어내고 동료에게 넘긴다.', k:'heal', dc:14,
      ok:`칼면을 갓 위에 대고 긁었다. 갓이 뿌리째는 아니어도 겉은 떨어진다.<br><br>입을 덮은 것부터. 정원사가 숨을 쉰다. 나머지는 치료하는 동료에게 넘겼다. 동료가 작은 칼로 마저 떼어 냈다.<br>정원사는 일어나지 못했다. 그래도 눈을 감고 잤다. 사람처럼.<br><br>칼면은 날보다 넓다. 넓어서 할 수 있는 일이 있다.`,
      ng:`긁는데 갓이 터지며 가루가 얼굴로 왔다.<br><br>기침에 칼이 흔들렸다. 칼면이 정원사 갈비를 눌렀다. 무게가 그대로 실렸다.<br>정원사가 신음했다. 이쪽은 가루를 뱉어 내느라 한참 숨을 못 쉬었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C', t:'불침번 — 칼을 타고 오르는 것',
  x:`잘 때는 칼을 땅에 꽂아 세운다. 다들 그 둘레에 눕는다.<br><br>
    불침번을 서는데 칼에서 소리가 난다. 사각. 사각. 무엇이 칼을 타고 오른다. 손바닥만 한 것. 다리가 많다.<br>
    칼 꼭대기에 오르면 아래가 다 보인다. 누운 사람들 얼굴이.<br><br>
    칼을 뽑으면 소리가 난다. 다들 깬다.`,
  o:[
    { l:'① 칼을 뽑아 한 번에 친다.', k:'break', dc:14,
      ok:`칼자루를 잡고 뽑으며 그대로 휘둘렀다. 칼에 붙어 있던 것이 칼날 끝에서 날아갔다.<br><br>벽에 붙었다가 떨어졌다. 다리를 오그리고 안 움직인다.<br>다들 깼다. 아무 일 없다고 했다. 칼을 다시 꽂았다. 이번엔 칼 밑동에 돌을 둘렀다.<br><br>칼을 세워 두면 오르는 것이 생긴다. 다음부터는 눕혀 둔다.`,
      ng:`뽑는 순간 그것이 칼날을 타고 손으로 내려왔다.<br><br>손목을 물었다. 칼을 떨어뜨렸다. 쿵 소리에 다들 깼다.<br>떼어 낸 것은 이미 다른 사람 얼굴 쪽으로 기어가고 있었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 칼을 살살 기울여 그것을 떨어뜨린다.', k:'fix', dc:14,
      ok:`칼자루를 잡고 아주 천천히 기울였다. 소리 안 나게.<br><br>칼이 비탈이 되자 그것이 미끄러진다. 버틴다. 더 기울였다. 떨어졌다. 아무도 없는 쪽으로.<br>떨어진 것을 장화로 눌렀다. 칼을 바로 세웠다. 아무도 안 깼다.<br><br>칼을 기울이는 것도 칼질이다. 소리 없는 칼질.`,
      ng:`기울이는데 칼 밑동이 흙에서 빠졌다.<br><br>칼이 넘어갔다. 누운 동료 옆에 쾅. 동료가 비명을 지르며 깼다.<br>그것은 그 동료 머리카락 속으로 들어갔다. 꺼내는 데 다들 한참 걸렸다.`,
      win:{ exp:14, dream:1, hp:6 }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C1', t:'도축장 — 고기 벽',
  x:`갈고리에 고기가 너무 빽빽이 걸렸다. 벽 같다. 통로가 막혔다.<br><br>
    고기들이 서로 붙어 자랐다. 이웃한 덩이끼리 살로 이어졌다. 한 덩어리 벽이다.<br>
    큰 칼이면 가른다. 갈라진 자리가 붙기 전에 지나야 한다.<br><br>
    벽 너머에서 칼 가는 소리가 일정하게 난다.`,
  o:[
    { l:'① 무력을 쓴다 — 위에서 아래까지 한 번에 가른다.', k:'break', dc:15, cost:{ might:18 },
      ok:`칼을 머리 위로 들었다. 무력을 등에서 팔로 끌어올렸다. 내리쳤다. 끝까지.<br><br>고기 벽이 위에서 아래까지 갈렸다. 갈린 사이로 사람 하나 지날 틈. 다들 뛰어 지났다. 마지막 사람 등 뒤에서 틈이 붙었다.<br>칼에 묻은 기름을 닦았다. 갈린 덩이 하나가 발밑에 떨어져 있다. 갈고리에서 떨어진 건 안 자란다. 챙겼다.<br><br>한 번에 가르면 붙는 것보다 빠르다.`,
      ng:`칼이 뼈에 걸려 반에서 멈췄다.<br><br>뽑으려는 사이 갈린 자리가 칼을 물고 붙기 시작했다. 칼이 고기 벽에 박혔다. 두 손으로 비틀어 뽑았다.<br>칼에 붉은 실이 감겨 나왔다. 길은 안 났다.`,
      win:{ exp:20, dream:2, item:'짐승 고기' }, lose:{ hp:-12, mind:-8, might:-5 } },
    { l:'② 칼끝으로 갈고리 고리만 끊어 덩이째 떨군다.', k:'gaze', dc:15,
      ok:`벽은 갈고리에 걸려 있다. 고리 하나하나를 봤다. 녹슨 데가 있다.<br><br>칼끝을 위로 올려 녹슨 고리 셋을 끊었다. 벽 한 칸이 통째로 바닥에 떨어졌다. 떨어진 것은 이웃과 이어진 살이 찢어지며 오그라든다.<br>빈 칸으로 지났다.<br><br>매단 것은 매단 데를 끊는다. 고기를 벨 필요가 없었다.`,
      ng:`고리를 끊자 덩이가 이쪽으로 떨어졌다.<br><br>무겁다. 다리를 깔렸다. 떨어진 덩이가 이쪽 다리에 살을 붙이려 한다. 따뜻하다.<br>동료들이 덩이를 굴려 냈다. 다리에 붉은 자국이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } },
    { l:'③ 벽장 쪽으로 돌아 소금을 챙겨 간다.', k:'sense', dc:14,
      ok:`벽을 가르기 전에 옆을 봤다. 통로 옆에 벽장이 있다. 문이 반쯤 열렸다.<br><br>안에 소금 포대가 있다. 굳은 덩이를 칼자루로 깨서 챙겼다. 벽장 뒤판이 헐겁다. 밀자 빠졌다. 고기 벽 너머로 이어진다.<br>한 사람씩 벽장으로 지났다.<br><br>벽을 벨 생각만 하면 문이 안 보인다.`,
      ng:`벽장 안에 무엇이 있었다. 갈고리에 걸린 것. 사람만 하다.<br><br>그것이 눈을 떴다. 문을 닫았다. 문이 밀린다. 칼로 받쳐 막았다.<br>결국 고기 벽을 갈라 지났다. 벽장 문은 계속 밀렸다.`,
      win:{ exp:15, dream:1, item:'소금 덩이' }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 작업대 사이',
  x:`공방이 좁다. 작업대가 빽빽하다. 그 위에 만들다 만 인형들이 누웠다.<br><br>
    등에 멘 칼이 천장 들보에 닿는다. 뽑을 자리가 없다. 휘두를 자리는 더 없다.<br>
    작업대 위 인형들이 하나씩 고개를 든다. 이빨을 넣다 만 입으로.<br><br>
    큰 칼은 자리가 없으면 짐이다.`,
  o:[
    { l:'① 칼을 등에 둔 채 맨손으로 밀치며 지난다.', k:'evade', dc:14,
      ok:`칼은 안 뽑았다. 어깨로 작업대를 밀며 지났다. 일어서는 인형은 손으로 쳐서 떨궜다.<br><br>팔꿈치, 손등, 무릎. 사기는 맞으면 깨진다. 이도 같이 흩어진다.<br>공방을 빠져나왔다. 손등이 여기저기 베였다. 칼은 멀쩡하다.<br><br>칼을 지키느라 몸이 상한다. 늘 그렇다.`,
      ng:`어깨로 밀던 작업대가 넘어졌다. 인형 여럿이 한꺼번에 쏟아졌다.<br><br>발목, 종아리. 칼을 못 뽑으니 손으로 떼어 내야 한다. 하나씩.<br>등의 칼이 들보에 걸려 몸을 못 숙였다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 칼을 짧게 쥐고 창처럼 찌른다.', k:'break', dc:15, wake:1,
      ok:`칼을 등에서 풀어 앞으로 돌렸다. 자루를 놓고 날 밑동 무딘 데를 두 손으로 잡았다. 칼이 반으로 짧아졌다.<br><br>짧아진 칼로 찔렀다. 인형 하나, 둘. 작업대 사이에서도 칼끝이 간다. 휘두르지 않으니 걸릴 것도 없다.<br>일곱을 찌르고 공방을 지났다.<br><br>칼 길이는 쥐는 데서 정해진다. 쥐는 자리를 옮기면 칼이 바뀐다. 이제 좁은 데서도 이 칼이 칼이다.`,
      ng:`날 밑동을 잡은 손이 미끄러졌다. 무딘 데라도 날은 날이다.<br><br>손바닥이 베였다. 피가 칼을 타고 흘렀다. 인형들이 피 냄새에 고개를 돌린다.<br>찌르긴 찔렀다. 다섯. 손바닥이 쓰라리다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C3', t:'성당 — 걷는 종',
  x:`종 하나가 아치 위를 걷는다. 입을 아래로 하고, 그 밑에 다리가 여럿 났다.<br><br>
    걸을 때마다 안에서 추가 흔들려 운다. 낮게. 그 소리에 다리 힘이 빠진다.<br>
    종 쇠는 두껍다. 큰 칼이라도 크게 휘둘러야 들어간다. 크게 휘두르면 몸이 칼을 따라간다. 양옆은 구멍이다.<br><br>
    종이 이쪽을 향해 방향을 틀었다.`,
  o:[
    { l:'① 온 힘으로 크게 휘둘러 종째 가른다.', k:'break', dc:16,
      doom:{ title:'걷는 종', what:'칼에 끌려 아치 구멍 아래로 떨어집니다', dc:16, sec:55,
        text:`크게 휘둘렀다. 칼이 종 어깨를 쳤다. 들어가지 않았다. 튕겼다.<br><br>튕긴 칼이 반대쪽으로 몸을 끌고 갔다. 발이 아치 가장자리를 넘었다. 한 손이 칼자루를 쥐고 한 손이 회반죽을 쥔다. 회반죽이 부서진다.<br>칼을 놓으면 두 손으로 잡을 수 있다. 칼은 안 놓았다.<br><br>종이 위에서 내려다보며 운다. 낮게. 손가락에서 힘이 빠진다.`,
        dieText:`성당 아치 가장자리에 손가락 자국 넷이 회반죽에 파였다.<br><br>떨어지는 소리는 끝까지 안 들렸다. 칼 소리도.<br>걷는 종은 그 자리에서 한참 울었다. 그 뒤로 그 종 소리에 쇠 긁히는 소리가 섞였다.` },
      ok:`크게 휘둘렀다. 칼이 종 어깨를 치고 들어갔다. 종 쇠가 갈리는 소리가 성당을 채웠다.<br><br>칼이 반쯤 들어간 채 몸이 칼을 따라 돌았다. 발이 가장자리에서 멈췄다. 종이 반으로 갈라지며 다리들이 따로따로 버둥댔다. 안의 추가 굴러 구멍 아래로 떨어졌다.<br>칼을 뽑았다. 날이 하얗게 달아올랐다.<br><br>귀가 한참 울렸다. 손바닥이 아직 저리다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 칼면으로 종을 눌러 울림을 죽이고 지난다.', k:'steady', dc:15,
      ok:`종이 다가올 때 칼을 눕혀 종 머리에 면을 댔다. 눌렀다. 칼 무게와 이쪽 무게를 다.<br><br>울림이 칼에 먹혔다. 종이 울려고 떨다가 조용해졌다. 다리들이 버둥대지만 칼에 눌려 못 움직인다.<br>그 옆으로 다들 지나갔다. 마지막에 칼을 떼고 뒷걸음질로 물러났다.<br><br>칼이 울림을 다 받아 손이 덜덜 떨린다. 그래도 다리는 섰다.`,
      ng:`누르는 순간 종이 크게 울었다. 칼이 그 울림을 이쪽 팔로 그대로 넘겼다.<br><br>팔이 마비됐다. 칼이 미끄러졌다. 종이 다리 하나로 이쪽 발목을 감았다.<br>동료들이 끌어냈다. 팔에 감각이 한참 안 돌아왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-10 } }
  ] },

{ at:'C4', t:'온실 — 하얀 장막',
  x:`온실 통로를 균사가 덮었다. 거미줄처럼 촘촘하다. 하얀 장막이 겹겹이다.<br><br>
    장막 너머가 안 보인다. 걸을 때마다 장막이 흔들리며 가루를 턴다.<br>
    큰 칼은 이럴 때 쓰라고 크다. 한 바퀴면 길이 난다. 가루도 한 바퀴만큼 날린다.<br><br>
    장막 가장자리 화단에 약초 같은 잎이 섞여 자란다.`,
  o:[
    { l:'① 무력을 쓴다 — 크게 한 바퀴 돌려 장막을 쓸어 벤다.', k:'break', dc:15, cost:{ might:18 },
      ok:`다들 뒤로 물리고 젖은 천으로 입을 막게 했다. 칼을 낮게 들고 무력을 허리에 실었다. 한 바퀴.<br><br>장막이 둥글게 잘려 떨어졌다. 둘째 겹, 셋째 겹. 세 바퀴에 통로가 열렸다. 가루가 뿌옇게 일었다가 바닥에 내려앉았다.<br>다들 숨을 참고 뛰었다.<br><br>칼끝에 하얀 실이 솜사탕처럼 감겼다. 털어 냈다.`,
      ng:`둘째 바퀴에 칼이 장막에 감겼다. 균사가 칼날을 물었다.<br><br>당기자 장막 전체가 이쪽으로 무너졌다. 하얀 것이 얼굴을 덮었다. 가루를 한 모금 마셨다.<br>동료들이 끌어냈다. 기침이 오래 갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6, might:-5 } },
    { l:'② 칼끝으로 화단 잎을 들춰 약초만 가려 딴다.', k:'sense', dc:14,
      ok:`칼끝으로 잎을 하나씩 들췄다. 손은 안 댔다.<br><br>잎 뒷면에 하얀 점이 없는 것만. 줄기를 꺾으면 쓴 냄새가 나는 것만. 한 줌.<br>약초 사이로 장막이 얇은 데가 보였다. 거기만 칼로 찢고 지났다.<br><br>큰 칼로 잎 하나를 고른다. 다들 이제 신기해하지도 않는다.`,
      ng:`들춘 잎 뒷면에 갓이 붙어 있었다. 칼끝에 터졌다.<br><br>가루가 칼을 타고 손으로 왔다. 손등이 가렵다.<br>딴 것은 다 버렸다. 뭐가 묻었는지 모른다.`,
      win:{ exp:15, dream:1, item:'약초 뭉치' }, lose:{ hp:-10, spirit:-8 } },
    { l:'③ 장막 사이 빈틈을 따라 몸을 비틀어 지난다.', k:'evade', dc:15,
      ok:`칼을 등에서 풀어 앞으로 안았다. 장막 사이 빈틈을 따라 몸을 비틀었다.<br><br>칼이 장막에 안 닿게. 몸이 장막에 안 닿게. 천천히. 다들 이쪽 발자국을 따라왔다.<br>통로를 빠져나오자 다들 숨을 몰아쉬었다. 가루는 거의 안 날렸다.<br><br>칼을 안고 춤추듯 걸었다. 다시는 하기 싫다.`,
      ng:`칼끝이 장막 하나를 건드렸다.<br><br>장막들이 줄줄이 흔들리며 가루를 쏟았다. 다들 기침을 했다.<br>눈이 따갑다. 손등이 하얗게 일어난다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 칼날에 비친 것',
  x:`쉬면서 칼을 닦았다. 날이 거울처럼 빛난다.<br><br>
    날에 이쪽 얼굴이 비친다. 그 뒤로 동료들이 비친다. 셋이 누웠다.<br>
    고개를 돌려 보니 둘이 누웠다. 칼날 속에는 셋이다.<br><br>
    칼날 속 셋째가 눈을 떴다.`,
  o:[
    { l:'① 칼날을 거울 삼아 셋째 자리를 찾는다.', k:'sense', dc:15,
      ok:`칼을 천천히 기울이며 비친 자리를 맞췄다. 셋째는 둘 사이, 천장 그늘 아래다.<br><br>고개를 들었다. 천장에 무엇이 붙어 있다. 사람 모양으로. 누운 자세 그대로 거꾸로.<br>칼끝을 들어 올려 찔렀다. 그것이 떨어져 두 사람 사이에 눕듯 떨어졌다. 다들 깼다.<br><br>칼은 앞만 보는 줄 알았다. 닦아 두면 뒤도 본다.`,
      ng:`칼을 기울이다 날에 비친 셋째가 사라졌다.<br><br>찾는 사이 목덜미에 무엇이 떨어졌다. 차고 축축하다.<br>털어 냈다. 천장으로 올라갔다. 그 뒤로 아무도 천장 밑에서 안 잤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } },
    { l:'② 칼을 눕혀 덮고 아침까지 안 본다.', k:'steady', dc:14,
      ok:`칼을 엎어 날이 땅을 보게 했다. 비치는 게 없다.<br><br>앉아서 아침까지 기다렸다. 아무 일도 없었다. 아침에 다들 일어났다. 둘이.<br>칼을 들어 다시 봤다. 이쪽 얼굴 뒤로 둘. 셋째는 없다.<br><br>안 보는 것도 버티는 법이다. 밤이 길었다.`,
      ng:`엎어 둔 칼 밑에서 사각사각 소리가 났다.<br><br>칼을 들어 보니 날 밑 흙에 손가락 자국이 줄지어 있다. 날을 긁은 자국.<br>날에 긁힌 금이 셋 생겼다. 그 금에도 무엇이 비친다.`,
      win:{ exp:14, dream:1, mind:6 }, lose:{ mind:-8, spirit:-10 } }
  ] },

{ at:'C1', t:'도축장 — 다시 붙는 토막',
  x:`도마 위에서 토막이 꿈틀댄다. 아까 벤 것이다. 둘로 갈랐는데 서로를 향해 기어간다.<br><br>
    갈린 자리에서 붉은 실이 나와 마주 닿으려 한다. 닿으면 붙는다. 붙으면 다시 일어난다.<br>
    이 아래에서는 갈라도 안 끝난다. 대검사의 칼이 처음 겪는 일이다.<br><br>
    다른 토막들도 레일 위에서 꿈틀대기 시작했다.`,
  o:[
    { l:'① 살결을 따라 다시 벤다 — 붙을 실을 남기지 않게.', k:'break', dc:15, wake:1,
      ok:`토막 단면을 봤다. 살에 결이 있다. 나무처럼. 아까는 결을 가로질러 벴다. 가로지른 결은 실을 뻗어 다시 찾는다.<br><br>결을 따라 다시 내렸다. 결대로 갈라진 살은 실을 안 뻗는다. 그대로 벌어져 누웠다. 다시 기지 않는다.<br>레일 위 토막들도 결을 따라 하나씩 벴다. 조용해졌다.<br><br>벤다고 다 끝나는 게 아니다. 어느 쪽으로 베느냐다. 이제 칼보다 결이 먼저 보인다.`,
      ng:`결을 따라 벤다는 게 결을 잘못 읽었다.<br><br>토막이 셋이 됐다. 셋이 다 실을 뻗는다. 하나가 칼날을 타고 손으로 기어왔다.<br>털어 냈다. 손등에 붉은 실이 한 가닥 남았다. 뽑았다. 뿌리가 있었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 칼면으로 토막을 멀리 쳐 서로 못 찾게 한다.', k:'break', dc:14,
      ok:`칼을 눕혀 토막 하나를 면으로 쳐 날렸다. 통로 끝까지. 다른 하나는 반대쪽으로.<br><br>둘이 서로를 찾느라 실을 뻗는다. 닿지 않는다. 너무 멀다.<br>레일 위 것들도 같은 식으로 흩었다. 다 흩어 놓고 지났다.<br><br>언젠가 서로 찾을 것이다. 그때 이쪽은 없다.`,
      ng:`쳐 낸 토막이 벽에 맞고 튕겨 돌아왔다. 다른 토막 바로 옆에.<br><br>둘이 붙었다. 하나가 됐다. 일어섰다. 아까보다 조금 크다.<br>다시 베었다. 이번엔 셋이 됐다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } },
    { l:'③ 소금 포대를 찢어 토막 사이에 쏟는다.', k:'fix', dc:14,
      ok:`벽 밑 소금 포대를 칼끝으로 찢었다. 굳은 소금을 깨서 두 토막 사이에 두껍게 깔았다.<br><br>붉은 실이 소금에 닿자 오그라든다. 넘어오지 못한다. 토막들이 소금 둑 양쪽에서 꿈틀대다 멈췄다.<br>남은 소금은 챙겼다.<br><br>칼로 못 끝내는 것은 칼 말고 다른 걸로 끝낸다.`,
      ng:`소금이 모자랐다. 둑에 틈이 났다.<br><br>실 하나가 틈을 찾아 넘어갔다. 붙었다. 일어섰다.<br>다시 베었다. 소금은 다 썼다.`,
      win:{ exp:15, dream:1, item:'소금 덩이' }, lose:{ mind:-10, spirit:-6 } }
  ] },

{ at:'C2', t:'공방 — 천장 너머',
  x:`공방 천장 들보 사이로 줄이 수백 가닥 올라간다. 위층으로.<br><br>
    위에서 발소리가 난다. 이쪽이 움직이면 위도 움직인다. 이쪽 바로 위에서 멈춘다.<br>
    계단은 멀다. 거기도 줄이 걸렸을 것이다.<br><br>
    천장은 나무다. 얇다. 큰 칼이면 들어간다.`,
  o:[
    { l:'① 무력을 쓴다 — 발소리 바로 밑에서 칼을 위로 찔러 올린다.', k:'break', dc:16, cost:{ might:20 },
      ok:`발소리가 멈춘 자리 바로 밑에 섰다. 칼을 세워 두 손으로 쥐고 무력을 다리에서 팔로 끌어올렸다.<br><br>찔러 올렸다. 나무 천장을 뚫고 위로. 칼끝에 무엇이 걸렸다. 위에서 비명. 줄 수백 가닥이 한꺼번에 축 늘어졌다.<br>칼을 뽑자 천장 구멍에서 하얀 가루와 사기 조각이 쏟아졌다.<br><br>위에 있는 것도 칼이 닿으면 칼 밑이다.`,
      ng:`찌르는 순간 위의 것이 비켰다. 칼이 허공을 뚫었다.<br><br>칼이 천장에 박혀 안 빠진다. 매달리듯 당기는 사이 줄이 내려와 손목을 감았다.<br>동료가 줄을 끊고 둘이 칼을 뽑았다. 손목에 줄 자국이 깊다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-8, might:-5 } },
    { l:'② 줄이 덜 걸린 쪽을 찾아 계단으로 돌아간다.', k:'sense', dc:14,
      ok:`줄이 올라가는 방향을 봤다. 다 한쪽으로 쏠렸다. 반대쪽 구석은 줄이 드물다.<br><br>그쪽 벽을 따라 계단에 닿았다. 줄이 세 가닥뿐이다. 칼끝으로 끊었다.<br>위층 문 앞까지 소리 없이 올라갔다.<br><br>위의 것은 아직 공방 한가운데 위에 서 있다. 이쪽이 아직 거기 있는 줄 안다.`,
      ng:`드문 쪽이라고 간 데에 줄이 안 보이게 걸려 있었다.<br><br>발목에 걸렸다. 위에서 알았다. 계단 위에서 인형이 줄줄이 굴러 내려왔다.<br>칼을 휘두를 자리가 없다. 칼등으로 막으며 물러났다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 칼 지붕',
  x:`쉬는 자리 천장에서 무엇이 떨어진다. 한 방울씩. 끈적하고 미지근하다.<br><br>
    떨어진 자리마다 바닥 돌이 조금 녹았다. 누운 동료 소매에 한 방울. 천이 삭았다.<br>
    자리를 옮길 데가 없다. 사방 천장이 다 그렇다.<br><br>
    칼은 넓다. 사람 셋이 그 밑에 누울 만큼은.`,
  o:[
    { l:'① 칼을 눕혀 받쳐 들고 동료들 위를 덮는다.', k:'steady', dc:15,
      ok:`칼을 돌 두 개에 걸쳐 눕혔다. 날을 위로. 면이 지붕이 됐다. 셋이 그 밑에 누웠다.<br><br>방울이 칼면에 떨어진다. 똑. 똑. 칼은 안 녹는다. 쇠는 이것보다 질기다.<br>이쪽은 칼 옆에 앉아 밤새 칼면을 닦았다. 쌓이지 않게.<br><br>칼 지붕 밑에서 다들 잤다. 칼이 오늘 처음으로 아무것도 안 베었다.`,
      ng:`칼을 걸친 돌 하나가 녹아 기울었다.<br><br>칼이 미끄러졌다. 칼면에 고인 것이 한꺼번에 누운 동료 다리로 쏟아졌다.<br>바지가 녹고 살갗이 붉어졌다. 다들 깼다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-10, spirit:-8 } },
    { l:'② 떨어뜨리는 것을 찾아 칼끝으로 찌른다.', k:'break', dc:15,
      ok:`방울이 떨어지는 자리를 이었다. 한 줄로 움직인다. 천장을 기어가는 무엇이 침을 흘리는 것이다.<br><br>줄 끝을 보고 칼끝을 올려 찔렀다. 천장에서 무엇이 떨어졌다. 개만 하다. 입이 둥글다. 그 입에서 아직 방울이 흐른다.<br>칼끝으로 눌러 끝냈다. 방울이 멎었다.<br><br>칼끝이 조금 삭았다. 갈면 된다.`,
      ng:`찌른 데가 줄 끝이 아니었다. 천장 돌만 찔렀다.<br><br>그것이 놀라 한꺼번에 흘렸다. 이쪽 어깨와 목덜미로.<br>살갗이 화끈거린다. 물로 씻었다. 오래 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
  ] },

{ at:'C3', t:'성당 — 입이 많은 성가대석',
  x:`성가대석이 거꾸로 매달려 발밑 가까이까지 내려왔다. 난간 너머로 얼굴들이 빽빽하다.<br><br>
    얼굴마다 입이 여럿이다. 다 노래한다. 노래가 몸을 누른다. 어깨가 내려앉는다. 등의 칼이 두 배로 무겁다.<br>
    난간은 나무다. 그 위에 성가대석 전체가 걸렸다.<br><br>
    칼 무게가 이쪽 무릎을 꺾으려 한다.`,
  o:[
    { l:'① 무력을 쓴다 — 난간 기둥을 가로로 벤다.', k:'break', dc:15, cost:{ might:20 },
      ok:`칼을 내렸다. 무거운 채로. 무력을 허리에 실어 가로로 그었다.<br><br>난간 기둥 셋이 한꺼번에 잘렸다. 성가대석이 기울었다. 노래가 높아졌다가 비명이 됐다. 기운 쪽부터 얼굴들이 아치 구멍 아래로 쏟아졌다.<br>노래가 멎었다. 칼이 다시 제 무게로 돌아왔다.<br><br>무거울 때 한 번 더 드는 것. 오늘은 그걸로 됐다.`,
      ng:`그었는데 칼이 노래에 눌려 반만 갔다.<br><br>기둥 하나만 잘렸다. 성가대석이 조금 기울어 노래가 이쪽 쪽으로 쏟아졌다. 무릎이 꺾였다.<br>칼을 짚고 겨우 섰다. 동료들이 양옆에서 끌어 지났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-12, spirit:-8, might:-5 } },
    { l:'② 칼을 꽂아 짚고 노래가 지날 때까지 버틴다.', k:'steady', dc:14,
      ok:`칼을 아치에 꽂고 두 손으로 자루를 짚었다. 칼이 지팡이가 됐다.<br><br>노래가 누른다. 칼이 받는다. 무릎이 꺾이려 할 때마다 칼에 기댔다. 동료들도 칼 둘레에 모여 서로 어깨를 붙잡았다.<br>노래가 숨을 고르는 틈에 다 같이 걸었다. 칼을 뽑아 다시 꽂고, 걷고.<br><br>무거운 칼이 오늘은 짐이 아니라 기둥이었다.`,
      ng:`칼을 짚었는데 칼이 노래에 같이 눌려 아치에 깊이 박혔다.<br><br>뽑을 수가 없다. 칼을 두고 갈 수는 없다. 노래 속에서 한참 칼을 뽑았다.<br>뽑았을 때 귀에서 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-10 } }
  ] },

{ at:'C4', t:'온실 — 칼을 삼키는 덩이',
  x:`통로 한가운데 하얀 덩이가 자랐다. 사람 둘 크기. 겉이 부드럽고 축축하다.<br><br>
    덩이가 숨을 쉰다. 쉴 때마다 표면에 얼굴 같은 굴곡이 떠올랐다 가라앉는다. 여럿.<br>
    덩이 너머로 길이 있다. 돌아갈 데는 없다.<br><br>
    큰 칼이면 한가운데를 뚫을 수 있다. 뚫리는 게 아니라 들어가는 거라면 이야기가 다르다.`,
  o:[
    { l:'① 한가운데에 칼을 끝까지 박아 넣는다.', k:'break', dc:15,
      doom:{ title:'하얀 덩이', what:'칼째 덩이 속으로 끌려 들어갑니다', dc:15, sec:60,
        text:`칼을 두 손으로 쥐고 한가운데로 밀어 넣었다. 들어간다. 너무 쉽게.<br><br>칼이 자루까지 들어갔다. 손이 덩이에 닿았다. 손이 붙었다. 덩이가 칼을 삼키듯 이쪽 팔을 당긴다. 팔꿈치까지 들어갔다.<br>칼을 놓으면 팔은 빠질지도 모른다. 칼을 놓지 않았다.<br><br>덩이 겉에 새 얼굴 굴곡이 떠올랐다. 이쪽 얼굴 모양이다.`,
        dieText:`하얀 덩이는 그 뒤로 조금 커졌다.<br><br>가운데에서 쇠막대 하나가 비죽 나와 있다. 칼자루 끝이다.<br>덩이가 숨 쉴 때마다 그 자루가 아주 조금 흔들린다. 쥐고 있는 무엇이 있는 것처럼.` },
      ok:`칼을 두 손으로 쥐고 한가운데로 밀어 넣었다. 너무 쉽게 들어간다. 자루 한 뼘 앞에서 멈추고 비틀었다.<br><br>덩이 속에서 무엇이 갈렸다. 단단한 것. 심이다. 덩이가 한꺼번에 오그라들었다. 얼굴 굴곡들이 일그러지며 가라앉았다.<br>칼을 뽑았다. 하얀 것이 날에 덕지덕지 붙어 나왔다. 덩이가 무너져 길이 났다.<br><br>손이 덩이에 닿기 한 뼘 전이었다. 그 한 뼘을 오래 기억할 것이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 칼끝만 넣어 휘저어 심을 찾고 뺀다.', k:'steady', dc:15,
      ok:`칼끝만 한 자쯤 넣었다. 휘저었다. 부드럽다. 더 넣었다. 휘저었다.<br><br>칼끝에 단단한 게 걸렸다. 거기서 멈추고 칼을 위로 젖혔다. 심이 덩이 밖으로 들려 나왔다. 덩이가 쭈그러들었다.<br>칼을 뺐다. 칼끝 한 자가 하얗다. 닦았다.<br><br>깊이 넣을수록 깊이 잡힌다. 얕게 넣고 길게 젓는다.`,
      ng:`휘젓는 사이 덩이가 칼끝을 물었다. 안 빠진다.<br><br>당겼다. 덩이가 칼을 따라 이쪽으로 늘어난다. 표면 얼굴들이 이쪽을 향한다.<br>동료들이 같이 당겨 뽑았다. 칼에 하얀 것이 엉겨 붙어 무게가 두 배다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C', t:'통로 — 낮은 천장',
  x:`통로 천장이 낮아졌다. 허리를 숙여야 한다. 칼은 등에서 풀어 손에 들었다.<br><br>
    앞에서 무엇이 온다. 네 발로. 천장이 낮은 건 저것한테는 아무 상관 없다.<br>
    큰 칼은 휘두를 수 없다. 들 수도 없다. 낮게 내밀 수는 있다.<br><br>
    그것이 이쪽 숨소리를 듣고 빨라졌다.`,
  o:[
    { l:'① 칼을 창처럼 앞으로 밀어 낸다.', k:'break', dc:15,
      ok:`칼을 바닥에 거의 붙여 낮게 쥐고 앞으로 밀었다. 칼끝이 앞을 막는다.<br><br>그것이 뛰어들다 칼끝에 걸렸다. 걸린 채로 밀었다. 칼 무게에 이쪽 몸무게까지 실어 벽까지.<br>그것이 벽과 칼 사이에서 버둥대다 멎었다.<br><br>큰 칼은 휘두르는 것이라고 다들 생각한다. 이쪽도 그렇게 생각했었다.`,
      ng:`칼을 밀었는데 그것이 칼 밑으로 기어 들어왔다.<br><br>칼이 너무 길다. 거둘 수가 없다. 그것이 손목을 물었다.<br>칼을 놓고 맨손으로 떼어 냈다. 칼은 바닥에 떨어진 채 길을 막았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-15, spirit:-6 } },
    { l:'② 칼을 내려놓고 칼 위에 서서 받는다.', k:'evade', dc:14,
      ok:`칼을 바닥에 눕혔다. 그 위에 한 발을 올렸다. 그것이 뛰어오르면 칼이 이쪽 발밑을 받친다.<br><br>그것이 다리를 물려 덤볐다. 칼을 밟은 발로 몸을 틀어 피했다. 그것이 칼날 위에 떨어졌다. 날 위로. 제 무게로.<br>그것이 비명을 지르며 물러났다. 다리 하나를 절며.<br><br>칼을 안 들고 칼로 이겼다. 어색하다.`,
      ng:`칼 위에 올린 발이 미끄러졌다. 쇠는 미끄럽다.<br><br>엉덩이를 찧었다. 그것이 그 위로 덮쳤다. 팔로 얼굴을 막았다. 팔뚝을 물렸다.<br>동료들이 떼어 냈다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'통로 — 끊이지 않는 것들',
  x:`작은 것들이 끝도 없이 나온다. 벽 틈에서, 바닥 구멍에서.<br><br>
    하나 베면 둘이 온다. 칼을 들 때마다 팔이 무겁다. 칼을 들었다 내렸다 하는 사이에 다음 것이 붙는다.<br>
    큰 칼은 한 번 들면 내리기까지 길다. 그 사이가 빈다.<br><br>
    팔이 떨린다. 또 온다.`,
  o:[
    { l:'① 칼을 멈추지 않고 몸 둘레로 돌린다.', k:'break', dc:15, wake:1,
      ok:`칼을 들었다 내리지 않았다. 내려오는 칼을 그대로 옆으로 흘려 다시 올렸다. 몸 둘레로 큰 원을 그렸다. 멈추지 않고.<br><br>칼이 제 무게로 돈다. 이쪽은 방향만 틀어 준다. 원 안으로 들어오는 것은 다 칼에 닿았다. 들고 내리는 사이가 없어졌다.<br>스무 번을 돌고 멈췄다. 발밑에 작은 것들이 흩어져 있다. 팔이 아까보다 덜 떨린다.<br><br>들어 올리는 데 쓰던 힘을 칼이 대신 냈다. 칼이 도는 동안은 칼이 쉰다. 이쪽도 쉰다. 이제 칼 무게로 오래 버틸 수 있다.`,
      ng:`셋째 바퀴에서 칼이 벽에 걸렸다. 원이 끊겼다.<br><br>칼이 멈춘 순간 다들 몰려왔다. 다리에 셋, 허리에 하나.<br>칼을 버리듯 놓고 떼어 냈다. 다시 들 힘이 없다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 칼을 세워 등 뒤를 막고 동료와 등을 맞댄다.', k:'steady', dc:14,
      ok:`동료와 등을 맞댔다. 칼을 세워 두 사람 옆을 막았다.<br><br>이쪽은 앞만, 동료는 뒤만. 칼은 휘두르지 않고 짧게 찍었다. 오는 것만.<br>한참 뒤 틈에서 나오는 것이 멎었다. 등이 땀으로 붙었다.<br><br>큰 칼은 혼자 휘두를 때 크다. 둘이면 칼이 반만 일해도 된다.`,
      ng:`등을 맞댄 동료가 먼저 무너졌다. 다리를 물렸다.<br><br>등 뒤가 비었다. 칼을 돌릴 틈도 없이 등을 긁혔다.<br>동료를 업고 물러났다. 칼을 끌면서.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C', t:'끝 방 — 껍질이 다시 자라는 것',
  x:`마지막 방에 큰 것이 버티고 섰다. 온몸에 껍질이 겹겹이다.<br><br>
    한 겹을 깨면 다음 겹이 나온다. 깨진 겹 밑에서 새 겹이 자란다. 숨 열 번이면 다시 덮인다.<br>
    대검사의 칼은 한 번에 깊이 간다. 겹이 다 열린 순간이 있다면 거기다.<br><br>
    동료들이 껍질을 깨기 시작했다. 한 겹씩.`,
  o:[
    { l:'① 칼을 높이 들고 겹이 다 열리는 순간을 기다린다.', k:'break', dc:16, wake:1,
      ok:`칼을 머리 위로 들고 섰다. 휘두르지 않았다. 동료들이 깨는 걸 봤다.<br><br>한 겹, 두 겹. 다시 자란다. 동료들이 같은 자리를 계속 깼다. 넷째 겹이 깨지는 순간 아래가 붉었다. 살이다. 다섯 숨 뒤면 덮인다.<br>내렸다. 한 번. 칼이 붉은 데로 들어가 끝까지 갔다. 그것이 무릎을 꿇었다. 새 겹이 더는 안 자랐다.<br><br>든 채로 오래 기다렸다. 팔이 안 떨렸다. 칼을 든 채 기다리는 것도 칼질이다. 이제 칼이 내려갈 때를 칼이 아니라 눈이 정한다.`,
      ng:`기다리다 팔이 먼저 떨렸다. 칼이 일찍 내려갔다.<br><br>셋째 겹에 맞았다. 칼이 튕겼다. 그것이 돌아서 이쪽을 쳤다. 칼로 막았다. 칼째 날아갔다.<br>벽에 등을 부딪쳤다. 그것 등에 새 겹이 덮였다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-18, spirit:-8 } },
    { l:'② 무력을 전부 실어 겹째 내리찍는다.', k:'break', dc:15, cost:{ might:25 },
      ok:`기다리지 않았다. 무력을 남김없이 끌어올렸다. 칼을 들어 그것 어깨에 내리찍었다.<br><br>겹 넷이 한꺼번에 깨졌다. 칼이 살까지 갔다. 다 자라기 전에 다시 들어 같은 자리에 내리찍었다.<br>그것이 주저앉았다. 깨진 겹 사이로 새 겹이 반쯤 자라다 멈췄다.<br><br>무력이 바닥이다. 팔이 칼을 못 든다. 칼은 그것 어깨에 박힌 채로 서 있다.`,
      ng:`겹 셋까지 깨졌다. 넷째에서 칼이 멈췄다.<br><br>박힌 칼을 뽑는 사이 깨진 겹이 칼 둘레로 다시 자랐다. 칼이 그것 어깨에 물렸다.<br>그것이 몸을 털었다. 칼째 이쪽이 날아갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-8, might:-5 } },
    { l:'③ 칼을 눕혀 동료들 앞을 막고 칠 틈을 지킨다.', k:'bond', dc:15,
      ok:`그것이 휘두르는 팔 앞에 칼을 눕혀 세웠다. 칼면이 방패다.<br><br>쾅. 팔이 칼을 쳤다. 버텼다. 그 뒤에서 동료들이 깼다. 한 겹, 두 겹. 다시 쾅. 버텼다.<br>동료 하나가 넷째 겹 밑 살을 찔렀다. 그것이 무너졌다.<br><br>오늘 이 칼은 아무것도 안 벴다. 다 막았다. 칼면에 그것 주먹 자국이 셋.`,
      ng:`셋째 쾅에 칼이 손에서 밀려 났다.<br><br>칼면이 이쪽 이마를 쳤다. 눈앞이 하얗다. 그것 팔이 다음으로 동료 쪽으로 갔다.<br>동료가 굴러 피했다. 둘 다 바닥에서 한참 못 일어났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-6 } }
  ] }

]);
